 drop constraint \\"spec_section_parent_section_id_fkey\\"","alter table \\"public\\".\\"spec_section\\" drop constraint \\"spec_section_section_name_category_id_key\\"","drop view if exists \\"public\\".\\"v_still_image_recording_pixels_grid\\"","alter table \\"public\\".\\"brand\\" drop constraint \\"brand_pkey\\"","alter table \\"public\\".\\"product\\" drop constraint \\"product_pkey\\"","alter table \\"public\\".\\"product_category\\" drop constraint \\"product_category_pkey\\"","alter table \\"public\\".\\"product_spec\\" drop constraint \\"product_spec_pkey\\"","alter table \\"public\\".\\"product_spec_matrix\\" drop constraint \\"product_spec_matrix_pkey\\"","alter table \\"public\\".\\"spec_definition\\" drop constraint \\"spec_definition_pkey\\"","alter table \\"public\\".\\"spec_mapping\\" drop constraint \\"spec_mapping_pkey\\"","alter table \\"public\\".\\"spec_section\\" drop constraint \\"spec_section_pkey\\"","drop index if exists \\"public\\".\\"brand_name_key\\"","drop index if exists \\"public\\".\\"brand_pkey\\"","drop index if exists \\"public\\".\\"brand_slug_key\\"","drop index if exists \\"public\\".\\"idx_product_brand\\"","drop index if exists \\"public\\".\\"idx_product_category\\"","drop index if exists \\"public\\".\\"idx_product_raw_data\\"","drop index if exists \\"public\\".\\"idx_product_slug\\"","drop index if exists \\"public\\".\\"idx_product_spec_definition\\"","drop index if exists \\"public\\".\\"idx_product_spec_numeric\\"","drop index if exists \\"public\\".\\"idx_product_spec_product\\"","drop index if exists \\"public\\".\\"idx_spec_mapping_pattern\\"","drop index if exists \\"public\\".\\"product_category_pkey\\"","drop index if exists \\"public\\".\\"product_category_slug_key\\"","drop index if exists \\"public\\".\\"product_pkey\\"","drop index if exists \\"public\\".\\"product_slug_key\\"","drop index if exists \\"public\\".\\"product_spec_matrix_pkey\\"","drop index if exists \\"public\\".\\"product_spec_matrix_product