t_id_fkey\\" FOREIGN KEY (product_id) REFERENCES public.product(id) ON DELETE CASCADE not valid","alter table \\"public\\".\\"product_spec_matrix\\" validate constraint \\"product_spec_matrix_v2_product_id_fkey\\"","alter table \\"public\\".\\"product_spec_matrix\\" add constraint \\"product_spec_matrix_v2_product_id_spec_definition_id_dims_key\\" UNIQUE using index \\"product_spec_matrix_v2_product_id_spec_definition_id_dims_key\\"","alter table \\"public\\".\\"product_spec_matrix\\" add constraint \\"product_spec_matrix_v2_spec_definition_id_fkey\\" FOREIGN KEY (spec_definition_id) REFERENCES public.spec_definition(id) ON DELETE CASCADE not valid","alter table \\"public\\".\\"product_spec_matrix\\" validate constraint \\"product_spec_matrix_v2_spec_definition_id_fkey\\"","alter table \\"public\\".\\"spec_definition\\" add constraint \\"spec_definitions_category_id_fkey\\" FOREIGN KEY (category_id) REFERENCES public.product_category(id) not valid","alter table \\"public\\".\\"spec_definition\\" validate constraint \\"spec_definitions_category_id_fkey\\"","alter table \\"public\\".\\"spec_definition\\" add constraint \\"spec_definitions_normalized_key_key\\" UNIQUE using index \\"spec_definitions_normalized_key_key\\"","alter table \\"public\\".\\"spec_definition\\" add constraint \\"spec_definitions_section_id_fkey\\" FOREIGN KEY (section_id) REFERENCES public.spec_section(id) not valid","alter table \\"public\\".\\"spec_definition\\" validate constraint \\"spec_definitions_section_id_fkey\\"","alter table \\"public\\".\\"spec_mapping\\" add constraint \\"spec_mappings_spec_definition_id_fkey\\" FOREIGN KEY (spec_definition_id) REFERENCES public.spec_definition(id) not valid","alter table \\"public\\".\\"spec_mapping\\" validate constraint \\"spec_mappings_spec_definition_id_fkey\\"","alter table \\"public\\".\\"spec_section\\" add constraint \\"spec_sections_category_id_fkey\\" FOREIGN KEY (category_id) REFERENCES public.product_category(id) not valid","alter table \\"public\\".\\"spec_section\\" validate constraint \\"spec_sections_category_id_fkey\\"","alter table \\"public\\".\\"spec_section\\" add constraint \\"spec_sections_parent_section_id_fkey\\" FOREIGN KEY (parent_section_id) REFERENCES public.spec_section(id) not valid","alter table \\"public\\".\\"spec_section\\" validate constraint \\"spec_sections_parent_section_id_fkey\\"","alter table \\"public\\".\\"spec_section\\" add constraint \\"spec_sections_section_name_category_id_key\\" UNIQUE using index \\"spec_sections_section_name_category_id_key\\"","CREATE TRIGGER update_products_updated_at BEFORE UPDATE ON public.product FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()"}	remote_schema
20251228000000	{"-- Product Documents / Assets\n-- Stores discovered PDF URLs (spec sheets, manuals, etc.)\n\n-- Supabase-friendly UUID generator\nCREATE EXTENSION IF NOT EXISTS \\"pgcrypto\\"","CREATE TABLE IF NOT EXISTS product_document (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n\n    -- Optional FK (can be filled later once product exists)\n    product_id UUID REFERENCES product(id) ON DELETE CASCADE,\n\n    -- Helpful denormalized identifiers (useful before product exists)\n    brand_slug TEXT,\n    product_type TEXT,\n    product_slug TEXT,\n\n    document_kind TEXT NOT NULL, -- e.g. 'technical_specs_pdf'\n    title TEXT,\n    url TEXT NOT NULL,\n    source_url TEXT, -- product page where the document link was found\n\n    status TEXT NOT NULL DEFAULT 'discovered', -- discovered, downloaded, parsed, failed\n    discovered_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    downloaded_at TIMESTAMP WITH TIME ZONE,\n    local_path TEXT,\n\n    raw_metadata JSONB,\n\n    CHECK (product_id IS NOT NULL OR product_slug IS NOT NULL),\n    UNIQUE (product_slug, document_kind, url)\n)","CREATE INDEX IF NOT EXISTS idx_product_document_product_id ON product_document(product_id)","CREATE INDEX IF NOT EXISTS idx_product_document_product_slug ON product_document(product_slug)","CREATE INDEX IF NOT EXISTS idx_product_document_kind ON product_document(document_kind)","CREATE INDEX IF NOT EXISTS idx_product_document_url ON product_document(url)"}	add_product_document
20251228002000	{"-- Seed migration (idempotent): Canon camera mapping coverage for Canon section headings.\n-- Goal: reduce `unmapped` from HTML extractions by adding context-specific label variants.\n\nDO $$\nBEGIN\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT\n    sd.id,\n    v.extraction_pattern,\n    v.context_pattern,\n    v.priority,\n    v.notes\n  FROM (\n    VALUES\n      -- Canon uses section \\"Type\\" for many Tier-1 fields.\n      ('body_type',        '^type$',                               '^type$',              90, 'Canon: body type label under Type section'),\n      ('image_processor',  'image\\\\\\\\s*processor|digic',             '^type$',              90, 'Canon: image processor under Type section'),\n      ('storage_types',    'recording\\\\\\\\s*media|card\\\\\\\\s*slots?|memory\\\\\\\\s*card', '^type$', 90, 'Canon: recording media under Type section'),\n      ('lens_mount',       'lens\\\\\\\\s*mount|mount$',                 '^type$',              95, 'Canon: lens mount under Type section'),\n\n      -- Canon Image Sensor section: key \\\\\\"Type\\\\\\" is sensor type; also uses \\\\\\"Screen Size\\\\\\" for sensor dimensions.\n      ('sensor_type',      '^type$',                               'image\\\\\\\\s*sensor',      95, 'Canon: sensor type label under Image Sensor section'),\n      ('sensor_size',      'sensor\\\\\\\\s*size|screen\\\\\\\\s*size',        'image\\\\\\\\s*sensor',      90, 'Canon: sensor size label variants under Image Sensor'),\n      ('effective_pixels', 'effective\\\\\\\\s*pixels?',                 'image\\\\\\\\s*sensor',      95, 'Canon: effective pixels (space variant)'),\n\n      -- Viewfinder section: Canon uses short labels.\n      ('viewfinder_type',          '^type$',          'viewfinder', 85, 'Canon: viewfinder type label \\\\\\"Type\\\\\\" under Viewfinder'),\n      ('viewfinder_coverage',      '^coverage$',      'viewfinder', 80, 'Canon: viewfinder coverage label \\\\\\"Coverage\\\\\\"'),\n      ('viewfinder_magnification', '^magnification$', 'viewfinder', 80, 'Canon: viewfinder magnification label \\\\\\"Magnification\\\\\\"'),\n\n      -- Connectivity section: Canon label \\\\\\"Transmission Method\\\\\\" maps to wireless.\n      ('wireless', 'transmission\\\\\\\\s*method|wi-?fi|bluetooth', '(connectivity|communication)', 80, 'Canon: transmission method / wireless'),\n\n      -- Power Source section: Canon uses \\\\\\"Battery\\\\\\".\n      ('battery', '^battery$', '(power\\\\\\\\s*source|power)', 80, 'Canon: battery label under Power Source')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_spec_mapping_canon_camera
20251228003000	{"-- Add a matrix spec definition for Canon \\\\\\"File Size\\\\\\" table (still images).\n-- This enables mapping the HTML table to a canonical spec_definition and later persisting into product_spec_matrix.\n\nDO $$\nDECLARE\n  cat_id UUID;\n  s_storage UUID;\nBEGIN\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'mirrorless-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: product_category with slug=% not found. Run category seeds first.', 'mirrorless-cameras';\n  END IF;\n\n  -- Use existing Storage section for camera media-related tables.\n  SELECT id INTO s_storage FROM spec_section WHERE section_name='Storage' AND category_id=cat_id;\n  IF s_storage IS NULL THEN\n    -- Fallback: create if missing\n    INSERT INTO spec_section (section_name, category_id, display_order)\n    VALUES ('Storage', cat_id, 80)\n    ON CONFLICT (section_name, category_id) DO NOTHING;\n    SELECT id INTO s_storage FROM spec_section WHERE section_name='Storage' AND category_id=cat_id;\n  END IF;\n\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance)\n  VALUES (s_storage, 'Still Image File Size Table', 'still_image_file_size_table', 'matrix', 'MB', cat_id, 5)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Map the Canon \\\\\\"File Size\\\\\\" label (within Recording System section) to the matrix spec.\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT sd.id, v.extraction_pattern, v.context_pattern, v.priority, v.notes\n  FROM (\n    VALUES\n      ('file\\\\\\\\s*size', 'recording\\\\\\\\s*system', 95, 'Canon: still image file size table under Recording System')\n  ) AS v(extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = 'still_image_file_size_table'\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	add_matrix_spec_canon_file_size
20251228004000	{"-- UI-friendly views (JSON payloads + matrix grids)\n\n-- Still image \\"File Size\\" matrix (grid-shaped for UI)\n-- Dimensions:\n-- - format_group (e.g., JPEG*2, HEIF*3, RAW, RAW+JPEG*2)\n-- - quality (e.g., L, M, S1, RAW, C-RAW, etc.)\nCREATE OR REPLACE VIEW v_still_image_file_size_grid AS\nWITH base AS (\n    SELECT\n        p.id AS product_id,\n        p.slug AS product_slug,\n        (m.dims->>'format_group') AS format_group,\n        (m.dims->>'quality') AS quality,\n        jsonb_strip_nulls(\n            jsonb_build_object(\n                'mb', m.numeric_value,\n                'unit', m.unit_used,\n                'extra',\n                CASE\n                    WHEN m.value_text IS NULL THEN NULL::jsonb\n                    WHEN left(btrim(m.value_text), 1) IN ('{', '[') THEN m.value_text::jsonb\n                    ELSE jsonb_build_object('text', m.value_text)\n                END\n            )\n        ) AS cell\n    FROM product_spec_matrix m\n    JOIN product p ON p.id = m.product_id\n    JOIN spec_definition sd ON sd.id = m.spec_definition_id\n    WHERE sd.normalized_key = 'still_image_file_size_table'\n)\nSELECT\n    product_id,\n    product_slug,\n    format_group,\n    jsonb_object_agg(quality, cell) AS cells\nFROM base\nGROUP BY product_id, product_slug, format_group","-- Grouped specs JSON payload (for accordion/detail pages)\n-- Shape:\n-- {\n--   \\"sections\\": {\n--     \\"<Section Name>\\": {\n--       \\"<normalized_key>\\": { label, value, numeric, unit, bool }\n--     }\n--   }\n-- }\nCREATE OR REPLACE VIEW v_product_specs_grouped_json AS\nWITH base AS (\n    SELECT\n        p.id AS product_id,\n        p.slug AS product_slug,\n        COALESCE(ss.section_name, 'Other') AS section_name,\n        sd.normalized_key AS normalized_key,\n        sd.display_name AS display_name,\n        ps.spec_value AS spec_value,\n        ps.numeric_value AS numeric_value,\n        ps.unit_used AS unit_used,\n        ps.boolean_value AS boolean_value\n    FROM product_spec ps\n    JOIN product p ON p.id = ps.product_id\n    JOIN spec_definition sd ON sd.id = ps.spec_definition_id\n    LEFT JOIN spec_section ss ON ss.id = sd.section_id\n),\nper_section AS (\n    SELECT\n        product_id,\n        product_slug,\n        section_name,\n        jsonb_object_agg(\n            normalized_key,\n            jsonb_strip_nulls(\n                jsonb_build_object(\n                    'label', display_name,\n                    'value', spec_value,\n                    'numeric', numeric_value,\n                    'unit', unit_used,\n                    'bool', boolean_value\n                )\n            )\n        ) AS specs\n    FROM base\n    GROUP BY product_id, product_slug, section_name\n)\nSELECT\n    product_id,\n    product_slug,\n    jsonb_object_agg(section_name, specs) AS sections\nFROM per_section\nGROUP BY product_id, product_slug"}	add_ui_views
20251228005000	{"-- Add matrix spec definitions + mappings for Canon tables:\n-- - Playback > Display Format\n-- - Wi‑Fi > Security\n\nDO $$\nDECLARE\n  cat_id UUID;\n  s_playback UUID;\n  s_wifi UUID;\nBEGIN\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'mirrorless-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: product_category with slug=% not found. Run category seeds first.', 'mirrorless-cameras';\n  END IF;\n\n  -- Sections (create if missing)\n  SELECT id INTO s_playback FROM spec_section WHERE section_name='Playback' AND category_id=cat_id;\n  IF s_playback IS NULL THEN\n    INSERT INTO spec_section (section_name, category_id, display_order)\n    VALUES ('Playback', cat_id, 70)\n    ON CONFLICT (section_name, category_id) DO NOTHING;\n    SELECT id INTO s_playback FROM spec_section WHERE section_name='Playback' AND category_id=cat_id;\n  END IF;\n\n  SELECT id INTO s_wifi FROM spec_section WHERE section_name='Wi-Fi' AND category_id=cat_id;\n  IF s_wifi IS NULL THEN\n    -- Canon sometimes uses Wi‑Fi®; we use the plain \\"Wi-Fi\\" section name for canonical grouping.\n    INSERT INTO spec_section (section_name, category_id, display_order)\n    VALUES ('Wi-Fi', cat_id, 75)\n    ON CONFLICT (section_name, category_id) DO NOTHING;\n    SELECT id INTO s_wifi FROM spec_section WHERE section_name='Wi-Fi' AND category_id=cat_id;\n  END IF;\n\n  -- Matrix spec definitions\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance)\n  VALUES (s_playback, 'Playback Display Format Table', 'playback_display_format_table', 'matrix', NULL, cat_id, 3)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance)\n  VALUES (s_wifi, 'Wi-Fi Security Table', 'wifi_security_table', 'matrix', NULL, cat_id, 3)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Mappings (tables come through as raw_value=\\"[table]\\" so we map by label+section)\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT sd.id, v.extraction_pattern, v.context_pattern, v.priority, v.notes\n  FROM (\n    VALUES\n      ('display\\\\\\\\s*format', 'playback', 90, 'Canon: Playback > Display Format table'),\n      ('security', 'wi\\\\\\\\s*[-\\\\\\\\u00ae]?\\\\\\\\s*fi', 90, 'Canon: Wi-Fi > Security table')\n  ) AS v(extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON (\n    (sd.normalized_key = 'playback_display_format_table' AND v.extraction_pattern = 'display\\\\\\\\s*format')\n    OR (sd.normalized_key = 'wifi_security_table' AND v.extraction_pattern = 'security')\n  )\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	add_matrix_specs_canon_display_security
20251228006000	{"-- Seed migration (idempotent): Canon camera mapping batch 1 (UI-top specs)\n-- Focus: add missing spec_definitions + Canon section-scoped mapping rules.\n\nDO $$\nDECLARE\n  cat_id UUID;\n\n  s_general UUID;\n  s_sensor UUID;\n  s_image UUID;\n  s_optics UUID;\n  s_display UUID;\n  s_photo UUID;\n  s_physical UUID;\n  s_other UUID;\nBEGIN\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'mirrorless-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: product_category with slug=% not found. Run category seeds first.', 'mirrorless-cameras';\n  END IF;\n\n  -- Reuse existing section taxonomy from seed.sql\n  SELECT id INTO s_general  FROM spec_section WHERE section_name='General'              AND category_id=cat_id;\n  SELECT id INTO s_sensor   FROM spec_section WHERE section_name='Image Sensor'         AND category_id=cat_id;\n  SELECT id INTO s_image    FROM spec_section WHERE section_name='Image'                AND category_id=cat_id;\n  SELECT id INTO s_optics   FROM spec_section WHERE section_name='Optics & Focus'       AND category_id=cat_id;\n  SELECT id INTO s_display  FROM spec_section WHERE section_name='Display'              AND category_id=cat_id;\n  SELECT id INTO s_photo    FROM spec_section WHERE section_name='Photography Features' AND category_id=cat_id;\n  SELECT id INTO s_physical FROM spec_section WHERE section_name='Physical'             AND category_id=cat_id;\n  SELECT id INTO s_other    FROM spec_section WHERE section_name='Other Features'       AND category_id=cat_id;\n\n  -- Add missing definitions (safe to re-run)\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_optics,  'Compatible Lenses',          'compatible_lenses',          'text',   NULL,  cat_id, 7),\n\n    (s_sensor,  'Color Filter System',        'color_filter_system',        'text',   NULL,  cat_id, 3),\n    (s_sensor,  'Total Pixels',               'total_pixels',               'number', 'MP',  cat_id, 3),\n    (s_sensor,  'Low Pass Filter',            'low_pass_filter',            'text',   NULL,  cat_id, 2),\n    (s_sensor,  'Dust Deletion Feature',      'dust_deletion_feature',      'text',   NULL,  cat_id, 2),\n\n    (s_image,   'Recording Format',           'recording_format',           'text',   NULL,  cat_id, 3),\n    (s_image,   'Image Format',               'image_format',               'text',   NULL,  cat_id, 3),\n    (s_image,   'File Numbering',             'file_numbering',             'text',   NULL,  cat_id, 2),\n    (s_image,   'Picture Style',              'picture_style',              'text',   NULL,  cat_id, 3),\n    (s_image,   'White Balance Settings',     'white_balance_settings',     'text',   NULL,  cat_id, 3),\n    (s_image,   'Auto White Balance',         'auto_white_balance',         'text',   NULL,  cat_id, 2),\n    (s_image,   'White Balance Shift',        'white_balance_shift',        'text',   NULL,  cat_id, 2),\n\n    (s_display, 'LCD Type',                   'lcd_type',                   'text',   NULL,  cat_id, 3),\n    (s_display, 'Viewfinder Eye Point',       'viewfinder_eye_point',       'text',   NULL,  cat_id, 2),\n\n    (s_photo,   'Metering Range',             'metering_range',             'text',   NULL,  cat_id, 2),\n    (s_photo,   'AE Lock',                    'ae_lock',                    'text',   NULL,  cat_id, 2),\n    (s_photo,   'Shutter Type',               'shutter_type',               'text',   NULL,  cat_id, 3),\n    (s_photo,   'Shutter Speeds',             'shutter_speeds',             'text',   NULL,  cat_id, 3),\n    (s_photo,   'X-sync Speed',               'x_sync_speed',               'text',   NULL,  cat_id, 2),\n    (s_photo,   'Shutter Release',            'shutter_release',            'text',   NULL,  cat_id, 1),\n    (s_photo,   'Flash Exposure Compensation','flash_exposure_compensation','text',   NULL,  cat_id, 2),\n    (s_photo,   'E-TTL Balance',              'e_ttl_balance',              'text',   NULL,  cat_id, 1),\n\n    (s_physical,'Start-up Time',              'startup_time',               'text',   NULL,  cat_id, 1),\n\n    (s_other,   'Highlight Alert',            'highlight_alert',            'text',   NULL,  cat_id, 1),\n    (s_other,   'Protection',                 'protection',                 'text',   NULL,  cat_id, 1),\n    (s_other,   'Erase',                      'erase',                      'text',   NULL,  cat_id, 1),\n    (s_other,   'DPOF',                       'dpof',                       'text',   NULL,  cat_id, 1)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Canon section-scoped mapping rules (idempotent)\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT\n    sd.id,\n    v.extraction_pattern,\n    v.context_pattern,\n    v.priority,\n    v.notes\n  FROM (\n    VALUES\n      -- Type section\n      ('compatible_lenses',           '^compatible\\\\\\\\s*lenses$',                 '^type$',                        90, 'Canon: Compatible Lenses under Type'),\n\n      -- Image Sensor section\n      ('color_filter_system',         '^color\\\\\\\\s*filter\\\\\\\\s*system$',            'image\\\\\\\\s*sensor',                80, 'Canon: Color Filter System under Image Sensor'),\n      ('total_pixels',                '^total\\\\\\\\s*pixels$',                      'image\\\\\\\\s*sensor',                80, 'Canon: Total Pixels under Image Sensor'),\n      ('low_pass_filter',             '^low\\\\\\\\s*pass\\\\\\\\s*filter$',                'image\\\\\\\\s*sensor',                75, 'Canon: Low Pass Filter under Image Sensor'),\n      ('dust_deletion_feature',       '^dust\\\\\\\\s*deletion\\\\\\\\s*feature$',          'image\\\\\\\\s*sensor',                75, 'Canon: Dust Deletion Feature under Image Sensor'),\n\n      -- Recording System section\n      ('recording_format',            '^recording\\\\\\\\s*format$',                  '^recording\\\\\\\\s*system$',          80, 'Canon: Recording Format under Recording System'),\n      ('image_format',                '^image\\\\\\\\s*format$',                      '^recording\\\\\\\\s*system$',          80, 'Canon: Image Format under Recording System'),\n      ('file_numbering',              '^file\\\\\\\\s*numbering$',                    '^recording\\\\\\\\s*system$',          75, 'Canon: File Numbering under Recording System'),\n      ('picture_style',               '^picture\\\\\\\\s*style$',                     '^recording\\\\\\\\s*system$',          75, 'Canon: Picture Style under Recording System'),\n\n      -- White Balance section\n      ('white_balance_settings',      '^settings$',                             '^white\\\\\\\\s*balance$',             75, 'Canon: WB Settings under White Balance'),\n      ('auto_white_balance',          '^auto\\\\\\\\s*white\\\\\\\\s*balance$',             '^white\\\\\\\\s*balance$',             70, 'Canon: Auto White Balance under White Balance'),\n      ('white_balance_shift',         '^white\\\\\\\\s*balance\\\\\\\\s*shift$',            '^white\\\\\\\\s*balance$',             70, 'Canon: WB Shift under White Balance'),\n\n      -- Display / playback\n      ('lcd_type',                    '^type$',                                 '^lcd\\\\\\\\s*screen$',                75, 'Canon: LCD Screen Type'),\n      ('viewfinder_eye_point',        '^eye\\\\\\\\s*point$',                          '^viewfinder$',                   70, 'Canon: Viewfinder Eye Point'),\n      ('highlight_alert',             '^highlight\\\\\\\\s*alert$',                    '^playback$',                     70, 'Canon: Highlight Alert under Playback'),\n\n      -- Exposure / shutter / flash\n      ('metering_range',              '^metering\\\\\\\\s*range$',                     '^exposure\\\\\\\\s*control$',          70, 'Canon: Metering Range under Exposure Control'),\n      ('ae_lock',                     '^ae\\\\\\\\s*lock$',                            '^exposure\\\\\\\\s*control$',          70, 'Canon: AE Lock under Exposure Control'),\n      ('shutter_type',                '^type$',                                  '^shutter$',                      70, 'Canon: Shutter Type'),\n      ('shutter_speeds',              '^shutter\\\\\\\\s*speeds?$',                    '^shutter$',                      70, 'Canon: Shutter Speeds'),\n      ('x_sync_speed',                'x-?sync\\\\\\\\s*speed',                        '^shutter$',                      70, 'Canon: X-sync Speed'),\n      ('shutter_release',             '^shutter\\\\\\\\s*release$',                    '^shutter$',                      65, 'Canon: Shutter Release'),\n      ('self_timer',                  '^self\\\\\\\\s*timer$',                         '^shutter$',                      65, 'Canon: Self Timer under Shutter'),\n      ('flash_exposure_compensation', '^flash\\\\\\\\s*exposure\\\\\\\\s*compensation$',     '^external\\\\\\\\s*speedlite$',        65, 'Canon: Flash Exposure Compensation'),\n      ('e_ttl_balance',               'e-?ttl\\\\\\\\s*balance',                        '^external\\\\\\\\s*speedlite$',        60, 'Canon: E-TTL balance'),\n\n      -- Physical / power\n      ('startup_time',                'start-?up\\\\\\\\s*time',                       '^power\\\\\\\\s*source$',              60, 'Canon: Start-up Time under Power Source'),\n      ('dimensions',                  '^dimensions(\\\\\\\\b|\\\\\\\\s*\\\\\\\\()','dimensions\\\\\\\\s*and\\\\\\\\s*weight',          85, 'Canon: Dimensions (W x H x D) under Dimensions and Weight'),\n      ('weight',                      '^weight$',                                'dimensions\\\\\\\\s*and\\\\\\\\s*weight',    85, 'Canon: Weight under Dimensions and Weight'),\n\n      -- Other\n      ('protection',                  '^protection$',                            'image\\\\\\\\s*protection\\\\\\\\s*and\\\\\\\\s*erase', 60, 'Canon: Protection under Image Protection and Erase'),\n      ('erase',                       '^erase$',                                 'image\\\\\\\\s*protection\\\\\\\\s*and\\\\\\\\s*erase', 60, 'Canon: Erase under Image Protection and Erase'),\n      ('dpof',                        '^dpof$',                                  'dpof',                           60, 'Canon: DPOF under DPOF section')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_spec_mapping_canon_camera_batch1
20251228007000	{"-- Seed migration (idempotent): Canon camera mapping batch 2 (UI-top specs)\n-- Focus: Wi-Fi/Bluetooth details, LCD Screen attributes, and a few high-frequency Canon labels.\n\nDO $$\nDECLARE\n  cat_id UUID;\n\n  s_connect UUID;\n  s_display UUID;\n  s_optics UUID;\n  s_image UUID;\n  s_other UUID;\n  s_physical UUID;\nBEGIN\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'mirrorless-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: product_category with slug=% not found. Run category seeds first.', 'mirrorless-cameras';\n  END IF;\n\n  -- Reuse existing section taxonomy from seed.sql\n  SELECT id INTO s_connect  FROM spec_section WHERE section_name='Connectivity'   AND category_id=cat_id;\n  SELECT id INTO s_display  FROM spec_section WHERE section_name='Display'        AND category_id=cat_id;\n  SELECT id INTO s_optics   FROM spec_section WHERE section_name='Optics & Focus' AND category_id=cat_id;\n  SELECT id INTO s_image    FROM spec_section WHERE section_name='Image'          AND category_id=cat_id;\n  SELECT id INTO s_physical FROM spec_section WHERE section_name='Physical'       AND category_id=cat_id;\n  SELECT id INTO s_other    FROM spec_section WHERE section_name='Other Features' AND category_id=cat_id;\n\n  -- Add missing definitions (safe to re-run)\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    -- Connectivity: split Wi‑Fi vs Bluetooth so we don't jam everything into generic `wireless`\n    (s_connect, 'Wi‑Fi Standards Compliance',      'wifi_standards_compliance',      'text', NULL, cat_id, 3),\n    (s_connect, 'Wi‑Fi Transmission Method',       'wifi_transmission_method',       'text', NULL, cat_id, 2),\n    (s_connect, 'Wi‑Fi Frequency (Central)',       'wifi_frequency_central',         'text', NULL, cat_id, 2),\n    (s_connect, 'Bluetooth Standards Compliance',  'bluetooth_standards_compliance', 'text', NULL, cat_id, 2),\n    (s_connect, 'Bluetooth Transmission Method',   'bluetooth_transmission_method',  'text', NULL, cat_id, 1),\n    (s_connect, 'Wi‑Fi Smartphone Support',        'wifi_smartphone_support',        'text', NULL, cat_id, 1),\n    (s_connect, 'Wi‑Fi EOS Utility Support',       'wifi_eos_utility_support',       'text', NULL, cat_id, 1),\n    (s_connect, 'Wi‑Fi Printer Support',           'wifi_printer_support',           'text', NULL, cat_id, 1),\n    (s_connect, 'Wi‑Fi Web Service Support',       'wifi_web_service_support',       'text', NULL, cat_id, 1),\n\n    -- Display: Canon LCD Screen emits many stable labels\n    (s_display, 'LCD Coverage',                    'lcd_coverage',                   'text', NULL, cat_id, 1),\n    (s_display, 'LCD Brightness Control',          'lcd_brightness_control',         'text', NULL, cat_id, 1),\n    (s_display, 'LCD Coating',                     'lcd_coating',                    'text', NULL, cat_id, 1),\n    (s_display, 'Interface Languages',             'interface_languages',            'text', NULL, cat_id, 1),\n    (s_connect, 'Headphone Terminal',              'headphone_terminal',             'text', NULL, cat_id, 2),\n\n    -- Optics & Focus\n    (s_optics,  'Focus Method',                    'focus_method',                   'text', NULL, cat_id, 2),\n\n    -- Image / recording\n    (s_image,   'RAW + JPEG/HEIF Simultaneous Recording', 'raw_jpeg_heif_simultaneous_recording', 'text', NULL, cat_id, 2),\n    (s_image,   'Color Space',                     'color_space',                    'text', NULL, cat_id, 2),\n\n    -- Physical / operating env\n    (s_physical,'Working Temperature Range',       'working_temperature_range',      'text', NULL, cat_id, 1),\n\n    -- Other / playback\n    (s_other,   'Histogram',                       'histogram',                      'text', NULL, cat_id, 1),\n    (s_other,   'Quick Control Function',          'quick_control_function',         'text', NULL, cat_id, 1)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Canon section-scoped mapping rules (idempotent)\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT\n    sd.id,\n    v.extraction_pattern,\n    v.context_pattern,\n    v.priority,\n    v.notes\n  FROM (\n    VALUES\n      -- Wi‑Fi / Bluetooth sections (Canon uses section names like \\"Wi‑Fi®\\" / \\"Bluetooth®\\")\n      ('wifi_transmission_method',        '^transmission\\\\\\\\s*method$',                       'wi-?fi',     80, 'Canon: Wi‑Fi Transmission Method under Wi‑Fi section'),\n      ('bluetooth_transmission_method',   '^transmission\\\\\\\\s*method$',                       'bluetooth',  80, 'Canon: Bluetooth Transmission Method under Bluetooth section'),\n      ('wifi_standards_compliance',       '^standards\\\\\\\\s*compliance$',                      'wi-?fi',     80, 'Canon: Wi‑Fi Standards Compliance'),\n      ('bluetooth_standards_compliance',  '^standards\\\\\\\\s*compliance$',                      'bluetooth',  80, 'Canon: Bluetooth Standards Compliance'),\n      ('wifi_frequency_central',          '^transition\\\\\\\\s*frequency\\\\\\\\s*\\\\\\\\(central\\\\\\\\s*frequency\\\\\\\\)$', 'wi-?fi', 75, 'Canon: Wi‑Fi frequency (central)'),\n      ('wifi_smartphone_support',         '^communication\\\\\\\\s*with\\\\\\\\s*a\\\\\\\\s*smartphone$',      'wi-?fi',     70, 'Canon: Wi‑Fi smartphone support label'),\n      ('wifi_eos_utility_support',        '^remote\\\\\\\\s*operation\\\\\\\\s*using\\\\\\\\s*eos\\\\\\\\s*utility$', 'wi-?fi',    70, 'Canon: Wi‑Fi EOS Utility support label'),\n      ('wifi_printer_support',            '^print\\\\\\\\s*from\\\\\\\\s*wi-?fi\\\\\\\\W*printers$',           'wi-?fi',     70, 'Canon: Wi‑Fi printer support label'),\n      ('wifi_web_service_support',        '^send\\\\\\\\s*images\\\\\\\\s*to\\\\\\\\s*a\\\\\\\\s*web\\\\\\\\s*service$',   'wi-?fi',     70, 'Canon: Wi‑Fi web service support label'),\n\n      -- LCD Screen / LCD Monitor section labels\n      ('lcd_coverage',                    '^coverage$',                                     '^lcd\\\\\\\\s*(screen|monitor)$', 75, 'Canon: LCD coverage'),\n      ('lcd_brightness_control',          '^brightness\\\\\\\\s*control$',                         '^lcd\\\\\\\\s*(screen|monitor)$', 75, 'Canon: LCD brightness control'),\n      ('interface_languages',             '^interface\\\\\\\\s*languages$',                         '^lcd\\\\\\\\s*(screen|monitor)$', 75, 'Canon: UI language list'),\n      ('screen_dots',                     '^dots$',                                          '^lcd\\\\\\\\s*(screen|monitor)$', 80, 'Canon: LCD dots label variant -> screen_dots'),\n      ('lcd_coating',                     '^coating$',                                       '^lcd\\\\\\\\s*(screen|monitor)$', 70, 'Canon: LCD coating'),\n\n      -- Ports (map Canon \\"Headphone terminal\\" to a text field, not boolean headphone_port)\n      ('headphone_terminal',              '^headphone\\\\\\\\s*terminal$',                          '(interface|external\\\\\\\\s*interface)', 75, 'Canon: headphone terminal details'),\n\n      -- Autofocus\n      ('focus_method',                    '^focus\\\\\\\\s*method$',                                '^autofocus$', 75, 'Canon: Focus Method under Autofocus'),\n\n      -- Playback / quick control\n      ('histogram',                       '^histogram$',                                      '^playback$', 70, 'Canon: Histogram under Playback'),\n      ('quick_control_function',          '^function$',                                       '^quick\\\\\\\\s*control\\\\\\\\s*function$', 70, 'Canon: Quick Control Function'),\n\n      -- Operating environment\n      ('working_temperature_range',        '^working\\\\\\\\s*temperature\\\\\\\\s*range$',               '(operating\\\\\\\\s*environment|working\\\\\\\\s*conditions)', 70, 'Canon: working temperature range'),\n\n      -- Recording system\n      ('raw_jpeg_heif_simultaneous_recording', '^raw\\\\\\\\s*\\\\\\\\+\\\\\\\\s*jpe?g\\\\\\\\s*/\\\\\\\\s*heif\\\\\\\\s*simultaneous\\\\\\\\s*recording$', '^recording\\\\\\\\s*system$', 75, 'Canon: RAW+JPEG/HEIF simultaneous recording'),\n      ('color_space',                     '^color\\\\\\\\s*space$',                                 '^recording\\\\\\\\s*system$', 75, 'Canon: Color Space under Recording System')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_spec_mapping_canon_camera_batch2
20251228008000	{"-- Fix migration (idempotent): Canon camera mapping batch 2\n-- Why: editing an already-applied migration does not re-run it; this file re-seeds any missing\n-- spec_definitions + spec_mapping rules introduced in batch2.\n\nDO $$\nDECLARE\n  cat_id UUID;\n  s_connect UUID;\n  s_display UUID;\n  s_optics UUID;\n  s_image UUID;\n  s_other UUID;\n  s_physical UUID;\nBEGIN\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'mirrorless-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: product_category with slug=% not found. Run category seeds first.', 'mirrorless-cameras';\n  END IF;\n\n  SELECT id INTO s_connect  FROM spec_section WHERE section_name='Connectivity'   AND category_id=cat_id;\n  SELECT id INTO s_display  FROM spec_section WHERE section_name='Display'        AND category_id=cat_id;\n  SELECT id INTO s_optics   FROM spec_section WHERE section_name='Optics & Focus' AND category_id=cat_id;\n  SELECT id INTO s_image    FROM spec_section WHERE section_name='Image'          AND category_id=cat_id;\n  SELECT id INTO s_physical FROM spec_section WHERE section_name='Physical'       AND category_id=cat_id;\n  SELECT id INTO s_other    FROM spec_section WHERE section_name='Other Features' AND category_id=cat_id;\n\n  -- Ensure missing definitions exist (safe to re-run)\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_connect, 'Headphone Terminal',              'headphone_terminal',             'text', NULL, cat_id, 2),\n    (s_connect, 'Wi‑Fi Standards Compliance',      'wifi_standards_compliance',      'text', NULL, cat_id, 3),\n    (s_connect, 'Wi‑Fi Transmission Method',       'wifi_transmission_method',       'text', NULL, cat_id, 2),\n    (s_connect, 'Wi‑Fi Frequency (Central)',       'wifi_frequency_central',         'text', NULL, cat_id, 2),\n    (s_connect, 'Bluetooth Standards Compliance',  'bluetooth_standards_compliance', 'text', NULL, cat_id, 2),\n    (s_connect, 'Bluetooth Transmission Method',   'bluetooth_transmission_method',  'text', NULL, cat_id, 1),\n    (s_connect, 'Wi‑Fi Smartphone Support',        'wifi_smartphone_support',        'text', NULL, cat_id, 1),\n    (s_connect, 'Wi‑Fi EOS Utility Support',       'wifi_eos_utility_support',       'text', NULL, cat_id, 1),\n    (s_connect, 'Wi‑Fi Printer Support',           'wifi_printer_support',           'text', NULL, cat_id, 1),\n    (s_connect, 'Wi‑Fi Web Service Support',       'wifi_web_service_support',       'text', NULL, cat_id, 1),\n\n    (s_display, 'LCD Coverage',                    'lcd_coverage',                   'text', NULL, cat_id, 1),\n    (s_display, 'LCD Brightness Control',          'lcd_brightness_control',         'text', NULL, cat_id, 1),\n    (s_display, 'LCD Coating',                     'lcd_coating',                    'text', NULL, cat_id, 1),\n    (s_display, 'Interface Languages',             'interface_languages',            'text', NULL, cat_id, 1),\n\n    (s_optics,  'Focus Method',                    'focus_method',                   'text', NULL, cat_id, 2),\n\n    (s_image,   'RAW + JPEG/HEIF Simultaneous Recording', 'raw_jpeg_heif_simultaneous_recording', 'text', NULL, cat_id, 2),\n    (s_image,   'Color Space',                     'color_space',                    'text', NULL, cat_id, 2),\n\n    (s_physical,'Working Temperature Range',       'working_temperature_range',      'text', NULL, cat_id, 1),\n\n    (s_other,   'Histogram',                       'histogram',                      'text', NULL, cat_id, 1),\n    (s_other,   'Quick Control Function',          'quick_control_function',         'text', NULL, cat_id, 1)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Re-seed mapping rules (safe to re-run)\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT\n    sd.id,\n    v.extraction_pattern,\n    v.context_pattern,\n    v.priority,\n    v.notes\n  FROM (\n    VALUES\n      ('wifi_transmission_method',        '^transmission\\\\\\\\s*method$',                       'wi-?fi',     80, 'Canon: Wi‑Fi Transmission Method under Wi‑Fi section'),\n      ('bluetooth_transmission_method',   '^transmission\\\\\\\\s*method$',                       'bluetooth',  80, 'Canon: Bluetooth Transmission Method under Bluetooth section'),\n      ('wifi_standards_compliance',       '^standards\\\\\\\\s*compliance$',                      'wi-?fi',     80, 'Canon: Wi‑Fi Standards Compliance'),\n      ('bluetooth_standards_compliance',  '^standards\\\\\\\\s*compliance$',                      'bluetooth',  80, 'Canon: Bluetooth Standards Compliance'),\n      ('wifi_frequency_central',          '^transition\\\\\\\\s*frequency\\\\\\\\s*\\\\\\\\(central\\\\\\\\s*frequency\\\\\\\\)$', 'wi-?fi', 75, 'Canon: Wi‑Fi frequency (central)'),\n      ('wifi_smartphone_support',         '^communication\\\\\\\\s*with\\\\\\\\s*a\\\\\\\\s*smartphone$',      'wi-?fi',     70, 'Canon: Wi‑Fi smartphone support label'),\n      ('wifi_eos_utility_support',        '^remote\\\\\\\\s*operation\\\\\\\\s*using\\\\\\\\s*eos\\\\\\\\s*utility$', 'wi-?fi',    70, 'Canon: Wi‑Fi EOS Utility support label'),\n      ('wifi_printer_support',            '^print\\\\\\\\s*from\\\\\\\\s*wi-?fi\\\\\\\\W*printers$',           'wi-?fi',     70, 'Canon: Wi‑Fi printer support label'),\n      ('wifi_web_service_support',        '^send\\\\\\\\s*images\\\\\\\\s*to\\\\\\\\s*a\\\\\\\\s*web\\\\\\\\s*service$',   'wi-?fi',     70, 'Canon: Wi‑Fi web service support label'),\n\n      ('lcd_coverage',                    '^coverage$',                                     '^lcd\\\\\\\\s*(screen|monitor)$', 75, 'Canon: LCD coverage'),\n      ('lcd_brightness_control',          '^brightness\\\\\\\\s*control$',                         '^lcd\\\\\\\\s*(screen|monitor)$', 75, 'Canon: LCD brightness control'),\n      ('interface_languages',             '^interface\\\\\\\\s*languages$',                         '^lcd\\\\\\\\s*(screen|monitor)$', 75, 'Canon: UI language list'),\n      ('screen_dots',                     '^dots$',                                          '^lcd\\\\\\\\s*(screen|monitor)$', 80, 'Canon: LCD dots label variant -> screen_dots'),\n      ('lcd_coating',                     '^coating$',                                       '^lcd\\\\\\\\s*(screen|monitor)$', 70, 'Canon: LCD coating'),\n\n      ('headphone_terminal',              '^headphone\\\\\\\\s*terminal$',                          '(interface|external\\\\\\\\s*interface)', 75, 'Canon: headphone terminal details'),\n\n      ('focus_method',                    '^focus\\\\\\\\s*method$',                                '^autofocus$', 75, 'Canon: Focus Method under Autofocus'),\n\n      ('histogram',                       '^histogram$',                                      '^playback$', 70, 'Canon: Histogram under Playback'),\n      ('quick_control_function',          '^function$',                                       '^quick\\\\\\\\s*control\\\\\\\\s*function$', 70, 'Canon: Quick Control Function'),\n\n      ('working_temperature_range',        '^working\\\\\\\\s*temperature\\\\\\\\s*range$',               '(operating\\\\\\\\s*environment|working\\\\\\\\s*conditions)', 70, 'Canon: working temperature range'),\n\n      ('raw_jpeg_heif_simultaneous_recording', '^raw\\\\\\\\s*\\\\\\\\+\\\\\\\\s*jpe?g\\\\\\\\s*/\\\\\\\\s*heif\\\\\\\\s*simultaneous\\\\\\\\s*recording$', '^recording\\\\\\\\s*system$', 75, 'Canon: RAW+JPEG/HEIF simultaneous recording'),\n      ('color_space',                     '^color\\\\\\\\s*space$',                                 '^recording\\\\\\\\s*system$', 75, 'Canon: Color Space under Recording System')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_spec_mapping_canon_camera_batch2_fix
20251228009000	{"-- Seed migration (idempotent): Canon camera mapping batch 3\n-- Focus: highest-frequency remaining Canon labels after batches 1-2 (viewfinder, flash, video, Bluetooth).\n\nDO $$\nDECLARE\n  cat_id UUID;\n  s_connect UUID;\n  s_display UUID;\n  s_image UUID;\n  s_photo UUID;\n  s_video UUID;\n  s_other UUID;\nBEGIN\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'mirrorless-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: product_category with slug=% not found. Run category seeds first.', 'mirrorless-cameras';\n  END IF;\n\n  SELECT id INTO s_connect FROM spec_section WHERE section_name='Connectivity'         AND category_id=cat_id;\n  SELECT id INTO s_display FROM spec_section WHERE section_name='Display'              AND category_id=cat_id;\n  SELECT id INTO s_image   FROM spec_section WHERE section_name='Image'                AND category_id=cat_id;\n  SELECT id INTO s_photo   FROM spec_section WHERE section_name='Photography Features' AND category_id=cat_id;\n  SELECT id INTO s_video   FROM spec_section WHERE section_name='Videography Features' AND category_id=cat_id;\n  SELECT id INTO s_other   FROM spec_section WHERE section_name='Other Features'       AND category_id=cat_id;\n\n  -- Add missing definitions (safe to re-run)\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_photo,   'Continuous Flash Control',        'continuous_flash_control',        'text', NULL, cat_id, 1),\n    (s_photo,   'Accessory Shoe',                 'accessory_shoe',                 'text', NULL, cat_id, 1),\n\n    (s_display, 'Viewfinder Magnification/Angle of View', 'viewfinder_magnification_angle_of_view', 'text', NULL, cat_id, 1),\n    (s_display, 'Viewfinder Dioptric Adjustment Range',   'viewfinder_dioptric_adjustment_range',   'text', NULL, cat_id, 1),\n    (s_display, 'Viewfinder Information',          'viewfinder_information',          'text', NULL, cat_id, 1),\n\n    (s_image,   'Still Photo IS',                 'still_photo_is',                 'text', NULL, cat_id, 1),\n\n    (s_video,   'Time Code',                      'time_code',                      'text', NULL, cat_id, 2),\n\n    (s_connect, 'Bluetooth Pairing',              'bluetooth_pairing',              'text', NULL, cat_id, 1),\n    (s_connect, 'Wi‑Fi Connection Method',        'wifi_connection_method',         'text', NULL, cat_id, 1),\n\n    (s_other,   'Compatible Printers',            'compatible_printers',            'text', NULL, cat_id, 1)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Canon mapping rules (section-scoped) (safe to re-run)\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT\n    sd.id,\n    v.extraction_pattern,\n    v.context_pattern,\n    v.priority,\n    v.notes\n  FROM (\n    VALUES\n      -- External Speedlite\n      ('continuous_flash_control',        '^continuous\\\\\\\\s*flash\\\\\\\\s*control$',      '^external\\\\\\\\s*speedlite$', 75, 'Canon: Continuous flash control'),\n      ('accessory_shoe',                 '^accessory\\\\\\\\s*shoe$',                    '^external\\\\\\\\s*speedlite$', 75, 'Canon: Accessory shoe'),\n\n      -- Viewfinder\n      ('viewfinder_magnification_angle_of_view', '^magnification\\\\\\\\s*/\\\\\\\\s*angle\\\\\\\\s*of\\\\\\\\s*view$', '^viewfinder$', 75, 'Canon: Magnification / Angle of View'),\n      ('viewfinder_dioptric_adjustment_range',   '^dioptric\\\\\\\\s*adjustment\\\\\\\\s*range$',           '^viewfinder$', 75, 'Canon: Dioptric adjustment range'),\n      ('viewfinder_information',                 '^viewfinder\\\\\\\\s*information$',                 '^viewfinder$', 70, 'Canon: Viewfinder information (long list)'),\n\n      -- Direct Printing\n      ('compatible_printers',                   '^compatible\\\\\\\\s*printers$',                    '^direct\\\\\\\\s*printing$', 70, 'Canon: Compatible printers (often Not supported)'),\n\n      -- Image Stabilization (IS mode)\n      ('still_photo_is',                        '^still\\\\\\\\s*photo\\\\\\\\s*is$',                       '^image\\\\\\\\s*stabilization\\\\\\\\s*\\\\\\\\(is\\\\\\\\s*mode\\\\\\\\)$', 70, 'Canon: Still Photo IS'),\n\n      -- Video Shooting\n      ('time_code',                              '^time\\\\\\\\s*code$',                               '^video\\\\\\\\s*shooting$', 75, 'Canon: Time Code'),\n      -- Map existing Tier-1 definition, but section is Video Shooting (Canon), not exposure/metering.\n      ('exposure_compensation',                  '^exposure\\\\\\\\s*compensation$',                   '^video\\\\\\\\s*shooting$', 80, 'Canon: Exposure compensation under Video Shooting'),\n\n      -- LCD Screen\n      ('touch_screen',                           '^touch[-\\\\\\\\s]*screen\\\\\\\\s*operation$',            '^lcd\\\\\\\\s*screen$', 80, 'Canon: Touch-screen Operation under LCD Screen'),\n\n      -- Bluetooth / Wi‑Fi\n      ('bluetooth_pairing',                      '^bluetooth\\\\\\\\s*pairing$',                       'bluetooth', 75, 'Canon: Bluetooth Pairing'),\n      ('wifi_connection_method',                 '^connection\\\\\\\\s*method$',                        'wi-?fi', 75, 'Canon: Wi‑Fi Connection Method')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_spec_mapping_canon_camera_batch3
20251228010000	{"-- Seed migration (idempotent): Canon camera mapping batch 4\n-- Focus: next highest-frequency Canon labels (environment, autofocus, video, customization, HDR).\n\nDO $$\nDECLARE\n  cat_id UUID;\n  s_sensor UUID;\n  s_image UUID;\n  s_optics UUID;\n  s_display UUID;\n  s_photo UUID;\n  s_video UUID;\n  s_connect UUID;\n  s_physical UUID;\n  s_other UUID;\nBEGIN\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'mirrorless-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: product_category with slug=% not found. Run category seeds first.', 'mirrorless-cameras';\n  END IF;\n\n  SELECT id INTO s_sensor   FROM spec_section WHERE section_name='Image Sensor'         AND category_id=cat_id;\n  SELECT id INTO s_image    FROM spec_section WHERE section_name='Image'                AND category_id=cat_id;\n  SELECT id INTO s_optics   FROM spec_section WHERE section_name='Optics & Focus'       AND category_id=cat_id;\n  SELECT id INTO s_display  FROM spec_section WHERE section_name='Display'              AND category_id=cat_id;\n  SELECT id INTO s_photo    FROM spec_section WHERE section_name='Photography Features' AND category_id=cat_id;\n  SELECT id INTO s_video    FROM spec_section WHERE section_name='Videography Features' AND category_id=cat_id;\n  SELECT id INTO s_connect  FROM spec_section WHERE section_name='Connectivity'         AND category_id=cat_id;\n  SELECT id INTO s_physical FROM spec_section WHERE section_name='Physical'             AND category_id=cat_id;\n  SELECT id INTO s_other    FROM spec_section WHERE section_name='Other Features'       AND category_id=cat_id;\n\n  -- Add missing definitions (safe to re-run)\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    -- Operating environment / conditions\n    (s_physical, 'Working Humidity',                        'working_humidity',                        'text', NULL, cat_id, 1),\n\n    -- Image sensor\n    (s_sensor,   'Pixel Unit',                              'pixel_unit',                              'text', NULL, cat_id, 1),\n\n    -- Autofocus / detection capabilities\n    (s_optics,   'Focusing Brightness Range (Still Photo)', 'focusing_brightness_range_still',         'text', NULL, cat_id, 1),\n    (s_optics,   'Eye Detection',                            'eye_detection',                           'text', NULL, cat_id, 1),\n    (s_optics,   'Available Subject Detection',              'available_subject_detection',             'text', NULL, cat_id, 1),\n\n    -- Video\n    (s_video,    'Video AF',                                 'video_af',                                'text', NULL, cat_id, 1),\n    (s_video,    'Movie Pre-recording',                      'movie_pre_recording',                     'text', NULL, cat_id, 1),\n\n    -- UI / customization\n    (s_other,    'Quick Control Screen',                     'quick_control_screen',                    'text', NULL, cat_id, 1),\n    (s_other,    'Available Functions',                      'available_functions',                     'text', NULL, cat_id, 1),\n\n    -- HDR\n    (s_other,    'Continuous HDR Shooting (Still Images)',   'continuous_hdr_shooting_still_images',    'text', NULL, cat_id, 1)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Canon mapping rules (section-scoped) (safe to re-run)\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT\n    sd.id,\n    v.extraction_pattern,\n    v.context_pattern,\n    v.priority,\n    v.notes\n  FROM (\n    VALUES\n      -- Operating environment / working conditions\n      ('working_humidity',                         '^working\\\\\\\\s*humidity(\\\\\\\\s*range)?$',            '(operating\\\\\\\\s*environment|working\\\\\\\\s*conditions)', 75, 'Canon: working humidity'),\n      -- (not in top10 right now, but pairs with humidity)\n      ('working_temperature_range',                '^working\\\\\\\\s*temperature\\\\\\\\s*range$',            '(operating\\\\\\\\s*environment|working\\\\\\\\s*conditions)', 75, 'Canon: working temperature'),\n\n      -- Image Sensor\n      ('pixel_unit',                               '^pixel\\\\\\\\s*unit$',                               '^image\\\\\\\\s*sensor$', 75, 'Canon: pixel unit under Image Sensor'),\n\n      -- Autofocus\n      ('focusing_brightness_range_still',          '^focusing\\\\\\\\s*brightness\\\\\\\\s*range\\\\\\\\s*\\\\\\\\(still\\\\\\\\s*photo\\\\\\\\s*shooting\\\\\\\\)$', '^autofocus$', 75, 'Canon: focusing brightness range (still photo shooting)'),\n      ('eye_detection',                            '^eye\\\\\\\\s*detection$',                            '^autofocus$', 75, 'Canon: eye detection'),\n      ('available_subject_detection',              '^available\\\\\\\\s*subject\\\\\\\\s*detection$',           '^autofocus$', 75, 'Canon: available subject detection'),\n\n      -- Video Shooting\n      ('video_af',                                 '^video\\\\\\\\s*af$',                                 '^video\\\\\\\\s*shooting$', 75, 'Canon: video AF'),\n      ('movie_pre_recording',                      '^movie\\\\\\\\s*pre-?recording\\\\\\\\s*\\\\\\\\(on/off\\\\\\\\)$',      '^video\\\\\\\\s*shooting$', 75, 'Canon: movie pre-recording'),\n\n      -- Quick Control / customization\n      ('quick_control_screen',                     '^quick\\\\\\\\s*control\\\\\\\\s*screen$',                  '^quick\\\\\\\\s*control\\\\\\\\s*function$', 75, 'Canon: quick control screen'),\n      ('available_functions',                      '^available\\\\\\\\s*functions$',                       '^customization$', 75, 'Canon: available functions under Customization'),\n\n      -- HDR\n      ('continuous_hdr_shooting_still_images',     '^continuous\\\\\\\\s*hdr\\\\\\\\s*shooting\\\\\\\\s*\\\\\\\\(still\\\\\\\\s*images\\\\\\\\)$', '^hdr\\\\\\\\s*shooting$', 75, 'Canon: continuous HDR shooting (still images)')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_spec_mapping_canon_camera_batch4
20251228011000	{"-- Seed migration (idempotent): Canon camera mapping batch 5\n-- Focus: next highest-frequency labels (ports, Wi‑Fi standards label variant, video focusing, HDR, customization).\n\nDO $$\nDECLARE\n  cat_id UUID;\n  s_sensor UUID;\n  s_image UUID;\n  s_display UUID;\n  s_optics UUID;\n  s_video UUID;\n  s_connect UUID;\n  s_physical UUID;\n  s_other UUID;\nBEGIN\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'mirrorless-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: product_category with slug=% not found. Run category seeds first.', 'mirrorless-cameras';\n  END IF;\n\n  SELECT id INTO s_sensor   FROM spec_section WHERE section_name='Image Sensor'         AND category_id=cat_id;\n  SELECT id INTO s_image    FROM spec_section WHERE section_name='Image'                AND category_id=cat_id;\n  SELECT id INTO s_optics   FROM spec_section WHERE section_name='Optics & Focus'       AND category_id=cat_id;\n  SELECT id INTO s_video    FROM spec_section WHERE section_name='Videography Features' AND category_id=cat_id;\n  SELECT id INTO s_connect  FROM spec_section WHERE section_name='Connectivity'         AND category_id=cat_id;\n  SELECT id INTO s_physical FROM spec_section WHERE section_name='Physical'             AND category_id=cat_id;\n  SELECT id INTO s_other    FROM spec_section WHERE section_name='Other Features'       AND category_id=cat_id;\n\n  -- Add missing definitions (safe to re-run)\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    -- Video calls / streaming\n    (s_video,   'USB Video Class (UVC)',                 'usb_video_class_uvc',               'text', NULL, cat_id, 1),\n\n    -- Customization\n    (s_other,   'Customizable Dials',                    'customizable_dials',                'text', NULL, cat_id, 1),\n    (s_other,   'Available Functions',                   'available_functions',               'text', NULL, cat_id, 1),\n\n    -- Ports / terminals (Canon uses Interface section labels)\n    (s_connect, 'Microphone Terminal',                   'microphone_terminal',               'text', NULL, cat_id, 1),\n    (s_connect, 'Remote Control Terminal',               'remote_control_terminal',           'text', NULL, cat_id, 1),\n    (s_connect, 'Video Out Terminal',                    'video_out_terminal',                'text', NULL, cat_id, 1),\n\n    -- Video / live view focusing\n    (s_video,   'Focusing (Video/Live View)',            'focusing_video',                    'text', NULL, cat_id, 1),\n\n    -- Image sensor\n    (s_sensor,  'Pixel Size',                            'pixel_size',                        'text', NULL, cat_id, 1),\n\n    -- Autofocus\n    (s_optics,  'Focusing Brightness Range (Movie)',     'focusing_brightness_range_movie',   'text', NULL, cat_id, 1),\n    (s_optics,  'Subject to Detect',                     'subject_to_detect',                 'text', NULL, cat_id, 1),\n\n    -- HDR / recording system details\n    (s_other,   'HDR Shooting (HDR PQ)',                 'hdr_shooting_hdr_pq',               'text', NULL, cat_id, 1),\n    (s_image,   'HDR Mode Continuous Shooting',          'hdr_mode_continuous_shooting',      'text', NULL, cat_id, 1),\n    (s_image,   'Advanced Shooting Operations',          'advanced_shooting_operations',      'text', NULL, cat_id, 1),\n\n    -- Exposure control\n    (s_other,   'Exposure Modes',                        'exposure_modes',                    'text', NULL, cat_id, 1),\n\n    -- Flash compatibility\n    (s_other,   'Compatible E‑TTL Speedlites',           'compatible_e_ttl_speedlites',       'text', NULL, cat_id, 1)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Canon mapping rules (section-scoped) (safe to re-run)\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT\n    sd.id,\n    v.extraction_pattern,\n    v.context_pattern,\n    v.priority,\n    v.notes\n  FROM (\n    VALUES\n      -- Video Calls / Streaming\n      ('usb_video_class_uvc',                 '^usb\\\\\\\\s*video\\\\\\\\s*class\\\\\\\\s*\\\\\\\\(uvc\\\\\\\\)$',          '^video\\\\\\\\s*calls\\\\\\\\s*/\\\\\\\\s*streaming$', 80, 'Canon: UVC label'),\n\n      -- Customization (scope strictly to avoid the weird context bleed seen in report)\n      ('customizable_dials',                  '^customizable\\\\\\\\s*dials$',                        '^customization$', 80, 'Canon: customizable dials'),\n      ('available_functions',                 '^available\\\\\\\\s*functions$',                        '^customization$', 70, 'Canon: available functions'),\n\n      -- Interface / External Interface (ports)\n      ('microphone_terminal',                 '^microphone\\\\\\\\s*terminal$',                        '(interface|external\\\\\\\\s*interface)', 80, 'Canon: microphone terminal (port details)'),\n      ('remote_control_terminal',             '^remote\\\\\\\\s*control\\\\\\\\s*terminal$',                 '(interface|external\\\\\\\\s*interface)', 80, 'Canon: remote control terminal'),\n      ('video_out_terminal',                  '^video\\\\\\\\s*out\\\\\\\\s*terminal$',                      '^interface$', 80, 'Canon: video out terminal'),\n\n      -- Video Shooting / Live View Functions\n      ('focusing_video',                      '^focusing$',                                     '(video\\\\\\\\s*shooting|live\\\\\\\\s*view\\\\\\\\s*functions)', 75, 'Canon: focusing (video/live view)'),\n\n      -- Image sensor\n      ('pixel_size',                          '^pixel\\\\\\\\s*size$',                                 '^image\\\\\\\\s*sensor$', 75, 'Canon: pixel size under Image Sensor'),\n\n      -- Autofocus\n      ('focusing_brightness_range_movie',     '^focusing\\\\\\\\s*brightness\\\\\\\\s*range\\\\\\\\s*\\\\\\\\(movie\\\\\\\\s*recording\\\\\\\\)$', '^autofocus$', 75, 'Canon: focusing brightness range (movie recording)'),\n      ('subject_to_detect',                   '^subject\\\\\\\\s*to\\\\\\\\s*detect$',                        '^autofocus$', 70, 'Canon: subject to detect'),\n\n      -- HDR\n      ('hdr_shooting_hdr_pq',                 '^hdr\\\\\\\\s*shooting\\\\\\\\s*\\\\\\\\(hdr\\\\\\\\s*pq\\\\\\\\)$',            '^hdr\\\\\\\\s*shooting$', 75, 'Canon: HDR shooting (HDR PQ)'),\n      ('hdr_mode_continuous_shooting',        '^hdr\\\\\\\\s*mode-?continuous\\\\\\\\s*shooting$',            '^recording\\\\\\\\s*system$', 70, 'Canon: HDR mode continuous shooting'),\n\n      -- Recording system misc\n      ('advanced_shooting_operations',        '^advanced\\\\\\\\s*shooting\\\\\\\\s*operations$',            '^recording\\\\\\\\s*system$', 70, 'Canon: advanced shooting operations'),\n\n      -- Exposure control\n      ('exposure_modes',                      '^exposure\\\\\\\\s*modes$',                              '^exposure\\\\\\\\s*control$', 75, 'Canon: exposure modes'),\n\n      -- Wi‑Fi standards label variant: map into existing `wifi_standards_compliance`\n      ('wifi_standards_compliance',           '^supporting\\\\\\\\s*standards$',                        'wi-?fi', 80, 'Canon: Supporting Standards under Wi‑Fi'),\n\n      -- Flash compatibility\n      ('compatible_e_ttl_speedlites',         '^compatible\\\\\\\\s*e-?ttl\\\\\\\\s*speedlites$',             '^external\\\\\\\\s*speedlite$', 70, 'Canon: compatible E‑TTL speedlites')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_spec_mapping_canon_camera_batch5
20251228012000	{"-- Seed migration (idempotent): Canon camera mapping batch 6\n-- Focus: remaining high-frequency Speedlite/HDR/Video/Interface/Customization labels.\n\nDO $$\nDECLARE\n  cat_id UUID;\n  s_connect UUID;\n  s_video UUID;\n  s_other UUID;\n  s_photo UUID;\nBEGIN\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'mirrorless-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: product_category with slug=% not found. Run category seeds first.', 'mirrorless-cameras';\n  END IF;\n\n  SELECT id INTO s_connect FROM spec_section WHERE section_name='Connectivity'         AND category_id=cat_id;\n  SELECT id INTO s_video   FROM spec_section WHERE section_name='Videography Features' AND category_id=cat_id;\n  SELECT id INTO s_photo   FROM spec_section WHERE section_name='Photography Features' AND category_id=cat_id;\n  SELECT id INTO s_other   FROM spec_section WHERE section_name='Other Features'       AND category_id=cat_id;\n\n  -- Add missing definitions (safe to re-run)\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_photo,  'E‑TTL II Flash Meterings',               'e_ttl_ii_flash_meterings',      'text', NULL, cat_id, 1),\n    (s_photo,  'Flash Function Menu',                    'flash_function_menu',           'text', NULL, cat_id, 1),\n\n    -- HDR / Video features\n    (s_other,  'HDR PQ Shooting',                        'hdr_pq_shooting',               'text', NULL, cat_id, 1),\n    (s_video,  'Canon Log',                              'canon_log',                     'text', NULL, cat_id, 1),\n\n    -- Interface label variants (map into existing text terminals too, but keep canonical key for UI)\n    (s_connect,'Microphone Input Terminal',              'microphone_input_terminal',     'text', NULL, cat_id, 1),\n    (s_connect,'Wireless Remote Control',                'wireless_remote_control',       'text', NULL, cat_id, 1),\n    (s_connect,'Multi-function Shoe',                    'multi_function_shoe',           'text', NULL, cat_id, 1),\n\n    -- Customization\n    (s_other,  'Customize Buttons',                      'customize_buttons',             'text', NULL, cat_id, 1),\n    (s_other,  'Custom Controls',                        'custom_controls',               'text', NULL, cat_id, 1),\n\n    -- Minor content buckets (often low value, but frequent enough)\n    (s_other,  'Movies (Folder Name / Dual shooting)',   'movies_bucket',                 'text', NULL, cat_id, 0)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Canon mapping rules (section-scoped) (safe to re-run)\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT\n    sd.id,\n    v.extraction_pattern,\n    v.context_pattern,\n    v.priority,\n    v.notes\n  FROM (\n    VALUES\n      -- External Speedlite\n      ('e_ttl_ii_flash_meterings',   '^e-?ttl\\\\\\\\s*ii\\\\\\\\s*flash\\\\\\\\s*meterings?$',  '^external\\\\\\\\s*speedlite$', 75, 'Canon: E‑TTL II flash meterings'),\n      ('flash_function_menu',        '^flash\\\\\\\\s*function\\\\\\\\s*menu$',            '^external\\\\\\\\s*speedlite$', 75, 'Canon: flash function menu'),\n\n      -- HDR PQ Shooting appears under sections like \\"HDR Shooting - Still\\" and \\"HDR Shooting and Movie Recording\\"\n      ('hdr_pq_shooting',            '^hdr\\\\\\\\s*pq\\\\\\\\s*shooting$',                'hdr\\\\\\\\s*shooting',          75, 'Canon: HDR PQ shooting'),\n\n      -- Canon Log (Video Shooting)\n      ('canon_log',                  '^canon\\\\\\\\s*log$',                         '^video\\\\\\\\s*shooting$',      75, 'Canon: Canon Log'),\n\n      -- Interface variants\n      ('microphone_terminal',        '^microphone\\\\\\\\s*input\\\\\\\\s*terminal$',      '^interface$',              80, 'Canon: mic input terminal -> microphone_terminal'),\n      ('microphone_input_terminal',  '^microphone\\\\\\\\s*input\\\\\\\\s*terminal$',      '^interface$',              70, 'Canon: mic input terminal (dedicated key)'),\n      ('wireless_remote_control',    '^wireless\\\\\\\\s*remote\\\\\\\\s*control$',        '^interface$',              75, 'Canon: wireless remote control'),\n      ('multi_function_shoe',        '^multi-?function\\\\\\\\s*shoe$',              '^interface$',              75, 'Canon: multi-function shoe'),\n\n      -- Customization\n      ('customize_buttons',          '^customize\\\\\\\\s*buttons$',                  '^customization$',          75, 'Canon: customize buttons'),\n      ('custom_controls',            '^custom\\\\\\\\s*controls$',                    '^customization$',          75, 'Canon: custom controls'),\n\n      -- Bucket-ish grouping\n      ('movies_bucket',              '^movies$',                                '(folder\\\\\\\\s*name|dual\\\\\\\\s*shooting)', 60, 'Canon: Movies bucket')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_spec_mapping_canon_camera_batch6
20251228013000	{"-- Seed migration (idempotent): Canon camera mapping batch 7\n-- Focus: remaining high-value non-folder items after agreeing to skip folder/file-structure metadata.\n\nDO $$\nDECLARE\n  cat_id UUID;\n  s_sensor UUID;\n  s_optics UUID;\n  s_video UUID;\n  s_connect UUID;\n  s_image UUID;\n  s_display UUID;\n  s_other UUID;\nBEGIN\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'mirrorless-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: product_category with slug=% not found. Run category seeds first.', 'mirrorless-cameras';\n  END IF;\n\n  SELECT id INTO s_sensor  FROM spec_section WHERE section_name='Image Sensor'         AND category_id=cat_id;\n  SELECT id INTO s_optics  FROM spec_section WHERE section_name='Optics & Focus'       AND category_id=cat_id;\n  SELECT id INTO s_video   FROM spec_section WHERE section_name='Videography Features' AND category_id=cat_id;\n  SELECT id INTO s_connect FROM spec_section WHERE section_name='Connectivity'         AND category_id=cat_id;\n  SELECT id INTO s_image   FROM spec_section WHERE section_name='Image'                AND category_id=cat_id;\n  SELECT id INTO s_display FROM spec_section WHERE section_name='Display'              AND category_id=cat_id;\n  SELECT id INTO s_other   FROM spec_section WHERE section_name='Other Features'       AND category_id=cat_id;\n\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_optics,  'Focus Mode Switch',                    'focus_mode_switch',                    'text', NULL, cat_id, 1),\n    (s_optics,  'Focusing Brightness Range (Movie)',    'focusing_brightness_range_movie',      'text', NULL, cat_id, 1),\n    (s_connect, 'Cloud RAW Processing (image.canon)',   'cloud_raw_processing_image_canon',     'text', NULL, cat_id, 0),\n\n    (s_display, 'Grid Display',                         'grid_display',                         'text', NULL, cat_id, 1),\n    (s_image,   'Movie Digital IS',                     'movie_digital_is',                     'text', NULL, cat_id, 1),\n    (s_other,   'HDR Mode',                             'hdr_mode',                             'text', NULL, cat_id, 1)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT\n    sd.id,\n    v.extraction_pattern,\n    v.context_pattern,\n    v.priority,\n    v.notes\n  FROM (\n    VALUES\n      -- Autofocus\n      ('focus_mode_switch',                 '^focus\\\\\\\\s*mode\\\\\\\\s*switch$',                      '^autofocus$', 75, 'Canon: focus mode switch'),\n      -- Handle both clean and mangled label variants (the @999br/> artifact)\n      ('focusing_brightness_range_movie',   '^focusing\\\\\\\\s*brightness\\\\\\\\s*range.*movie\\\\\\\\s*recording\\\\\\\\)?$', '^autofocus$', 80, 'Canon: focusing brightness range (movie recording)'),\n      ('focusing_brightness_range_movie',   '^focusing\\\\\\\\s*brightness\\\\\\\\s*range\\\\\\\\s*\\\\\\\\(in\\\\\\\\s*movie\\\\\\\\s*recording\\\\\\\\)$', '^autofocus$', 80, 'Canon: focusing brightness range (in movie recording)'),\n\n      -- Wi‑Fi feature (kept as text; low importance)\n      ('cloud_raw_processing_image_canon',  '^cloud\\\\\\\\s*raw\\\\\\\\s*image\\\\\\\\s*processing\\\\\\\\s*via\\\\\\\\s*image\\\\\\\\.canon', 'wi-?fi', 60, 'Canon: Cloud RAW processing via image.canon'),\n\n      -- Grid display appears under Viewfinder and Live View Functions\n      ('grid_display',                      '^grid\\\\\\\\s*display$',                               '(viewfinder|live\\\\\\\\s*view\\\\\\\\s*functions)', 70, 'Canon: grid display'),\n\n      -- Movie Digital IS appears in multiple sections\n      ('movie_digital_is',                  '^movie\\\\\\\\s*digital\\\\\\\\s*is$',                         '(image\\\\\\\\s*stabilization|video\\\\\\\\s*shooting)', 70, 'Canon: Movie Digital IS'),\n\n      -- HDR mode\n      ('hdr_mode',                          '^hdr\\\\\\\\s*mode$',                                   '^hdr\\\\\\\\s*shooting$', 70, 'Canon: HDR mode')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_spec_mapping_canon_camera_batch7
20251228014000	{"-- Seed migration (idempotent): Canon camera mapping batch 8\n-- Focus: mop-up of remaining non-folder items (pixels/type ambiguity, low-pass/dust label variants, display sizing).\n\nDO $$\nDECLARE\n  cat_id UUID;\n  s_sensor UUID;\n  s_display UUID;\n  s_optics UUID;\nBEGIN\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'mirrorless-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: product_category with slug=% not found. Run category seeds first.', 'mirrorless-cameras';\n  END IF;\n\n  SELECT id INTO s_sensor  FROM spec_section WHERE section_name='Image Sensor'   AND category_id=cat_id;\n  SELECT id INTO s_display FROM spec_section WHERE section_name='Display'        AND category_id=cat_id;\n  SELECT id INTO s_optics  FROM spec_section WHERE section_name='Optics & Focus' AND category_id=cat_id;\n\n  -- Add missing definitions (safe to re-run)\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_display, 'Exposure Simulation', 'exposure_simulation', 'text', NULL, cat_id, 1)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Canon mapping rules (section-scoped) (safe to re-run)\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT\n    sd.id,\n    v.extraction_pattern,\n    v.context_pattern,\n    v.priority,\n    v.notes\n  FROM (\n    VALUES\n      -- Pixels label is ambiguous; scope tightly by section\n      ('effective_pixels',   '^pixels$',     '^image\\\\\\\\s*sensor$', 85, 'Canon: Image Sensor Pixels -> effective_pixels'),\n      ('screen_dots',        '^pixels$',     '^lcd\\\\\\\\s*monitor$',  85, 'Canon: LCD Monitor Pixels (dots) -> screen_dots'),\n\n      -- \\"Type\\" label is ambiguous; scope by section\n      ('autofocus',          '^type$',       '^autofocus$',       80, 'Canon: Autofocus Type -> autofocus system'),\n      ('lcd_type',           '^type$',       '^lcd\\\\\\\\s*monitor$',  80, 'Canon: LCD Monitor Type -> lcd_type'),\n\n      -- Canon label variants\n      ('low_pass_filter',    '^low-?pass\\\\\\\\s*filter$', 'image\\\\\\\\s*sensor', 80, 'Canon: Low-pass Filter -> low_pass_filter'),\n      ('dust_deletion_feature','^dust\\\\\\\\s*deletion\\\\\\\\s*feature.*self\\\\\\\\s*cleaning\\\\\\\\s*sensor\\\\\\\\s*unit$', 'image\\\\\\\\s*sensor', 80, 'Canon: Dust Deletion Feature (Self Cleaning Sensor Unit) -> dust_deletion_feature'),\n\n      -- LCD Screen label variants\n      ('screen_size',        '^size$',       '^lcd\\\\\\\\s*screen$',   75, 'Canon: LCD Screen Size -> screen_size'),\n      ('screen_dots',        '^resolution$', '^lcd\\\\\\\\s*screen$',   75, 'Canon: LCD Screen Resolution (dots) -> screen_dots'),\n      ('lcd_coating',        '^coatings?$',  '^lcd\\\\\\\\s*screen$',   70, 'Canon: LCD Screen Coatings -> lcd_coating'),\n\n      -- Viewfinder misc (low frequency but clean)\n      ('exposure_simulation','^exposure\\\\\\\\s*simulation$', '^viewfinder$', 70, 'Canon: Exposure Simulation')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_spec_mapping_canon_camera_batch8
20251228015000	{"-- Product Images / Assets\n-- Stores discovered product image URLs (gallery, primary, etc.)\n\n-- Supabase-friendly UUID generator\nCREATE EXTENSION IF NOT EXISTS \\"pgcrypto\\"","CREATE TABLE IF NOT EXISTS product_image (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n\n    product_id UUID REFERENCES product(id) ON DELETE CASCADE NOT NULL,\n\n    url TEXT NOT NULL,\n    kind TEXT,        -- e.g. 'primary', 'gallery', 'thumbnail'\n    sort_order INTEGER,\n\n    source_url TEXT,  -- product page where the image link was found\n    raw_metadata JSONB,\n\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n\n    UNIQUE (product_id, url)\n)","CREATE INDEX IF NOT EXISTS idx_product_image_product_id ON product_image(product_id)","CREATE INDEX IF NOT EXISTS idx_product_image_kind ON product_image(kind)","CREATE INDEX IF NOT EXISTS idx_product_image_url ON product_image(url)"}	add_product_image
20251228014500	{"-- Seed migration (idempotent): lens product categories\n-- Ensures 'lenses' and lens subcategories exist before lens spec taxonomy seeds.\n\nDO $$\nDECLARE\n  lenses_id UUID;\nBEGIN\n  -- Root: Lenses\n  INSERT INTO product_category (name, slug, display_order, icon_name)\n  VALUES ('Lenses', 'lenses', 20, 'aperture')\n  ON CONFLICT (slug) DO NOTHING;\n\n  SELECT id INTO lenses_id FROM product_category WHERE slug = 'lenses';\n\n  -- Subcategories: Lens types\n  INSERT INTO product_category (name, slug, parent_category_id, display_order) VALUES\n    ('Mirrorless Lenses', 'mirrorless-lenses', lenses_id, 10),\n    ('DSLR Lenses', 'dslr-lenses', lenses_id, 20),\n    ('Cinema Lenses', 'cinema-lenses', lenses_id, 30),\n    ('Rangefinder Lenses', 'rangefinder-lenses', lenses_id, 40),\n    ('Lens Adapters', 'lens-adapters', lenses_id, 50),\n    ('Teleconverters', 'teleconverters', lenses_id, 60),\n    ('Lens Filters', 'lens-filters', lenses_id, 70)\n  ON CONFLICT (slug) DO NOTHING;\nEND $$"}	seed_lens_categories
