20260210000001	{"-- Batch 2: additional context patterns for lens spec mappings\n-- Covers section name variants found in cinema/broadcast lenses (Main Unit Spec, General, etc.)\n\nDO $$\nBEGIN\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT sd.id, v.extraction_pattern, v.context_pattern, v.priority, v.notes\n  FROM (VALUES\n\n    -- Weight appears under Lens, General, Main Unit Spec(s) in cinema lenses\n    ('lens_weight', '^weight$',          '^lens$',              88, 'Canon lens: Weight under Lens section'),\n    ('lens_weight', '^weight$',          '^general$',           85, 'Canon lens: Weight under General'),\n    ('lens_weight', '^weight$',          'main\\\\\\\\s*unit\\\\\\\\s*spec', 85, 'Canon lens: Weight under Main Unit Spec'),\n    ('lens_weight', 'approx\\\\\\\\.?\\\\\\\\s*mass','main\\\\\\\\s*unit\\\\\\\\s*spec', 80, 'Canon lens: Approx Mass under Main Unit Spec'),\n\n    -- Lens Construction also appears under Lens and Main Unit Spec\n    ('lens_construction', 'lens\\\\\\\\s*construction', '^lens$',              83, 'Canon lens: Lens Construction under Lens'),\n    ('lens_construction', 'lens\\\\\\\\s*construction', 'main\\\\\\\\s*unit\\\\\\\\s*spec', 80, 'Canon lens: Lens Construction under Main Unit Spec'),\n\n    -- Zoom Ratio appears across many section names\n    ('zoom_ratio', 'zoom\\\\\\\\s*ratio', '^general$',           85, 'Canon lens: Zoom Ratio under General'),\n    ('zoom_ratio', 'zoom\\\\\\\\s*ratio', 'main\\\\\\\\s*unit\\\\\\\\s*spec', 82, 'Canon lens: Zoom Ratio under Main Unit Spec'),\n    ('zoom_ratio', 'zoom\\\\\\\\s*ratio', 'image\\\\\\\\s*composition', 80, 'Canon lens: Zoom Ratio under Image Composition'),\n    ('zoom_ratio', 'zoom\\\\\\\\s*ratio', '^product$',           78, 'Canon lens: Zoom Ratio under Product'),\n\n    -- Dust Cap (accessories - not mapped before)\n    ('included_lens_cap', 'dust\\\\\\\\s*cap', 'accessories', 68, 'Canon lens: Dust Cap under Accessories'),\n\n    -- Lens Case variants\n    ('included_lens_case', 'lens\\\\\\\\s*case', '^lens$', 68, 'Canon lens: Lens Case under Lens'),\n\n    -- Filter size also under Lens section directly\n    ('filter_thread_diameter', 'filter\\\\\\\\s*size(\\\\\\\\s*diameter)?', '^lens$', 88, 'Canon lens: Filter Size under Lens'),\n\n    -- Closest Focusing Distance (cinema lenses use this label instead)\n    ('min_focus_distance', 'closest\\\\\\\\s*focus(ing)?\\\\\\\\s*distance', 'main\\\\\\\\s*unit\\\\\\\\s*spec', 82, 'Canon lens: Closest Focusing Distance'),\n    ('min_focus_distance', 'minimum\\\\\\\\s*shooting\\\\\\\\s*distance',    'main\\\\\\\\s*unit\\\\\\\\s*spec', 80, 'Canon lens: Min Shooting Distance'),\n    ('min_focus_distance', 'mod\\\\\\\\s*from\\\\\\\\s*(image\\\\\\\\s*)?sensor',  'main\\\\\\\\s*unit\\\\\\\\s*spec', 78, 'Canon lens: MOD from sensor'),\n\n    -- Focal Length variants in cinema lenses\n    ('focal_length', 'focal\\\\\\\\s*length\\\\\\\\s*(range|&)', 'main\\\\\\\\s*unit\\\\\\\\s*spec', 78, 'Canon lens: Focal Length Range under Main Unit Spec'),\n\n    -- Aperture in cinema lenses uses different labels\n    ('lens_aperture_range', 'maximum\\\\\\\\s*relative\\\\\\\\s*aperture', 'main\\\\\\\\s*unit\\\\\\\\s*spec', 82, 'Canon lens: Max Relative Aperture'),\n    ('lens_aperture_range', 'maximum\\\\\\\\s*photometric\\\\\\\\s*aperture', 'main\\\\\\\\s*unit\\\\\\\\s*spec', 80, 'Canon lens: Max Photometric Aperture'),\n    ('lens_aperture_range', 'f-number',                           'main\\\\\\\\s*unit\\\\\\\\s*spec', 78, 'Canon lens: F-Number under Main Unit Spec'),\n\n    -- Physical dimensions in cinema lenses\n    ('lens_dimensions', '^(width|height|length)$',               'main\\\\\\\\s*unit\\\\\\\\s*spec', 78, 'Canon lens: W/H/L under Main Unit Spec'),\n    ('lens_dimensions', 'dimensions\\\\\\\\s*\\\\\\\\(w\\\\\\\\s*x\\\\\\\\s*h',          'main\\\\\\\\s*unit\\\\\\\\s*spec', 80, 'Canon lens: WxHxL under Main Unit Spec'),\n    ('lens_dimensions', 'outer\\\\\\\\s*dimensions',                    'main\\\\\\\\s*unit\\\\\\\\s*spec', 80, 'Canon lens: Outer Dimensions'),\n    ('lens_weight',     'approx\\\\\\\\.?\\\\\\\\s*weight',                   'main\\\\\\\\s*unit\\\\\\\\s*spec', 80, 'Canon lens: Approx Weight')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1 FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_spec_definitions_lens_batch2
20260210000002	{"-- Batch 3: mapping rules for cinema/broadcast lens section variants\n-- Covers Physical Attributes, Image Composition, Exterior Design sections\n-- and angular/diagonal angle of view label variants.\n\nDO $$\nBEGIN\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT sd.id, v.extraction_pattern, v.context_pattern, v.priority, v.notes\n  FROM (VALUES\n\n    -- === Angle of View ===\n    -- Cinema lenses use \\"Angular Field of View\\" and \\"Diagonal Angle of View\\"\n    -- under Main Unit Spec / Image Composition instead of plain \\"Angle of view\\"\n    ('angle_of_view', 'angular\\\\\\\\s*(field\\\\\\\\s*of\\\\\\\\s*)?view',  'main\\\\\\\\s*unit\\\\\\\\s*spec',   85, 'Canon lens: Angular (Field of) View under Main Unit Spec'),\n    ('angle_of_view', 'angular\\\\\\\\s*(field\\\\\\\\s*of\\\\\\\\s*)?view',  'image\\\\\\\\s*composition',   83, 'Canon lens: Angular (Field of) View under Image Composition'),\n    ('angle_of_view', 'diagonal\\\\\\\\s*angle\\\\\\\\s*of\\\\\\\\s*view',    'main\\\\\\\\s*unit\\\\\\\\s*spec',   82, 'Canon lens: Diagonal Angle of View under Main Unit Spec'),\n    ('angle_of_view', 'diagonal\\\\\\\\s*angle\\\\\\\\s*of\\\\\\\\s*view',    'image\\\\\\\\s*composition',   80, 'Canon lens: Diagonal Angle of View under Image Composition'),\n    ('angle_of_view', 'angle\\\\\\\\s*of\\\\\\\\s*view',                'main\\\\\\\\s*unit\\\\\\\\s*spec',   80, 'Canon lens: Angle of View under Main Unit Spec'),\n    ('angle_of_view', 'angle\\\\\\\\s*of\\\\\\\\s*view',                'image\\\\\\\\s*composition',   78, 'Canon lens: Angle of View under Image Composition'),\n\n    -- === Focal Length under Image Composition (cinema lenses) ===\n    ('focal_length', 'focal\\\\\\\\s*length(\\\\\\\\s*range)?',         'image\\\\\\\\s*composition',   82, 'Canon lens: Focal Length (Range) under Image Composition'),\n\n    -- === Weight under Physical Attributes / Physical Specifications ===\n    ('lens_weight', '^weight$',                             'physical\\\\\\\\s*attributes', 85, 'Canon lens: Weight under Physical Attributes'),\n    ('lens_weight', '^weight$',                             'physical\\\\\\\\s*spec',       82, 'Canon lens: Weight under Physical Spec(ifications)'),\n    ('lens_weight', 'max\\\\\\\\.?\\\\\\\\s*diameter.{0,10}weight',     'main\\\\\\\\s*unit\\\\\\\\s*spec',   80, 'Canon lens: Max. Diameter x Length, Weight under Main Unit Spec'),\n    ('lens_weight', 'max\\\\\\\\.?\\\\\\\\s*diameter.{0,10}weight',     'physical\\\\\\\\s*attributes', 78, 'Canon lens: Max. Diameter x Length, Weight under Physical Attributes'),\n\n    -- === Dimensions under Physical Attributes / Main Unit Specs (plural) ===\n    ('lens_dimensions', '^dimensions$',                     'physical\\\\\\\\s*attributes', 85, 'Canon lens: Dimensions under Physical Attributes'),\n    ('lens_dimensions', '^dimensions$',                     'main\\\\\\\\s*unit\\\\\\\\s*specs',  83, 'Canon lens: Dimensions under Main Unit Specs'),\n    ('lens_dimensions', '^(width|height|length)$',          'physical\\\\\\\\s*attributes', 78, 'Canon lens: W/H/L under Physical Attributes'),\n\n    -- === Dust / Weather Sealing under Exterior Design ===\n    -- Current rule requires context ^lens$; cinema lenses put this under Exterior Design\n    ('lens_weather_sealing', 'dust.{0,10}weather',          'exterior\\\\\\\\s*design',     82, 'Canon lens: Dust/Weather under Exterior Design'),\n    ('lens_weather_sealing', 'dust.{0,10}weather',          'main\\\\\\\\s*unit\\\\\\\\s*spec',   80, 'Canon lens: Dust/Weather under Main Unit Spec'),\n\n    -- === Max Magnification under Image Composition ===\n    ('max_magnification', 'max(imum)?\\\\\\\\s*magnification',    'image\\\\\\\\s*composition',   82, 'Canon lens: Max Magnification under Image Composition'),\n    ('max_magnification', 'max(imum)?\\\\\\\\s*magnification',    'main\\\\\\\\s*unit\\\\\\\\s*spec',   80, 'Canon lens: Max Magnification under Main Unit Spec'),\n\n    -- === Min Focus Distance under Image Composition ===\n    ('min_focus_distance', 'min(imum)?\\\\\\\\s*focus(ing)?\\\\\\\\s*distance', 'image\\\\\\\\s*composition', 82, 'Canon lens: Min Focus Distance under Image Composition'),\n\n    -- === Image Stabilization under Exterior Design / General ===\n    ('lens_image_stabilization', 'image\\\\\\\\s*stabilization', 'exterior\\\\\\\\s*design',      78, 'Canon lens: IS under Exterior Design'),\n    ('lens_image_stabilization', 'image\\\\\\\\s*stabilization', '^general$',               75, 'Canon lens: IS under General'),\n\n    -- === Filter Thread Diameter under Physical Attributes ===\n    ('filter_thread_diameter', 'filter\\\\\\\\s*size(\\\\\\\\s*diameter)?', 'physical\\\\\\\\s*attributes', 82, 'Canon lens: Filter Size under Physical Attributes'),\n\n    -- === Aperture Blades under Physical Attributes ===\n    ('aperture_blades', 'aperture\\\\\\\\s*blades?',              'physical\\\\\\\\s*attributes', 80, 'Canon lens: Aperture Blades under Physical Attributes')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1 FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_spec_definitions_lens_batch3
20260210000003	{"-- Batch 4: fill remaining gaps found after batch3 normalization pass\n-- Fixes too-short regex ranges and adds missing context variants.\n\nDO $$\nBEGIN\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT sd.id, v.extraction_pattern, v.context_pattern, v.priority, v.notes\n  FROM (VALUES\n\n    -- === Aperture Blades under Lens and Main Unit Spec ===\n    -- Existing rule only covers optical_design context\n    ('aperture_blades', 'aperture\\\\\\\\s*blades?',              '^lens$',                 82, 'Canon lens: Aperture Blades under Lens'),\n    ('aperture_blades', 'aperture\\\\\\\\s*blades?',              'main\\\\\\\\s*unit\\\\\\\\s*spec',   80, 'Canon lens: Aperture Blades under Main Unit Spec'),\n\n    -- === Special Elements under Lens and Main Unit Spec ===\n    -- Existing rule only covers optical_design context\n    ('lens_special_elements', 'special\\\\\\\\s*(lens\\\\\\\\s*)?elements?', '^lens$',            82, 'Canon lens: Special Elements under Lens'),\n    ('lens_special_elements', 'special\\\\\\\\s*(lens\\\\\\\\s*)?elements?', 'main\\\\\\\\s*unit\\\\\\\\s*spec', 80, 'Canon lens: Special Elements under Main Unit Spec'),\n\n    -- === Dimensions under Main Unit Spec (singular, not covered by batch3) ===\n    -- batch3 covered physical_attributes and main_unit_specs (plural) but missed singular\n    ('lens_dimensions', '^dimensions$',                     'main\\\\\\\\s*unit\\\\\\\\s*spec',   83, 'Canon lens: Dimensions under Main Unit Spec'),\n\n    -- === Minimum Overall Length ===\n    ('lens_dimensions', 'min(imum)?\\\\\\\\s*overall\\\\\\\\s*length',  '^lens$',                 78, 'Canon lens: Minimum Overall Length under Lens'),\n    ('lens_dimensions', 'min(imum)?\\\\\\\\s*overall\\\\\\\\s*length',  'main\\\\\\\\s*unit\\\\\\\\s*spec',   76, 'Canon lens: Minimum Overall Length under Main Unit Spec'),\n\n    -- === Front Diameter → filter thread diameter ===\n    -- Cinema lenses list the front element diameter separately\n    ('filter_thread_diameter', 'front\\\\\\\\s*diameter',         'main\\\\\\\\s*unit\\\\\\\\s*spec',   78, 'Canon lens: Front Diameter under Main Unit Spec'),\n    ('filter_thread_diameter', 'front\\\\\\\\s*diameter',         '^general$',              75, 'Canon lens: Front Diameter under General'),\n    ('filter_thread_diameter', 'front\\\\\\\\s*diameter',         'physical\\\\\\\\s*attributes', 75, 'Canon lens: Front Diameter under Physical Attributes'),\n    ('filter_thread_diameter', 'front\\\\\\\\s*diameter',         'main\\\\\\\\s*unit\\\\\\\\s*specs',  75, 'Canon lens: Front Diameter under Main Unit Specs'),\n\n    -- === Max. Diameter x Length, Weight (batch3 regex too short: used .{0,10}) ===\n    -- \\"Max. Diameter x Length, Weight\\" has ~14 chars between \\"diameter\\" and \\"weight\\"\n    ('lens_weight', 'max\\\\\\\\.?\\\\\\\\s*diameter.{0,25}weight',     'main\\\\\\\\s*unit\\\\\\\\s*spec',   80, 'Canon lens: Max Diameter+Length+Weight under Main Unit Spec'),\n    ('lens_weight', 'max\\\\\\\\.?\\\\\\\\s*diameter.{0,25}weight',     'physical\\\\\\\\s*attributes', 78, 'Canon lens: Max Diameter+Length+Weight under Physical Attributes'),\n\n    -- === Maximum Relative Aperture under Optical Brightness (cinema) ===\n    ('lens_aperture_range', 'maximum\\\\\\\\s*relative\\\\\\\\s*aperture', 'optical\\\\\\\\s*brightness', 82, 'Canon lens: Max Relative Aperture under Optical Brightness'),\n    ('lens_aperture_range', 'maximum\\\\\\\\s*photometric\\\\\\\\s*aperture', 'optical\\\\\\\\s*brightness', 80, 'Canon lens: Max Photometric Aperture under Optical Brightness'),\n\n    -- === Focusing Method → focus drive system ===\n    ('focus_drive_system', 'focus(ing)?\\\\\\\\s*method',         'main\\\\\\\\s*unit\\\\\\\\s*specs',  82, 'Canon lens: Focusing Method under Main Unit Specs'),\n    ('focus_drive_system', 'focus(ing)?\\\\\\\\s*method',         'autofocus',              80, 'Canon lens: Focusing Method under Autofocus'),\n    ('focus_drive_system', 'focus(ing)?\\\\\\\\s*method',         'main\\\\\\\\s*unit\\\\\\\\s*spec',   78, 'Canon lens: Focusing Method under Main Unit Spec'),\n\n    -- === MOD From Front of Lens → min focus distance ===\n    -- Different from \\"MOD from image sensor\\" but the closest existing definition\n    ('min_focus_distance', 'mod\\\\\\\\s*from\\\\\\\\s*front',          'scene\\\\\\\\s*composition',   76, 'Canon lens: MOD from Front under Scene Composition'),\n    ('min_focus_distance', 'mod\\\\\\\\s*from\\\\\\\\s*front',          'main\\\\\\\\s*unit\\\\\\\\s*spec',   74, 'Canon lens: MOD from Front under Main Unit Spec'),\n\n    -- === Iris Ring → lens control ring (cinema manual iris control) ===\n    ('lens_control_ring', 'iris\\\\\\\\s*ring',                   'exterior\\\\\\\\s*design',     78, 'Canon lens: Iris Ring under Exterior Design'),\n    ('lens_control_ring', 'iris\\\\\\\\s*ring',                   'main\\\\\\\\s*unit\\\\\\\\s*spec',   75, 'Canon lens: Iris Ring under Main Unit Spec')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1 FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_spec_definitions_lens_batch4
20260210000004	{"-- Batch 5: cover additional section contexts for focal_length, focus_drive_system,\n-- aperture_blades, lens_dimensions, and fulltime_manual_focus.\n\nDO $$\nBEGIN\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT sd.id, v.extraction_pattern, v.context_pattern, v.priority, v.notes\n  FROM (VALUES\n\n    -- === Focal Length under cinema/broadcast sections ===\n    -- Existing rule only covers ^lens$ context\n    ('focal_length', 'focal\\\\\\\\s*length(\\\\\\\\s*range)?',     '^general$',            85, 'Canon lens: Focal Length under General'),\n    ('focal_length', 'focal\\\\\\\\s*length(\\\\\\\\s*range)?',     'main\\\\\\\\s*unit\\\\\\\\s*spec', 83, 'Canon lens: Focal Length under Main Unit Spec'),\n    ('focal_length', 'focal\\\\\\\\s*length(\\\\\\\\s*range)?',     'main\\\\\\\\s*unit\\\\\\\\s*specs', 83, 'Canon lens: Focal Length under Main Unit Specs'),\n\n    -- === Focus Drive System under Lens and AF sections ===\n    -- Existing rule only covers focusing context\n    ('focus_drive_system', 'focus(ing)?\\\\\\\\s*drive\\\\\\\\s*system', '^lens$',           83, 'Canon lens: Focus Drive System under Lens'),\n    ('focus_drive_system', 'focus(ing)?\\\\\\\\s*drive\\\\\\\\s*system', '^af$',             80, 'Canon lens: Focus Drive System under AF'),\n    ('focus_drive_system', 'focus(ing)?\\\\\\\\s*drive\\\\\\\\s*system', 'main\\\\\\\\s*unit\\\\\\\\s*spec', 78, 'Canon lens: Focus Drive System under Main Unit Spec'),\n\n    -- === Number of Blades → aperture_blades ===\n    -- Canon pages use both \\"Aperture Blades\\" and \\"Number of Blades\\"\n    ('aperture_blades', 'number\\\\\\\\s*of\\\\\\\\s*(aperture\\\\\\\\s*)?blades?', 'main\\\\\\\\s*unit\\\\\\\\s*spec',   82, 'Canon lens: Number of Blades under Main Unit Spec'),\n    ('aperture_blades', 'number\\\\\\\\s*of\\\\\\\\s*(aperture\\\\\\\\s*)?blades?', 'image\\\\\\\\s*composition',   80, 'Canon lens: Number of Blades under Image Composition'),\n    ('aperture_blades', 'number\\\\\\\\s*of\\\\\\\\s*(aperture\\\\\\\\s*)?blades?', '^lens$',                 82, 'Canon lens: Number of Blades under Lens'),\n    ('aperture_blades', 'number\\\\\\\\s*of\\\\\\\\s*(aperture\\\\\\\\s*)?blades?', 'optical\\\\\\\\s*design',      80, 'Canon lens: Number of Blades under Optical Design'),\n\n    -- === Maximum Diameter → lens_dimensions ===\n    ('lens_dimensions', 'maximum\\\\\\\\s*diameter',           '^lens$',               78, 'Canon lens: Maximum Diameter under Lens'),\n    ('lens_dimensions', 'maximum\\\\\\\\s*diameter',           'main\\\\\\\\s*unit\\\\\\\\s*spec', 76, 'Canon lens: Maximum Diameter under Main Unit Spec'),\n\n    -- === Focus Adjustment → fulltime_manual_focus ===\n    -- Values are typically \\"AF with full-time manual\\" confirming this is the right key\n    ('fulltime_manual_focus', 'focus\\\\\\\\s*adjustment',     'main\\\\\\\\s*unit\\\\\\\\s*spec', 78, 'Canon lens: Focus Adjustment under Main Unit Spec'),\n    ('fulltime_manual_focus', 'focus\\\\\\\\s*adjustment',     'focusing',             76, 'Canon lens: Focus Adjustment under Focusing'),\n\n    -- === Close-up Lenses (accessories compatibility) ===\n    ('included_lens_cap', 'close.?up\\\\\\\\s*lens(es)?',      'accessories',          65, 'Canon lens: Close-up Lens accessory (closest match)'),\n\n    -- === Lens Coating under Lens section (in addition to Optical Design) ===\n    ('lens_coating', 'lens\\\\\\\\s*coating',                  '^lens$',               78, 'Canon lens: Lens Coating under Lens'),\n    ('lens_coating', 'lens\\\\\\\\s*coating',                  'main\\\\\\\\s*unit\\\\\\\\s*spec', 75, 'Canon lens: Lens Coating under Main Unit Spec'),\n\n    -- === IS Mode variants ===\n    ('lens_image_stabilization', 'is\\\\\\\\s*(mode|system)',  'main\\\\\\\\s*unit\\\\\\\\s*spec', 78, 'Canon lens: IS Mode under Main Unit Spec'),\n    ('lens_image_stabilization', 'is\\\\\\\\s*(mode|system)',  '^general$',            75, 'Canon lens: IS Mode under General')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1 FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_spec_definitions_lens_batch5
20260211000000	{"-- Migration: cinema-cameras product category, spec sections, definitions, and mapping rules.\n-- Derived from ARRI ALEXA LF and Sony Venice 2 spec sheets.\n-- Safe to re-run: all inserts use ON CONFLICT DO NOTHING guards.\n\nDO $$\nDECLARE\n  cameras_id  UUID;\n  cat_id      UUID;\n\n  s_general   UUID;\n  s_sensor    UUID;\n  s_recording UUID;\n  s_optics    UUID;\n  s_color     UUID;\n  s_audio     UUID;\n  s_connect   UUID;\n  s_physical  UUID;\nBEGIN\n\n  -- ----------------------------------------------------------------\n  -- 1. Ensure parent 'cameras' category exists\n  -- ----------------------------------------------------------------\n  SELECT id INTO cameras_id FROM product_category WHERE slug = 'cameras';\n  IF cameras_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: product_category with slug=cameras not found. Run category seeds first.';\n  END IF;\n\n  -- ----------------------------------------------------------------\n  -- 2. Add 'cinema-cameras' subcategory\n  -- ----------------------------------------------------------------\n  INSERT INTO product_category (name, slug, parent_category_id, display_order, icon_name)\n  VALUES ('Cinema Cameras', 'cinema-cameras', cameras_id, 20, 'video')\n  ON CONFLICT (slug) DO NOTHING;\n\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'cinema-cameras';\n\n  -- ----------------------------------------------------------------\n  -- 3. Spec sections\n  -- ----------------------------------------------------------------\n  INSERT INTO spec_section (section_name, category_id, display_order) VALUES\n    ('General',        cat_id,  10),\n    ('Image Sensor',   cat_id,  20),\n    ('Recording',      cat_id,  30),\n    ('Optics & Mount', cat_id,  40),\n    ('Color Science',  cat_id,  50),\n    ('Audio',          cat_id,  60),\n    ('Connectivity',   cat_id,  70),\n    ('Physical',       cat_id,  80)\n  ON CONFLICT (section_name, category_id) DO NOTHING;\n\n  SELECT id INTO s_general   FROM spec_section WHERE section_name = 'General'        AND category_id = cat_id;\n  SELECT id INTO s_sensor    FROM spec_section WHERE section_name = 'Image Sensor'   AND category_id = cat_id;\n  SELECT id INTO s_recording FROM spec_section WHERE section_name = 'Recording'      AND category_id = cat_id;\n  SELECT id INTO s_optics    FROM spec_section WHERE section_name = 'Optics & Mount' AND category_id = cat_id;\n  SELECT id INTO s_color     FROM spec_section WHERE section_name = 'Color Science'  AND category_id = cat_id;\n  SELECT id INTO s_audio     FROM spec_section WHERE section_name = 'Audio'          AND category_id = cat_id;\n  SELECT id INTO s_connect   FROM spec_section WHERE section_name = 'Connectivity'   AND category_id = cat_id;\n  SELECT id INTO s_physical  FROM spec_section WHERE section_name = 'Physical'       AND category_id = cat_id;\n\n  -- ----------------------------------------------------------------\n  -- 4. Spec definitions\n  -- Keys are prefixed 'cinema_' where they would collide with mirrorless\n  -- definitions (e.g. sensor_size, weight) to keep the category-aware\n  -- SpecMapperService from cross-contaminating rules.\n  -- ----------------------------------------------------------------\n\n  -- General\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_general, 'Camera Type',        'cinema_body_type',       'text',    NULL,  cat_id, 8),\n    (s_general, 'Image Processor',    'cinema_image_processor', 'text',    NULL,  cat_id, 6)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Image Sensor\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_sensor, 'Sensor Type',                   'cinema_sensor_type',              'text',    NULL,  cat_id, 9),\n    (s_sensor, 'Sensor Size / Format',           'cinema_sensor_size',              'text',    NULL,  cat_id, 10),\n    (s_sensor, 'Sensor Dimensions',              'cinema_sensor_dimensions',        'text',    'mm',  cat_id, 8),\n    (s_sensor, 'Dynamic Range',                  'cinema_dynamic_range',            'text',    'stops', cat_id, 10),\n    (s_sensor, 'Base ISO / EI',                  'cinema_base_iso',                 'text',    NULL,  cat_id, 9),\n    (s_sensor, 'Dual Base ISO',                  'dual_base_iso',                   'boolean', NULL,  cat_id, 7),\n    (s_sensor, 'Maximum Frame Rate',             'cinema_max_fps',                  'number',  'fps', cat_id, 8),\n    (s_sensor, 'Anamorphic De-squeeze Support',  'anamorphic_desqueeze_supported',  'boolean', NULL,  cat_id, 9),\n    (s_sensor, 'Anamorphic Squeeze Factors',     'anamorphic_squeeze_factors',      'text',    NULL,  cat_id, 7)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Recording\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_recording, 'Recording Formats',         'cinema_recording_formats',   'text',    NULL, cat_id, 10),\n    (s_recording, 'Recording Media',           'cinema_recording_media',     'text',    NULL, cat_id, 9),\n    (s_recording, 'Internal Recording',        'cinema_internal_recording',  'boolean', NULL, cat_id, 8),\n    (s_recording, 'Max Recording Resolution',  'cinema_max_resolution',      'text',    NULL, cat_id, 9),\n    (s_recording, 'Internal ND Filter',        'cinema_internal_nd',         'text',    NULL, cat_id, 8)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Optics & Mount\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_optics, 'Lens Mount',               'cinema_lens_mount',           'text', NULL, cat_id, 10),\n    (s_optics, 'Flange Focal Distance',    'cinema_flange_focal_distance', 'text', 'mm', cat_id, 8),\n    (s_optics, 'Lens Metadata Support',    'cinema_lens_metadata',        'text', NULL, cat_id, 6)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Color Science\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_color, 'Log Format',          'cinema_log_format',    'text', NULL, cat_id, 10),\n    (s_color, 'Color Space',         'cinema_color_space',   'text', NULL, cat_id, 9),\n    (s_color, 'Color Output Modes',  'cinema_color_output',  'text', NULL, cat_id, 7),\n    (s_color, 'LUT Support',         'cinema_lut_support',   'boolean', NULL, cat_id, 6)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Audio\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_audio, 'Audio Channels',  'cinema_audio_channels', 'number', NULL,  cat_id, 6),\n    (s_audio, 'Audio Format',    'cinema_audio_format',   'text',   NULL,  cat_id, 5),\n    (s_audio, 'Audio Input',     'cinema_audio_input',    'text',   NULL,  cat_id, 5)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Connectivity\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_connect, 'Timecode I/O',    'cinema_timecode_io',  'boolean', NULL, cat_id, 8),\n    (s_connect, 'Genlock / Sync',  'cinema_genlock',      'boolean', NULL, cat_id, 7),\n    (s_connect, 'SDI Outputs',     'cinema_sdi_outputs',  'text',    NULL, cat_id, 7),\n    (s_connect, 'HDMI',            'cinema_hdmi',         'text',    NULL, cat_id, 5),\n    (s_connect, 'Wi-Fi',           'cinema_wifi',         'boolean', NULL, cat_id, 5),\n    (s_connect, 'Ethernet',        'cinema_ethernet',     'boolean', NULL, cat_id, 6),\n    (s_connect, 'Remote Control',  'cinema_remote',       'text',    NULL, cat_id, 5)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Physical\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_physical, 'Weight',                 'cinema_weight',         'number', 'g',  cat_id, 7),\n    (s_physical, 'Dimensions',             'cinema_dimensions',     'text',   NULL, cat_id, 6),\n    (s_physical, 'Power Input',            'cinema_power_input',    'text',   NULL, cat_id, 7),\n    (s_physical, 'Power Consumption',      'cinema_power_draw',     'text',   'W',  cat_id, 5),\n    (s_physical, 'Operating Temperature',  'cinema_operating_temp', 'text',   NULL, cat_id, 4),\n    (s_physical, 'Weather Sealed',         'cinema_weather_sealed', 'boolean', NULL, cat_id, 6)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\nEND $$","-- ----------------------------------------------------------------\n-- 5. Spec mapping rules\n-- Regex patterns cover ARRI and Sony spec sheet label conventions.\n-- Run in a separate block so section/definition UUIDs are committed.\n-- ----------------------------------------------------------------\n\nDO $$\nBEGIN\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT sd.id, v.extraction_pattern, v.context_pattern, v.priority, v.notes\n  FROM (VALUES\n\n    -- === General ===\n    ('cinema_body_type',\n      '(camera\\\\\\\\s*type|type\\\\\\\\b|body\\\\\\\\s*type)',\n      '(general|type)',\n      70, 'Cinema: body/camera type'),\n    ('cinema_image_processor',\n      '(image\\\\\\\\s*processor|processor\\\\\\\\b)',\n      '(general)',\n      65, 'Cinema: image processor'),\n\n    -- === Image Sensor ===\n    ('cinema_sensor_type',\n      '(sensor\\\\\\\\s*type|cmos\\\\\\\\b|alev\\\\\\\\b|bsi\\\\\\\\s*cmos)',\n      '(image\\\\\\\\s*sensor|sensor)',\n      85, 'Cinema: sensor technology (ALEV III, BSI CMOS, etc.)'),\n    ('cinema_sensor_size',\n      '(sensor\\\\\\\\s*(size|format|mode)|imager\\\\\\\\s*(size|format|mode)|format\\\\\\\\b)',\n      '(image\\\\\\\\s*sensor|sensor|imager)',\n      90, 'Cinema: sensor format (Large Format, Super 35, Full Frame)'),\n    ('cinema_sensor_dimensions',\n      '(sensor\\\\\\\\s*(maximum\\\\\\\\s*number\\\\\\\\s*of\\\\\\\\s*photosites\\\\\\\\s*and\\\\\\\\s*size|active\\\\\\\\s*image\\\\\\\\s*area|dimensions?)|photosite\\\\\\\\s*pitch)',\n      '(image\\\\\\\\s*sensor|sensor)',\n      75, 'Cinema: physical sensor dimensions in mm'),\n    ('cinema_dynamic_range',\n      '(dynamic\\\\\\\\s*range|latitude\\\\\\\\b|stops?\\\\\\\\s*(of\\\\\\\\s*)?(dynamic\\\\\\\\s*range|latitude))',\n      '(image\\\\\\\\s*sensor|sensor|dynamic|latitude|general)',\n      90, 'Cinema: dynamic range in stops (ARRI 14+, Venice 2 16)'),\n    ('cinema_base_iso',\n      '(base\\\\\\\\s*(iso|ei|sensitivity)|exposure\\\\\\\\s*index|native\\\\\\\\s*iso)',\n      '(image\\\\\\\\s*sensor|sensor|exposure|iso|general)',\n      85, 'Cinema: base EI / ISO (single or dual)'),\n    ('dual_base_iso',\n      '(dual\\\\\\\\s*base\\\\\\\\s*(iso|ei|sensitivity))',\n      '(image\\\\\\\\s*sensor|sensor|exposure|iso)',\n      80, 'Cinema: dual base ISO flag (Venice 2, ALEXA 35)'),\n    ('cinema_max_fps',\n      '(max(imum)?\\\\\\\\s*(frame\\\\\\\\s*rate|fps)|sensor\\\\\\\\s*frame\\\\\\\\s*rates?|high\\\\\\\\s*(frame\\\\\\\\s*rate|speed))',\n      '(image\\\\\\\\s*sensor|sensor|frame\\\\\\\\s*rate|recording)',\n      80, 'Cinema: maximum sensor frame rate'),\n    ('anamorphic_desqueeze_supported',\n      '(anamorphic\\\\\\\\s*(de-?squeeze|de\\\\\\\\s*squeeze|support|license|mode)|de-?squeeze)',\n      '(image\\\\\\\\s*sensor|sensor|anamorphic|recording|lens)',\n      85, 'Cinema: in-camera anamorphic de-squeeze support'),\n    ('anamorphic_squeeze_factors',\n      '(squeeze\\\\\\\\s*(factor|ratio)|lens\\\\\\\\s*squeeze\\\\\\\\s*factors?|anamorphic\\\\\\\\s*(ratio|squeeze\\\\\\\\s*ratio))',\n      '(image\\\\\\\\s*sensor|sensor|anamorphic|recording)',\n      80, 'Cinema: supported squeeze ratios (1.25, 1.33, 1.5, 1.65, 1.8, 2.0)'),\n\n    -- === Recording ===\n    ('cinema_recording_formats',\n      '(recording\\\\\\\\s*format|file\\\\\\\\s*(format|container)|codec\\\\\\\\b|arriraw|x-?ocn|prores\\\\\\\\b)',\n      '(recording|format|codec)',\n      90, 'Cinema: recording codecs/containers (ARRIRAW, X-OCN, ProRes)'),\n    ('cinema_recording_media',\n      '(recording\\\\\\\\s*media|storage\\\\\\\\s*media|memory\\\\\\\\s*(card|media)|capture\\\\\\\\s*drive|sxr\\\\\\\\b|axs\\\\\\\\b|sxs\\\\\\\\b|cfast)',\n      '(recording|media|storage)',\n      85, 'Cinema: recording media type (SXR, AXS, CFast)'),\n    ('cinema_internal_recording',\n      '(internal\\\\\\\\s*recording|on-?board\\\\\\\\s*recording)',\n      '(recording|storage)',\n      75, 'Cinema: records internally without external recorder'),\n    ('cinema_max_resolution',\n      '(max(imum)?\\\\\\\\s*(recording\\\\\\\\s*)?resolution|sensor\\\\\\\\s*active\\\\\\\\s*image\\\\\\\\s*area|recording\\\\\\\\s*file\\\\\\\\s*(container|image)\\\\\\\\s*size)',\n      '(recording|resolution|image\\\\\\\\s*sensor)',\n      85, 'Cinema: maximum recording resolution (4.5K, 6K, 8.6K)'),\n    ('cinema_internal_nd',\n      '(internal\\\\\\\\s*(nd|neutral\\\\\\\\s*density)|built.?in\\\\\\\\s*nd|(mechanical|motorized|servo)\\\\\\\\s*nd|fsnd|nd\\\\\\\\s*filter)',\n      '(recording|optics|nd|filter|general)',\n      80, 'Cinema: internal ND filter type and range'),\n\n    -- === Optics & Mount ===\n    ('cinema_lens_mount',\n      '(lens\\\\\\\\s*mount|mount\\\\\\\\s*type)',\n      '(optics|mount|lens)',\n      95, 'Cinema: lens mount (LPL, PL, E-mount lever lock)'),\n    ('cinema_flange_focal_distance',\n      '(flange\\\\\\\\s*(focal\\\\\\\\s*)?(depth|distance)|ffd\\\\\\\\b)',\n      '(optics|mount|lens)',\n      85, 'Cinema: flange focal distance in mm'),\n    ('cinema_lens_metadata',\n      '(lens\\\\\\\\s*(data|metadata|information)|lds\\\\\\\\b|cooke\\\\\\\\s*/i|zeiss\\\\\\\\s*extended|lens\\\\\\\\s*bus)',\n      '(optics|mount|lens)',\n      70, 'Cinema: supported lens metadata protocols (LDS, /i, eXtended Data)'),\n\n    -- === Color Science ===\n    ('cinema_log_format',\n      '(log\\\\\\\\s*(format|curve|profile|gamma)|log[-\\\\\\\\s]?c\\\\\\\\b|s-?log\\\\\\\\b|c-?log\\\\\\\\b|log\\\\\\\\s*(c[234]?|2|3)\\\\\\\\b)',\n      '(color|log|image|recording)',\n      90, 'Cinema: log format (ARRI LogC, S-Log3, C-Log2)'),\n    ('cinema_color_space',\n      '(color\\\\\\\\s*space|colour\\\\\\\\s*space|gamut|wide\\\\\\\\s*gamut|s-?gamut|arri\\\\\\\\s*wide|rec\\\\\\\\.?\\\\\\\\s*2020)',\n      '(color|gamut|image)',\n      85, 'Cinema: native color space / gamut'),\n    ('cinema_color_output',\n      '(color\\\\\\\\s*output|colour\\\\\\\\s*output|look\\\\\\\\s*(output|control)|output\\\\\\\\s*color)',\n      '(color|output|image)',\n      70, 'Cinema: color output modes (Rec 709, Rec 2020, Log C)'),\n    ('cinema_lut_support',\n      '(lut\\\\\\\\s*(support|import|loading)|look.?up\\\\\\\\s*table|3d\\\\\\\\s*lut|asc\\\\\\\\s*cdl)',\n      '(color|lut|workflow)',\n      65, 'Cinema: 3D LUT import/support'),\n\n    -- === Audio ===\n    ('cinema_audio_channels',\n      '(audio\\\\\\\\s*(channels?|recording)|channel\\\\\\\\s*(audio|count)|\\\\\\\\d+\\\\\\\\s*ch(annel)?)',\n      '(audio|sound)',\n      70, 'Cinema: number of audio channels'),\n    ('cinema_audio_format',\n      '(audio\\\\\\\\s*(format|encoding|bit\\\\\\\\s*depth)|pcm\\\\\\\\b|linear\\\\\\\\s*pcm|\\\\\\\\d+.?bit\\\\\\\\s*\\\\\\\\d+\\\\\\\\s*k?hz)',\n      '(audio|sound)',\n      65, 'Cinema: audio encoding format (PCM, 24-bit 48kHz)'),\n    ('cinema_audio_input',\n      '(audio\\\\\\\\s*input|xlr\\\\\\\\b|mic\\\\\\\\s*in|line\\\\\\\\s*in|\\\\\\\\d+.?pin.*xlr)',\n      '(audio|connectivity)',\n      60, 'Cinema: audio input connectors (XLR, etc.)'),\n\n    -- === Connectivity ===\n    ('cinema_timecode_io',\n      '(timecode|ltc\\\\\\\\b|smpte\\\\\\\\s*timecode|tc\\\\\\\\s*in|tc\\\\\\\\s*out)',\n      '(connectivity|timecode|interfaces?)',\n      85, 'Cinema: LTC/SMPTE timecode I/O'),\n    ('cinema_genlock',\n      '(genlock|sync\\\\\\\\s*(in|out|i/o)|tri-?level\\\\\\\\s*sync|bb(black\\\\\\\\s*burst)?)',\n      '(connectivity|sync|interfaces?)',\n      80, 'Cinema: genlock / external sync'),\n    ('cinema_sdi_outputs',\n      '(sdi\\\\\\\\s*(output|out|mon)|mon\\\\\\\\s*(out|output)|hd-?sdi|3g-?sdi|6g-?sdi|12g-?sdi)',\n      '(connectivity|output|interfaces?)',\n      80, 'Cinema: SDI monitor outputs'),\n    ('cinema_hdmi',\n      '(\\\\\\\\bhdmi\\\\\\\\b)',\n      '(connectivity|interfaces?)',\n      60, 'Cinema: HDMI output'),\n    ('cinema_wifi',\n      '(wi-?fi|wlan|wireless\\\\\\\\s*(lan|network)|ieee\\\\\\\\s*802\\\\\\\\.11)',\n      '(connectivity|wireless)',\n      65, 'Cinema: built-in Wi-Fi'),\n    ('cinema_ethernet',\n      '(ethernet\\\\\\\\b|\\\\\\\\brj-?45\\\\\\\\b|\\\\\\\\blemo.*ethernet|network\\\\\\\\s*(interface|port))',\n      '(connectivity|interfaces?)',\n      65, 'Cinema: Ethernet port'),\n    ('cinema_remote',\n      '(remote\\\\\\\\s*control|web\\\\\\\\s*(remote|interface|control)|rcp\\\\\\\\s*control)',\n      '(connectivity|remote)',\n      55, 'Cinema: remote control options'),\n\n    -- === Physical ===\n    ('cinema_weight',\n      '(\\\\\\\\bweight\\\\\\\\b)',\n      '(physical|body|dimensions)',\n      85, 'Cinema: camera body weight'),\n    ('cinema_dimensions',\n      '(dimensions?|size\\\\\\\\s*\\\\\\\\(h\\\\\\\\s*[x×]\\\\\\\\s*w|measurements?\\\\\\\\s*\\\\\\\\(h)',\n      '(physical|body|dimensions)',\n      80, 'Cinema: camera body dimensions'),\n    ('cinema_power_input',\n      '(power\\\\\\\\s*input|power\\\\\\\\s*supply|bat(tery)?\\\\\\\\s*(connector|adapter|input)|input\\\\\\\\s*voltage|v\\\\\\\\s*dc)',\n      '(physical|power)',\n      80, 'Cinema: power input spec (voltage, connector type)'),\n    ('cinema_power_draw',\n      '(power\\\\\\\\s*(consumption|draw|dissipation|requirement)|watt(s|age)?\\\\\\\\b)',\n      '(physical|power)',\n      70, 'Cinema: power consumption in watts'),\n    ('cinema_operating_temp',\n      '(operating\\\\\\\\s*temperature|temp(erature)?\\\\\\\\s*(range|operating)|working\\\\\\\\s*temperature)',\n      '(physical|environmental)',\n      55, 'Cinema: operating temperature range'),\n    ('cinema_weather_sealed',\n      '(dust.{0,10}(sand|splash|moisture|weather|sealed|proof)|splash\\\\\\\\s*proof|weather\\\\\\\\s*sealed|ingress\\\\\\\\s*protection)',\n      '(physical|body|environmental)',\n      65, 'Cinema: dust/moisture protection')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1 FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_cinema_camera_category
20260403000000	{"-- Migration: seed brand rows for ARRI and Sony.\n-- The cinema-cameras product_category and its spec_definitions already exist\n-- (see 20260211000000_seed_cinema_camera_category.sql).\n-- Safe to re-run: uses ON CONFLICT DO NOTHING guards.\n\nDO $$\nBEGIN\n  INSERT INTO brand (name, slug, website_url, scraping_enabled)\n  VALUES\n    ('ARRI',  'arri',  'https://www.arri.com',            TRUE),\n    ('Sony',  'sony',  'https://pro.sony/ue_US',          TRUE)\n  ON CONFLICT (slug) DO NOTHING;\nEND $$"}	seed_arri_sony_brands
20260403000001	{"-- Migration: ARRI cinema-camera spec definitions and mapping rules.\n--\n-- Two parts:\n--   1. Widen context_pattern on existing rules whose patterns are correct but\n--      whose context strings are too narrow for ARRI's flat \\"Technical\n--      Specifications\\" section (everything in one section, no sub-headings).\n--      The spec_mapper now also tries raw_key as context fallback, so adding\n--      the label word to the context is sufficient.\n--\n--   2. New spec_definitions (+ mapping rules) for ARRI labels that have no\n--      existing definition at all.\n--\n-- Safe to re-run: all inserts use ON CONFLICT DO NOTHING; updates are idempotent.\n\n-- ─────────────────────────────────────────────────────────────────────────────\n-- PART 1 – Widen context_pattern on existing cinema-cameras mapping rules\n-- ─────────────────────────────────────────────────────────────────────────────\n\n-- cinema_weight  (\\"Weight\\" doesn't contain physical/body/dimensions)\nUPDATE spec_mapping\nSET    context_pattern = '(physical|body|dimensions|weight)'\nWHERE  spec_definition_id = (SELECT id FROM spec_definition WHERE normalized_key = 'cinema_weight')\n  AND  context_pattern = '(physical|body|dimensions)'","-- cinema_dimensions  (\\"Measurements (HxWxL)\\" — add measurements)\nUPDATE spec_mapping\nSET    context_pattern = '(physical|body|dimensions|measurements)'\nWHERE  spec_definition_id = (SELECT id FROM spec_definition WHERE normalized_key = 'cinema_dimensions')\n  AND  context_pattern = '(physical|body|dimensions)'","-- cinema_operating_temp  (\\"Operating Temperature\\" — add operating|temperature)\nUPDATE spec_mapping\nSET    context_pattern = '(physical|environmental|operating|temperature)'\nWHERE  spec_definition_id = (SELECT id FROM spec_definition WHERE normalized_key = 'cinema_operating_temp')\n  AND  context_pattern = '(physical|environmental)'","-- cinema_flange_focal_distance  (\\"Flange Focal Depth\\" — add flange|focal|depth)\nUPDATE spec_mapping\nSET    context_pattern = '(optics|mount|lens|flange|focal|depth)'\nWHERE  spec_definition_id = (SELECT id FROM spec_definition WHERE normalized_key = 'cinema_flange_focal_distance')\n  AND  context_pattern = '(optics|mount|lens)'","-- anamorphic_squeeze_factors  (\\"Lens Squeeze Factors\\" — add lens|squeeze)\nUPDATE spec_mapping\nSET    context_pattern = '(image\\\\s*sensor|sensor|anamorphic|recording|lens|squeeze)'\nWHERE  spec_definition_id = (SELECT id FROM spec_definition WHERE normalized_key = 'anamorphic_squeeze_factors')\n  AND  context_pattern = '(image\\\\\\\\s*sensor|sensor|anamorphic|recording)'","-- cinema_sensor_dimensions  (\\"Photosite Pitch\\" — add photosite)\nUPDATE spec_mapping\nSET    context_pattern = '(image\\\\s*sensor|sensor|photosite)'\nWHERE  spec_definition_id = (SELECT id FROM spec_definition WHERE normalized_key = 'cinema_sensor_dimensions')\n  AND  context_pattern = '(image\\\\\\\\s*sensor|sensor)'","-- ─────────────────────────────────────────────────────────────────────────────\n-- PART 2 – New spec_definitions and mapping rules\n-- ─────────────────────────────────────────────────────────────────────────────\n\nDO $$\nDECLARE\n  cat_id      UUID;\n\n  s_general   UUID;\n  s_sensor    UUID;\n  s_recording UUID;\n  s_optics    UUID;\n  s_color     UUID;\n  s_audio     UUID;\n  s_connect   UUID;\n  s_physical  UUID;\n  s_viewfinder UUID;\nBEGIN\n\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'cinema-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'cinema-cameras category not found';\n  END IF;\n\n  -- Existing sections\n  SELECT id INTO s_general   FROM spec_section WHERE section_name = 'General'        AND category_id = cat_id;\n  SELECT id INTO s_sensor    FROM spec_section WHERE section_name = 'Image Sensor'   AND category_id = cat_id;\n  SELECT id INTO s_recording FROM spec_section WHERE section_name = 'Recording'      AND category_id = cat_id;\n  SELECT id INTO s_optics    FROM spec_section WHERE section_name = 'Optics & Mount' AND category_id = cat_id;\n  SELECT id INTO s_color     FROM spec_section WHERE section_name = 'Color Science'  AND category_id = cat_id;\n  SELECT id INTO s_audio     FROM spec_section WHERE section_name = 'Audio'          AND category_id = cat_id;\n  SELECT id INTO s_connect   FROM spec_section WHERE section_name = 'Connectivity'   AND category_id = cat_id;\n  SELECT id INTO s_physical  FROM spec_section WHERE section_name = 'Physical'       AND category_id = cat_id;\n\n  -- New section: Display & Viewfinder\n  INSERT INTO spec_section (section_name, category_id, display_order)\n  VALUES ('Display & Viewfinder', cat_id, 45)\n  ON CONFLICT (section_name, category_id) DO NOTHING;\n  SELECT id INTO s_viewfinder FROM spec_section WHERE section_name = 'Display & Viewfinder' AND category_id = cat_id;\n\n  -- ── General ──────────────────────────────────────────────────────────────\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_general, 'Software Licenses',       'cinema_software_licenses',  'text', NULL, cat_id, 5),\n    (s_general, 'Exposure & Focus Tools',  'cinema_exposure_tools',     'text', NULL, cat_id, 6)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- ── Image Sensor ─────────────────────────────────────────────────────────\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_sensor, 'Photosite Pitch',    'cinema_photosite_pitch', 'text', 'μm', cat_id, 6),\n    (s_sensor, 'Shutter',            'cinema_shutter',         'text', NULL, cat_id, 7),\n    (s_sensor, 'White Balance',      'cinema_white_balance',   'text', NULL, cat_id, 6)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- ── Recording ────────────────────────────────────────────────────────────\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_recording, 'Recording Frame Rates',     'cinema_recording_frame_rates',  'text', 'fps', cat_id, 8),\n    (s_recording, 'Recording Modes',           'cinema_recording_modes',        'text', NULL,  cat_id, 7),\n    (s_recording, 'Recording Resolutions',     'cinema_recording_resolutions',  'text', NULL,  cat_id, 8),\n    (s_recording, 'Optical Filters',           'cinema_filters',                'text', NULL,  cat_id, 8)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- ── Display & Viewfinder ─────────────────────────────────────────────────\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_viewfinder, 'Viewfinder Technology',       'cinema_viewfinder_type',       'text', NULL, cat_id, 7),\n    (s_viewfinder, 'Viewfinder Resolution',       'cinema_viewfinder_resolution', 'text', NULL, cat_id, 6),\n    (s_viewfinder, 'Viewfinder Diopter Range',    'cinema_viewfinder_diopter',    'text', NULL, cat_id, 5)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- ── Color Science ────────────────────────────────────────────────────────\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_color, 'Look Control',   'cinema_look_control',  'text', NULL, cat_id, 7),\n    (s_color, 'White Balance',  'cinema_white_balance', 'text', NULL, cat_id, 6)  -- already inserted above; ON CONFLICT absorbs\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- ── Audio ─────────────────────────────────────────────────────────────────\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_audio, 'Audio Output', 'cinema_audio_output', 'text', NULL, cat_id, 5)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- ── Connectivity ─────────────────────────────────────────────────────────\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_connect, 'Image Outputs',         'cinema_image_outputs',        'text', NULL, cat_id, 8),\n    (s_connect, 'Physical Interfaces',   'cinema_interfaces',           'text', NULL, cat_id, 7),\n    (s_connect, 'Wireless Interfaces',   'cinema_wireless_interfaces',  'text', NULL, cat_id, 6)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- ── Physical ─────────────────────────────────────────────────────────────\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n    (s_physical, 'Power Outputs',         'cinema_power_outputs',   'text', NULL, cat_id, 6),\n    (s_physical, 'Storage Temperature',   'cinema_storage_temp',    'text', NULL, cat_id, 4),\n    (s_physical, 'Sound Level',           'cinema_sound_level',     'text', 'dB', cat_id, 4)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\nEND $$","-- ─────────────────────────────────────────────────────────────────────────────\n-- Mapping rules for the new definitions\n-- ─────────────────────────────────────────────────────────────────────────────\n\nDO $$\nBEGIN\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT sd.id, v.extraction_pattern, v.context_pattern, v.priority, v.notes\n  FROM (VALUES\n\n    -- General\n    ('cinema_software_licenses',\n      '(software\\\\s*(license|key|option)|license\\\\s*(key|pack)|firmware\\\\s*option)',\n      '(general|license|software)',\n      60, 'Cinema: optional software licenses / feature keys'),\n    ('cinema_exposure_tools',\n      '(exposure\\\\s*(and\\\\s*focus\\\\s*)?tools?|false\\\\s*color|zebra|waveform|peaking|focus\\\\s*assist)',\n      '(general|image|exposure|focus)',\n      60, 'Cinema: on-board exposure and focus assist tools'),\n\n    -- Image Sensor\n    ('cinema_photosite_pitch',\n      '(photosite\\\\s*pitch|pixel\\\\s*pitch|cell\\\\s*pitch)',\n      '(image\\\\s*sensor|sensor|photosite|pitch)',\n      70, 'Cinema: photosite / pixel pitch in μm'),\n    ('cinema_shutter',\n      '(\\\\bshutter\\\\b)',\n      '(image\\\\s*sensor|sensor|shutter|recording)',\n      75, 'Cinema: shutter type and range (degrees / time)'),\n    ('cinema_white_balance',\n      '(white\\\\s*balance|color\\\\s*temperature\\\\s*range|colour\\\\s*temperature)',\n      '(image\\\\s*sensor|sensor|color|colour|white)',\n      70, 'Cinema: white balance range and modes'),\n\n    -- Recording\n    ('cinema_recording_frame_rates',\n      '(recording\\\\s*frame\\\\s*rates?|capture\\\\s*frame\\\\s*rates?)',\n      '(recording|frame\\\\s*rate|capture)',\n      80, 'Cinema: per-format recording frame rate range'),\n    ('cinema_recording_modes',\n      '(recording\\\\s*modes?|capture\\\\s*modes?|pre.?rec(ord)?|intervalometer|stop\\\\s*motion)',\n      '(recording|capture|modes?)',\n      75, 'Cinema: recording mode options (real-time, pre-rec, intervalometer, stop-motion)'),\n    ('cinema_recording_resolutions',\n      '(recording\\\\s*file\\\\s*(image\\\\s*content|container|size)|per.?format\\\\s*resolution)',\n      '(recording|resolution|format)',\n      78, 'Cinema: per-format recording resolution table'),\n    ('cinema_filters',\n      '(\\\\bfilters?\\\\b(?!\\\\s*type))',\n      '(recording|optics|nd|filter|general|filters)',\n      72, 'Cinema: optical filter suite (ND, LP, UV, IR)'),\n\n    -- Display & Viewfinder\n    ('cinema_viewfinder_type',\n      '(viewfinder\\\\s*(technology|type)|evf\\\\s*type|oled\\\\s*viewfinder|lcd\\\\s*(monitor|viewfinder))',\n      '(viewfinder|display|evf|monitor)',\n      70, 'Cinema: viewfinder/monitor technology (OLED, LCD)'),\n    ('cinema_viewfinder_resolution',\n      '(viewfinder\\\\s*resolution|evf\\\\s*resolution)',\n      '(viewfinder|display|evf|resolution)',\n      68, 'Cinema: viewfinder panel resolution in pixels'),\n    ('cinema_viewfinder_diopter',\n      '(diopter|dioptric\\\\s*adjustment)',\n      '(viewfinder|display|evf|diopter)',\n      65, 'Cinema: viewfinder diopter adjustment range'),\n\n    -- Color Science\n    ('cinema_look_control',\n      '(look\\\\s*control|3d\\\\s*lut|asc\\\\s*cdl|look\\\\s*file|alf\\\\b|look\\\\s*management)',\n      '(color|look|lut|workflow)',\n      72, 'Cinema: in-camera look management (3D LUT, ASC CDL, look files)'),\n\n    -- Audio\n    ('cinema_audio_output',\n      '(audio\\\\s*output|headphone\\\\s*(output|jack)|monitor\\\\s*out.*audio|line\\\\s*out)',\n      '(audio|sound|output)',\n      62, 'Cinema: audio monitor/headphone output'),\n\n    -- Connectivity\n    ('cinema_image_outputs',\n      '(image\\\\s*output|video\\\\s*output|mon(itor)?\\\\s*out(?!put\\\\s*channel))',\n      '(connectivity|output|interfaces?|image)',\n      75, 'Cinema: all video/image outputs (SDI, HDMI, proprietary)'),\n    ('cinema_interfaces',\n      '(\\\\binterfaces?\\\\b)',\n      '(connectivity|interfaces?|connectors?)',\n      65, 'Cinema: all physical I/O connectors (catch-all)'),\n    ('cinema_wireless_interfaces',\n      '(wireless\\\\s*interfaces?|wi.?fi.*bluetooth|bluetooth.*wi.?fi)',\n      '(connectivity|wireless|interfaces?)',\n      70, 'Cinema: wireless I/O (Wi-Fi + Bluetooth combined)'),\n\n    -- Physical\n    ('cinema_power_outputs',\n      '(power\\\\s*outputs?|accessory\\\\s*power|12v\\\\s*out|24v\\\\s*out)',\n      '(physical|power|output)',\n      68, 'Cinema: accessory power output connectors'),\n    ('cinema_storage_temp',\n      '(storage\\\\s*temperature|storage\\\\s*temp)',\n      '(physical|environmental|storage|temperature)',\n      50, 'Cinema: storage temperature range'),\n    ('cinema_sound_level',\n      '(sound\\\\s*level|noise\\\\s*level|db\\\\s*\\\\(?a\\\\)?|acoustic\\\\s*noise)',\n      '(physical|environmental|sound|noise)',\n      52, 'Cinema: camera body sound/noise level in dB(A)')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1 FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_arri_cinema_specs
20260403000002	{"-- Migration: Sony cinema-camera spec definitions and mapping rules.\n--\n-- Three parts:\n--   1. Widen context_pattern on existing rules where the extraction pattern\n--      is fine but Sony's single flat \\"Specifications\\" section means the\n--      context fallback (raw_key) doesn't hit the required terms.\n--\n--   2. New mapping rows for existing spec_definitions covering Sony-specific\n--      label wording (e.g. \\"ISO Sensitivity\\", \\"DC Input\\", \\"Imaging Device\\",\n--      \\"HD MONI Output\\", \\"Mass\\", \\"Gamma Curve\\", etc.).\n--\n--   3. New spec_definitions (pixel count, gain, proxy recording) that have\n--      no existing definition and appear in at least one Sony camera.\n--\n-- Safe to re-run: all inserts use ON CONFLICT / WHERE NOT EXISTS guards;\n-- updates include the WHERE clause to match only the current pattern value.\n\n-- ─────────────────────────────────────────────────────────────────────────────\n-- PART 1 – Widen context_pattern on existing cinema-cameras mapping rules\n-- ─────────────────────────────────────────────────────────────────────────────\n\n-- cinema_hdmi  (\\"HDMI Output\\" – context fallback doesn't hit connectivity)\nUPDATE spec_mapping\nSET    context_pattern = '(connectivity|interfaces?|hdmi|output)'\nWHERE  spec_definition_id = (SELECT id FROM spec_definition WHERE normalized_key = 'cinema_hdmi')\n  AND  context_pattern = '(connectivity|interfaces?)'","-- cinema_genlock  (\\"Genlock Input\\", \\"Genlock input/Ref output\\")\nUPDATE spec_mapping\nSET    context_pattern = '(connectivity|sync|interfaces?|genlock|ref)'\nWHERE  spec_definition_id = (SELECT id FROM spec_definition WHERE normalized_key = 'cinema_genlock')\n  AND  context_pattern = '(connectivity|sync|interfaces?)'","-- cinema_timecode_io  (\\"TC/UB\\", \\"TC input/TC output\\")\nUPDATE spec_mapping\nSET    context_pattern = '(connectivity|timecode|interfaces?|tc|ub)'\nWHERE  spec_definition_id = (SELECT id FROM spec_definition WHERE normalized_key = 'cinema_timecode_io')\n  AND  context_pattern = '(connectivity|timecode|interfaces?)'","-- cinema_recording_media  (\\"Memory card slot\\" – label contains 'memory card'\n--   which the extraction pattern already catches, but context fails via fallback)\nUPDATE spec_mapping\nSET    context_pattern = '(recording|media|storage|memory|card)'\nWHERE  spec_definition_id = (SELECT id FROM spec_definition WHERE normalized_key = 'cinema_recording_media')\n  AND  context_pattern = '(recording|media|storage)'","-- ─────────────────────────────────────────────────────────────────────────────\n-- PART 2 – New mapping rows for existing spec_definitions\n-- ─────────────────────────────────────────────────────────────────────────────\n\nDO $$\nBEGIN\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT sd.id, v.extraction_pattern, v.context_pattern, v.priority, v.notes\n  FROM (VALUES\n\n    -- ── Image Sensor ─────────────────────────────────────────────────────────\n\n    -- \\"ISO Sensitivity\\" (context passes via 'iso' in raw_key; pattern misses)\n    ('cinema_base_iso',\n      'iso\\\\s*sensitivity',\n      '(image\\\\s*sensor|sensor|exposure|iso|general)',\n      83, 'Sony: ISO Sensitivity label for base EI/ISO'),\n\n    -- \\"Imaging Device\\" → sensor type (single-chip CMOS imager, etc.)\n    ('cinema_sensor_type',\n      'imaging\\\\s*device\\\\b(?!\\\\s*(size|pixel))',\n      '(image\\\\s*sensor|sensor|imaging|device)',\n      83, 'Sony: Imaging Device label for sensor technology'),\n\n    -- \\"Imaging Device Size\\" → sensor format\n    ('cinema_sensor_size',\n      'imaging\\\\s*device\\\\s*size',\n      '(sensor|imaging|device)',\n      88, 'Sony: Imaging Device Size label for sensor format'),\n\n    -- ── Recording ────────────────────────────────────────────────────────────\n\n    -- \\"Select FPS\\" → per-format frame rate table\n    ('cinema_recording_frame_rates',\n      'select\\\\s*fps|\\\\bfps\\\\s*select',\n      '(recording|fps|frame\\\\s*rate|capture|select)',\n      78, 'Sony: Select FPS per-format frame rate label'),\n\n    -- \\"Video compression\\" → recording codec/format\n    ('cinema_recording_formats',\n      'video\\\\s*compression',\n      '(recording|compression|codec|video|format)',\n      78, 'Sony: Video compression label for recording format'),\n\n    -- \\"Slow & Quick Motion (S&Q)\\" → recording mode\n    ('cinema_recording_modes',\n      'slow\\\\s*(&|and)\\\\s*quick|s\\\\s*&\\\\s*q\\\\s*motion|slow\\\\s*motion\\\\b|quick\\\\s*motion',\n      '(recording|capture|modes?|slow|motion)',\n      73, 'Sony: Slow & Quick Motion (S&Q) recording mode label'),\n\n    -- \\"Proxy recording\\" mapped here as a mode option (new full def added in Part 3)\n    -- (handled via new spec_definition cinema_proxy_recording below)\n\n    -- ── Power ────────────────────────────────────────────────────────────────\n\n    -- \\"DC Input\\", \\"Battery DC Input\\" → power input\n    ('cinema_power_input',\n      'battery\\\\s*dc\\\\s*input|(?<!\\\\w)dc\\\\s*input',\n      '(physical|power|dc|battery|input)',\n      78, 'Sony: DC Input / Battery DC Input power connector labels'),\n\n    -- \\"Battery\\" standalone → power input\n    ('cinema_power_input',\n      '\\\\bbattery\\\\b',\n      '(physical|power|battery)',\n      70, 'Sony/generic: standalone Battery label for power input'),\n\n    -- \\"DC Output\\" → accessory power output\n    -- (context passes via 'output' in raw_key; extraction pattern misses)\n    ('cinema_power_outputs',\n      '\\\\bdc\\\\s*out(put)?\\\\b',\n      '(physical|power|output|dc)',\n      66, 'Sony: DC Output label for accessory power output'),\n\n    -- ── Connectivity ─────────────────────────────────────────────────────────\n\n    -- \\"HD MONI Output\\" → SDI/image monitor output\n    ('cinema_image_outputs',\n      'hd[\\\\s\\\\-]*moni|moni\\\\s*out(put)?',\n      '(connectivity|output|interfaces?|moni|sdi)',\n      73, 'Sony: HD MONI Output label for SDI monitor output'),\n\n    -- \\"Remote\\", \\"Remote terminal\\" → remote control connector\n    -- (context already passes via 'remote' in raw_key; pattern too strict)\n    ('cinema_remote',\n      '\\\\bremote\\\\b',\n      '(connectivity|remote)',\n      53, 'Sony/generic: standalone Remote or Remote terminal label'),\n\n    -- \\"Network\\", \\"LAN terminal\\" → Ethernet\n    ('cinema_ethernet',\n      '\\\\bnetwork\\\\b|\\\\blan\\\\b|\\\\blan\\\\s*terminal\\\\b',\n      '(connectivity|network|interfaces?|lan|ethernet)',\n      63, 'Sony: Network / LAN terminal label for Ethernet port'),\n\n    -- \\"TC/UB\\", \\"TC input/TC output\\" → timecode I/O\n    ('cinema_timecode_io',\n      'tc\\\\s*/\\\\s*ub|tc\\\\s*(input|output)',\n      '(connectivity|timecode|interfaces?|tc|ub)',\n      83, 'Sony: TC/UB and TC input / TC output labels'),\n\n    -- \\"VF\\" → viewfinder connector (physical, not the viewfinder type)\n    ('cinema_interfaces',\n      '\\\\bvf\\\\b',\n      '(connectivity|interfaces?|vf|viewfinder|connector)',\n      40, 'Sony: VF connector label (viewfinder physical pin connector)'),\n\n    -- \\"AUX\\" (BNC timecode output on Venice)\n    ('cinema_interfaces',\n      '\\\\baux\\\\b',\n      '(connectivity|interfaces?|aux)',\n      40, 'Sony: AUX connector label'),\n\n    -- \\"USB\\"\n    ('cinema_interfaces',\n      '\\\\busb\\\\b',\n      '(connectivity|interfaces?|usb)',\n      45, 'Sony: USB host interface label'),\n\n    -- \\"Lens\\" (physical 12-pin lens communication bus connector)\n    ('cinema_interfaces',\n      'lens\\\\s*(connector|bus|port|pin)|\\\\blens\\\\b',\n      '(connectivity|interfaces?|connector|pin)',\n      38, 'Sony: Lens connector physical interface (low priority, avoids lens_mount)'),\n\n    -- ── Audio ─────────────────────────────────────────────────────────────────\n\n    -- \\"Speaker Output\\", \\"Speaker\\"\n    ('cinema_audio_output',\n      '\\\\bspeaker\\\\s*(output|out|terminal)?\\\\b',\n      '(audio|sound|output|speaker)',\n      60, 'Sony: Speaker Output / Speaker labels for audio output'),\n\n    -- \\"Headphone terminal\\"\n    ('cinema_audio_output',\n      'headphone\\\\s*(output|jack|terminal)',\n      '(audio|sound|output|headphone)',\n      62, 'Sony: Headphone terminal label for audio output'),\n\n    -- \\"Microphone\\"\n    ('cinema_audio_input',\n      '\\\\bmicrophone\\\\b|\\\\bmic\\\\b(?!\\\\s*in)',\n      '(audio|sound|microphone|mic)',\n      58, 'Sony: Microphone label for audio input'),\n\n    -- ── Color Science ────────────────────────────────────────────────────────\n\n    -- \\"Gamma Curve\\" → log/color format\n    ('cinema_log_format',\n      'gamma\\\\s*(curve|profile)',\n      '(color|log|gamma|image)',\n      78, 'Sony: Gamma Curve label for log/color format'),\n\n    -- ── Physical ────────────────────────────────────────────────────────────\n\n    -- \\"Mass\\", \\"Mass (without lens...)\\", \\"Body only\\", \\"Body only (oz.)\\"\n    ('cinema_weight',\n      '\\\\bmass\\\\b|body\\\\s*only',\n      '(physical|body|dimensions|weight|mass)',\n      83, 'Sony: Mass / Body only weight labels'),\n\n    -- ── Display & Viewfinder ─────────────────────────────────────────────────\n\n    -- \\"Number of dots (total)\\" → LCD/EVF resolution (Burano LCD dot count)\n    ('cinema_viewfinder_resolution',\n      'number\\\\s*of\\\\s*dots|dot\\\\s*count|(total\\\\s*)?dots\\\\b',\n      '(viewfinder|display|evf|resolution|dots|panel)',\n      66, 'Sony: Number of dots (total) for LCD/EVF resolution'),\n\n    -- \\"Touch panel\\" / \\"With LCD screen\\"\n    ('cinema_viewfinder_type',\n      'touch\\\\s*panel|lcd\\\\s*touch|touch\\\\s*screen|with\\\\s*lcd\\\\s*screen',\n      '(viewfinder|display|evf|touch|panel|lcd)',\n      65, 'Sony: Touch panel / LCD screen label for display type'),\n\n    -- ── Optics / Lens ─────────────────────────────────────────────────────────\n\n    -- \\"Lens compensation\\" → lens correction feature (part of lens metadata support)\n    ('cinema_lens_metadata',\n      'lens\\\\s*compensation',\n      '(optics|mount|lens|compensation)',\n      65, 'Sony: Lens compensation / correction feature'),\n\n    -- ── General / Exposure ───────────────────────────────────────────────────\n\n    -- \\"Recognition target (Movies)\\" → exposure/focus assist tools\n    ('cinema_exposure_tools',\n      'recognition\\\\s*target|subject\\\\s*recognition',\n      '(general|image|exposure|focus|recognition)',\n      58, 'Sony: Recognition target (Movies) AI subject recognition label')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1 FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$","-- ─────────────────────────────────────────────────────────────────────────────\n-- PART 3 – New spec_definitions and mapping rules\n-- ─────────────────────────────────────────────────────────────────────────────\n\nDO $$\nDECLARE\n  cat_id      UUID;\n  s_sensor    UUID;\n  s_recording UUID;\nBEGIN\n\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'cinema-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'cinema-cameras category not found';\n  END IF;\n\n  SELECT id INTO s_sensor    FROM spec_section WHERE section_name = 'Image Sensor' AND category_id = cat_id;\n  SELECT id INTO s_recording FROM spec_section WHERE section_name = 'Recording'    AND category_id = cat_id;\n\n  -- ── Image Sensor ─────────────────────────────────────────────────────────\n\n  -- Total/effective pixel count (Venice \\"50.0 M (Total)\\", Burano effective pixel count)\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance)\n  VALUES (s_sensor, 'Pixel Count', 'cinema_pixel_count', 'text', 'MP', cat_id, 7)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- Gain control (Burano: ISO-based exposure gain for Cinema EI workflow)\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance)\n  VALUES (s_sensor, 'Gain Control', 'cinema_gain', 'text', NULL, cat_id, 7)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\n  -- ── Recording ────────────────────────────────────────────────────────────\n\n  -- Proxy recording capability (Burano: simultaneous proxy record)\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance)\n  VALUES (s_recording, 'Proxy Recording', 'cinema_proxy_recording', 'text', NULL, cat_id, 7)\n  ON CONFLICT (normalized_key) DO NOTHING;\n\nEND $$","-- Mapping rules for the new definitions\nDO $$\nBEGIN\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT sd.id, v.extraction_pattern, v.context_pattern, v.priority, v.notes\n  FROM (VALUES\n\n    -- cinema_pixel_count\n    ('cinema_pixel_count',\n      'imaging\\\\s*device\\\\s*pixel\\\\s*count|number\\\\s*of\\\\s*pixels\\\\s*\\\\(?(effective|total)\\\\)?|total\\\\s*pixels?\\\\b|effective\\\\s*pixels?\\\\b',\n      '(image\\\\s*sensor|sensor|pixels?|imaging|count)',\n      78, 'Cinema: imaging device / effective / total pixel count'),\n\n    -- cinema_gain\n    ('cinema_gain',\n      'gain\\\\s*(control|setting|mode|range)?',\n      '(image\\\\s*sensor|sensor|exposure|gain|iso)',\n      75, 'Cinema: gain control for EI/ISO exposure setting'),\n\n    -- cinema_proxy_recording\n    ('cinema_proxy_recording',\n      'proxy\\\\s*record(ing)?',\n      '(recording|proxy|media|format)',\n      75, 'Cinema: proxy recording mode or capability')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1 FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_sony_cinema_specs
20260408000000	{"-- ─────────────────────────────────────────────────────────────────────────────\n-- Productions schema: companies, productions, packages, RLS\n-- ─────────────────────────────────────────────────────────────────────────────\n\n-- ── Enums ────────────────────────────────────────────────────────────────────\n\nCREATE TYPE company_role AS ENUM ('owner', 'admin', 'member')","CREATE TYPE production_role AS ENUM ('dp', 'coordinator', 'producer')","CREATE TYPE production_status AS ENUM ('draft', 'active', 'wrapped', 'archived')","CREATE TYPE package_item_status AS ENUM ('draft', 'sent', 'quote_received', 'approved', 'confirmed', 'unavailable', 'over_budget')","-- ── Shared updated_at trigger function ───────────────────────────────────────\n\nCREATE OR REPLACE FUNCTION set_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql","-- ── users (extends auth.users) ───────────────────────────────────────────────\n\nCREATE TABLE users (\n  id                     uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,\n  full_name              text,\n  avatar_url             text,\n  experience_level       text CHECK (experience_level IN ('guided', 'standard', 'pro')),\n  default_production_role production_role,\n  created_at             timestamptz NOT NULL DEFAULT now(),\n  updated_at             timestamptz NOT NULL DEFAULT now()\n)","CREATE TRIGGER users_updated_at\n  BEFORE UPDATE ON users\n  FOR EACH ROW EXECUTE FUNCTION set_updated_at()","ALTER TABLE users ENABLE ROW LEVEL SECURITY","-- Users can read and update their own row only\nCREATE POLICY \\"users_select_own\\" ON users FOR SELECT USING (id = auth.uid())","CREATE POLICY \\"users_update_own\\" ON users FOR UPDATE USING (id = auth.uid())","-- Insert is handled by the signup trigger below\nCREATE POLICY \\"users_insert_own\\" ON users FOR INSERT WITH CHECK (id = auth.uid())","-- Auto-create a users row on signup\nCREATE OR REPLACE FUNCTION handle_new_user()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO public.users (id, full_name, avatar_url)\n  VALUES (\n    NEW.id,\n    NEW.raw_user_meta_data->>'full_name',\n    NEW.raw_user_meta_data->>'avatar_url'\n  );\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER","CREATE TRIGGER on_auth_user_created\n  AFTER INSERT ON auth.users\n  FOR EACH ROW EXECUTE FUNCTION handle_new_user()","-- ── companies ────────────────────────────────────────────────────────────────\n\nCREATE TABLE companies (\n  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name           text NOT NULL,\n  slug           text UNIQUE,\n  logo_url       text,\n  billing_email  text,\n  plan           text NOT NULL DEFAULT 'free' CHECK (plan IN ('free', 'pro', 'enterprise')),\n  created_by     uuid NOT NULL REFERENCES users(id),\n  created_at     timestamptz NOT NULL DEFAULT now()\n)","ALTER TABLE companies ENABLE ROW LEVEL SECURITY","-- ── company_members ──────────────────────────────────────────────────────────\n\nCREATE TABLE company_members (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  company_id  uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,\n  user_id     uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  role        company_role NOT NULL,\n  invited_by  uuid REFERENCES users(id),\n  joined_at   timestamptz,\n  UNIQUE (company_id, user_id)\n)","CREATE INDEX ON company_members (company_id)","CREATE INDEX ON company_members (user_id)","ALTER TABLE company_members ENABLE ROW LEVEL SECURITY","-- ── productions ──────────────────────────────────────────────────────────────\n\nCREATE TABLE productions (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  company_id    uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,\n  name          text NOT NULL,\n  shoot_type    text CHECK (shoot_type IN ('narrative', 'commercial', 'documentary', 'music_video')),\n  shoot_days    integer,\n  start_date    date,\n  end_date      date,\n  total_budget  numeric(12,2),\n  status        production_status NOT NULL DEFAULT 'draft',\n  created_by    uuid NOT NULL REFERENCES users(id),\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  updated_at    timestamptz NOT NULL DEFAULT now()\n)","CREATE INDEX ON productions (company_id)","CREATE TRIGGER productions_updated_at\n  BEFORE UPDATE ON productions\n  FOR EACH ROW EXECUTE FUNCTION set_updated_at()","ALTER TABLE productions ENABLE ROW LEVEL SECURITY","-- ── production_members ───────────────────────────────────────────────────────\n\nCREATE TABLE production_members (\n  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  production_id  uuid NOT NULL REFERENCES productions(id) ON DELETE CASCADE,\n  user_id        uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  role           production_role NOT NULL,\n  invited_by     uuid REFERENCES users(id),\n  joined_at      timestamptz,\n  UNIQUE (production_id, user_id)\n)","CREATE INDEX ON production_members (production_id)","CREATE INDEX ON production_members (user_id)","ALTER TABLE production_members ENABLE ROW LEVEL SECURITY","-- ── packages ─────────────────────────────────────────────────────────────────\n\nCREATE TABLE packages (\n  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  production_id  uuid NOT NULL REFERENCES productions(id) ON DELETE CASCADE,\n  name           text NOT NULL,\n  created_by     uuid REFERENCES users(id),\n  created_at     timestamptz NOT NULL DEFAULT now(),\n  updated_at     timestamptz NOT NULL DEFAULT now()\n)","CREATE INDEX ON packages (production_id)","CREATE TRIGGER packages_updated_at\n  BEFORE UPDATE ON packages\n  FOR EACH ROW EXECUTE FUNCTION set_updated_at()","ALTER TABLE packages ENABLE ROW LEVEL SECURITY","-- ── package_items ────────────────────────────────────────────────────────────\n\nCREATE TABLE package_items (\n  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  package_id          uuid NOT NULL REFERENCES packages(id) ON DELETE CASCADE,\n  gear_id             uuid REFERENCES product(id),\n  quantity            integer NOT NULL DEFAULT 1,\n  day_rate_snapshot   numeric(10,2),\n  status              package_item_status NOT NULL DEFAULT 'draft',\n  notes               text,\n  added_by            uuid REFERENCES users(id),\n  approved_by         uuid REFERENCES users(id),\n  approved_at         timestamptz,\n  sort_order          integer,\n  created_at          timestamptz NOT NULL DEFAULT now()\n)","CREATE INDEX ON package_items (package_id)","ALTER TABLE package_items ENABLE ROW LEVEL SECURITY","-- ── invitations ──────────────────────────────────────────────────────────────\n\nCREATE TABLE invitations (\n  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  email            text NOT NULL,\n  company_id       uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,\n  production_id    uuid REFERENCES productions(id) ON DELETE CASCADE,\n  company_role     company_role,\n  production_role  production_role,\n  token            text UNIQUE NOT NULL DEFAULT replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', ''),\n  invited_by       uuid REFERENCES users(id),\n  expires_at       timestamptz NOT NULL DEFAULT (now() + interval '7 days'),\n  accepted_at      timestamptz\n)","CREATE INDEX ON invitations (token)","CREATE INDEX ON invitations (email)","ALTER TABLE invitations ENABLE ROW LEVEL SECURITY","-- ─────────────────────────────────────────────────────────────────────────────\n-- RLS helper functions\n-- ─────────────────────────────────────────────────────────────────────────────\n\nCREATE OR REPLACE FUNCTION get_company_role(p_company_id uuid)\nRETURNS company_role AS $$\n  SELECT role FROM company_members\n  WHERE company_id = p_company_id\n    AND user_id = auth.uid();\n$$ LANGUAGE sql SECURITY DEFINER STABLE","CREATE OR REPLACE FUNCTION get_production_role(p_production_id uuid)\nRETURNS production_role AS $$\n  SELECT role FROM production_members\n  WHERE production_id = p_production_id\n    AND user_id = auth.uid();\n$$ LANGUAGE sql SECURITY DEFINER STABLE","CREATE OR REPLACE FUNCTION is_company_admin_for_production(p_production_id uuid)\nRETURNS boolean AS $$\n  SELECT EXISTS (\n    SELECT 1 FROM productions p\n    JOIN company_members cm ON cm.company_id = p.company_id\n    WHERE p.id = p_production_id\n      AND cm.user_id = auth.uid()\n      AND cm.role IN ('owner', 'admin')\n  );\n$$ LANGUAGE sql SECURITY DEFINER STABLE","-- ─────────────────────────────────────────────────────────────────────────────\n-- RLS policies\n-- ─────────────────────────────────────────────────────────────────────────────\n\n-- companies: members see their own company\nCREATE POLICY \\"companies_select\\" ON companies FOR SELECT\n  USING (get_company_role(id) IS NOT NULL)","-- companies: only owner/admin can update\nCREATE POLICY \\"companies_update\\" ON companies FOR UPDATE\n  USING (get_company_role(id) IN ('owner', 'admin'))","-- companies: any authenticated user can create (they become owner via trigger below)\nCREATE POLICY \\"companies_insert\\" ON companies FOR INSERT\n  WITH CHECK (auth.uid() IS NOT NULL)","-- Auto-assign creator as owner when a company is created\nCREATE OR REPLACE FUNCTION handle_new_company()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO company_members (company_id, user_id, role, joined_at)\n  VALUES (NEW.id, NEW.created_by, 'owner', now());\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER","CREATE TRIGGER on_company_created\n  AFTER INSERT ON companies\n  FOR EACH ROW EXECUTE FUNCTION handle_new_company()","-- company_members: members see own company roster\nCREATE POLICY \\"company_members_select\\" ON company_members FOR SELECT\n  USING (get_company_role(company_id) IS NOT NULL)","-- company_members: owner or admin can insert/update/delete\nCREATE POLICY \\"company_members_insert\\" ON company_members FOR INSERT\n  WITH CHECK (get_company_role(company_id) IN ('owner', 'admin'))","CREATE POLICY \\"company_members_update\\" ON company_members FOR UPDATE\n  USING (get_company_role(company_id) IN ('owner', 'admin'))","CREATE POLICY \\"company_members_delete\\" ON company_members FOR DELETE\n  USING (get_company_role(company_id) IN ('owner', 'admin'))","-- productions: select — production member OR company admin/owner\nCREATE POLICY \\"productions_select\\" ON productions FOR SELECT\n  USING (\n    get_production_role(id) IS NOT NULL\n    OR is_company_admin_for_production(id)\n  )","-- productions: insert — any company member\nCREATE POLICY \\"productions_insert\\" ON productions FOR INSERT\n  WITH CHECK (get_company_role(company_id) IS NOT NULL)","-- Auto-assign creator as producer on new production\nCREATE OR REPLACE FUNCTION handle_new_production()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO production_members (production_id, user_id, role, joined_at)\n  VALUES (NEW.id, NEW.created_by, 'producer', now());\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER","CREATE TRIGGER on_production_created\n  AFTER INSERT ON productions\n  FOR EACH ROW EXECUTE FUNCTION handle_new_production()","-- productions: update — producer on production OR company admin/owner\nCREATE POLICY \\"productions_update\\" ON productions FOR UPDATE\n  USING (\n    get_production_role(id) = 'producer'\n    OR is_company_admin_for_production(id)\n  )","-- productions: delete — company admin/owner only\nCREATE POLICY \\"productions_delete\\" ON productions FOR DELETE\n  USING (is_company_admin_for_production(id))","-- production_members: any production member can see roster\nCREATE POLICY \\"production_members_select\\" ON production_members FOR SELECT\n  USING (\n    get_production_role(production_id) IS NOT NULL\n    OR is_company_admin_for_production(production_id)\n  )","-- production_members: producer or company admin can manage roster\nCREATE POLICY \\"production_members_insert\\" ON production_members FOR INSERT\n  WITH CHECK (\n    get_production_role(production_id) = 'producer'\n    OR is_company_admin_for_production(production_id)\n  )","CREATE POLICY \\"production_members_delete\\" ON production_members FOR DELETE\n  USING (\n    get_production_role(production_id) = 'producer'\n    OR is_company_admin_for_production(production_id)\n  )","-- packages: select — any production member\nCREATE POLICY \\"packages_select\\" ON packages FOR SELECT\n  USING (\n    get_production_role(production_id) IS NOT NULL\n    OR is_company_admin_for_production(production_id)\n  )","-- packages: insert/update — DP only\nCREATE POLICY \\"packages_insert\\" ON packages FOR INSERT\n  WITH CHECK (get_production_role(production_id) = 'dp')","CREATE POLICY \\"packages_update\\" ON packages FOR UPDATE\n  USING (get_production_role(production_id) = 'dp')","-- package_items: select — any production member (via package)\nCREATE POLICY \\"package_items_select\\" ON package_items FOR SELECT\n  USING (\n    EXISTS (\n      SELECT 1 FROM packages pk\n      WHERE pk.id = package_id\n        AND (\n          get_production_role(pk.production_id) IS NOT NULL\n          OR is_company_admin_for_production(pk.production_id)\n        )\n    )\n  )","-- package_items: insert — DP only\nCREATE POLICY \\"package_items_insert\\" ON package_items FOR INSERT\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM packages pk\n      WHERE pk.id = package_id\n        AND get_production_role(pk.production_id) = 'dp'\n    )\n  )","-- package_items: update — DP or coordinator\n-- (enforce column-level split in app layer: updateItemGear() vs updateItemStatus())\nCREATE POLICY \\"package_items_update\\" ON package_items FOR UPDATE\n  USING (\n    EXISTS (\n      SELECT 1 FROM packages pk\n      WHERE pk.id = package_id\n        AND get_production_role(pk.production_id) IN ('dp', 'coordinator')\n    )\n  )","-- package_items: delete — DP only\nCREATE POLICY \\"package_items_delete\\" ON package_items FOR DELETE\n  USING (\n    EXISTS (\n      SELECT 1 FROM packages pk\n      WHERE pk.id = package_id\n        AND get_production_role(pk.production_id) = 'dp'\n    )\n  )","-- invitations: invited_by user or company admin can see\nCREATE POLICY \\"invitations_select\\" ON invitations FOR SELECT\n  USING (\n    invited_by = auth.uid()\n    OR get_company_role(company_id) IN ('owner', 'admin')\n  )","-- invitations: company admin can create\nCREATE POLICY \\"invitations_insert\\" ON invitations FOR INSERT\n  WITH CHECK (get_company_role(company_id) IN ('owner', 'admin'))","-- invitations: company admin can delete (revoke)\nCREATE POLICY \\"invitations_delete\\" ON invitations FOR DELETE\n  USING (get_company_role(company_id) IN ('owner', 'admin'))"}	add_productions_schema
20260408000001	{"-- ─────────────────────────────────────────────────────────────────────────────\n-- Catalog RLS + app-level admin role\n--\n-- Access model:\n--   anon        → SELECT on public catalog tables only (marketing pages)\n--   authenticated → SELECT on all catalog tables (app features)\n--   admin       → full CRUD on all catalog tables (internal team / ops)\n--   service_role / pipeline → bypasses RLS entirely (postgres direct connection)\n-- ─────────────────────────────────────────────────────────────────────────────\n\n-- ── App role on users ─────────────────────────────────────────────────────────\n-- Added here rather than in the productions migration to keep auth concerns\n-- together. 'user' is the default for anyone who signs up.\n\nALTER TABLE users ADD COLUMN IF NOT EXISTS\n  app_role text NOT NULL DEFAULT 'user'\n  CHECK (app_role IN ('admin', 'user'))","-- ── Admin helper ──────────────────────────────────────────────────────────────\n\nCREATE OR REPLACE FUNCTION is_admin()\nRETURNS boolean AS $$\n  SELECT EXISTS (\n    SELECT 1 FROM users\n    WHERE id = auth.uid()\n      AND app_role = 'admin'\n  );\n$$ LANGUAGE sql SECURITY DEFINER STABLE","-- ─────────────────────────────────────────────────────────────────────────────\n-- Public catalog tables\n-- anon + authenticated: SELECT only\n-- admin: full CRUD\n-- Tables: brand, product_category, product, product_spec,\n--         product_spec_matrix, product_image, product_document\n-- ─────────────────────────────────────────────────────────────────────────────\n\n-- ── brand ─────────────────────────────────────────────────────────────────────\n\nALTER TABLE brand ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"brand_read\\" ON brand FOR SELECT\n  TO anon, authenticated USING (true)","CREATE POLICY \\"brand_admin_all\\" ON brand\n  TO authenticated\n  USING (is_admin())\n  WITH CHECK (is_admin())","-- ── product_category ──────────────────────────────────────────────────────────\n\nALTER TABLE product_category ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"product_category_read\\" ON product_category FOR SELECT\n  TO anon, authenticated USING (true)","CREATE POLICY \\"product_category_admin_all\\" ON product_category\n  TO authenticated\n  USING (is_admin())\n  WITH CHECK (is_admin())","-- ── product ───────────────────────────────────────────────────────────────────\n\nALTER TABLE product ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"product_read\\" ON product FOR SELECT\n  TO anon, authenticated USING (true)","CREATE POLICY \\"product_admin_all\\" ON product\n  TO authenticated\n  USING (is_admin())\n  WITH CHECK (is_admin())","-- ── product_spec ──────────────────────────────────────────────────────────────\n\nALTER TABLE product_spec ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"product_spec_read\\" ON product_spec FOR SELECT\n  TO anon, authenticated USING (true)","CREATE POLICY \\"product_spec_admin_all\\" ON product_spec\n  TO authenticated\n  USING (is_admin())\n  WITH CHECK (is_admin())","-- ── product_spec_matrix ───────────────────────────────────────────────────────\n\nALTER TABLE product_spec_matrix ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"product_spec_matrix_read\\" ON product_spec_matrix FOR SELECT\n  TO anon, authenticated USING (true)","CREATE POLICY \\"product_spec_matrix_admin_all\\" ON product_spec_matrix\n  TO authenticated\n  USING (is_admin())\n  WITH CHECK (is_admin())","-- ── product_image ─────────────────────────────────────────────────────────────\n\nALTER TABLE product_image ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"product_image_read\\" ON product_image FOR SELECT\n  TO anon, authenticated USING (true)","CREATE POLICY \\"product_image_admin_all\\" ON product_image\n  TO authenticated\n  USING (is_admin())\n  WITH CHECK (is_admin())","-- ── product_document ──────────────────────────────────────────────────────────\n\nALTER TABLE product_document ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"product_document_read\\" ON product_document FOR SELECT\n  TO anon, authenticated USING (true)","CREATE POLICY \\"product_document_admin_all\\" ON product_document\n  TO authenticated\n  USING (is_admin())\n  WITH CHECK (is_admin())","-- ─────────────────────────────────────────────────────────────────────────────\n-- Internal pipeline tables\n-- anon: no access\n-- authenticated: SELECT only\n-- admin: full CRUD\n-- Tables: spec_section, spec_definition, spec_mapping\n-- ─────────────────────────────────────────────────────────────────────────────\n\n-- ── spec_section ──────────────────────────────────────────────────────────────\n\nALTER TABLE spec_section ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"spec_section_read\\" ON spec_section FOR SELECT\n  TO authenticated USING (true)","CREATE POLICY \\"spec_section_admin_all\\" ON spec_section\n  TO authenticated\n  USING (is_admin())\n  WITH CHECK (is_admin())","-- ── spec_definition ───────────────────────────────────────────────────────────\n\nALTER TABLE spec_definition ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"spec_definition_read\\" ON spec_definition FOR SELECT\n  TO authenticated USING (true)","CREATE POLICY \\"spec_definition_admin_all\\" ON spec_definition\n  TO authenticated\n  USING (is_admin())\n  WITH CHECK (is_admin())","-- ── spec_mapping ──────────────────────────────────────────────────────────────\n\nALTER TABLE spec_mapping ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"spec_mapping_read\\" ON spec_mapping FOR SELECT\n  TO authenticated USING (true)","CREATE POLICY \\"spec_mapping_admin_all\\" ON spec_mapping\n  TO authenticated\n  USING (is_admin())\n  WITH CHECK (is_admin())"}	catalog_rls
20260408000002	{"-- ─────────────────────────────────────────────────────────────────────────────\n-- Kit builder & compatibility checker tables\n-- Adds: compatibility_axis, product_compatibility_value, product_relationship,\n--       kit_template, kit_template_item, rental_house, rental_house_location,\n--       rental_house_inventory, package_item_quote\n-- Also: packages.source_kit_template_id backref + RLS on all new tables\n-- ─────────────────────────────────────────────────────────────────────────────\n\n-- ── Enums ────────────────────────────────────────────────────────────────────\n\nCREATE TYPE product_relationship_type AS ENUM (\n  'requires',\n  'recommends',\n  'replaces',\n  'incompatible_with',\n  'optional_upgrade'\n)","CREATE TYPE rental_house_type AS ENUM (\n  'full_service',\n  'specialty',\n  'peer_to_peer',\n  'manufacturer'\n)","-- ── compatibility_axis ────────────────────────────────────────────────────────\n-- The 7 axes to seed: lens_mount, sensor_format, rod_system,\n-- power_standard, recording_media, signal_output, gear_pitch\n\nCREATE TABLE compatibility_axis (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name          text NOT NULL,\n  slug          text NOT NULL UNIQUE,\n  description   text,\n  value_type    text NOT NULL DEFAULT 'enum'\n                CHECK (value_type IN ('enum', 'range', 'boolean')),\n  display_order integer DEFAULT 0,\n  created_at    timestamptz NOT NULL DEFAULT now()\n)","ALTER TABLE compatibility_axis ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"compatibility_axis_read\\" ON compatibility_axis FOR SELECT\n  TO anon, authenticated USING (true)","CREATE POLICY \\"compatibility_axis_admin_all\\" ON compatibility_axis\n  TO authenticated USING (is_admin()) WITH CHECK (is_admin())","-- ── product_compatibility_value ───────────────────────────────────────────────\n-- is_input = true  → product accepts this value (e.g. camera body accepts PL)\n-- is_input = false → product provides this value (e.g. lens has PL mount)\n-- A product can have multiple rows per axis (e.g. ALEXA 35: LPL + PL both accepted)\n\nCREATE TABLE product_compatibility_value (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  product_id  uuid NOT NULL REFERENCES product(id) ON DELETE CASCADE,\n  axis_id     uuid NOT NULL REFERENCES compatibility_axis(id) ON DELETE CASCADE,\n  value       text NOT NULL,\n  is_input    boolean DEFAULT true,\n  notes       text,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (product_id, axis_id, value)\n)","CREATE INDEX ON product_compatibility_value (product_id)","CREATE INDEX ON product_compatibility_value (axis_id)","ALTER TABLE product_compatibility_value ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"product_compatibility_value_read\\" ON product_compatibility_value FOR SELECT\n  TO anon, authenticated USING (true)","CREATE POLICY \\"product_compatibility_value_admin_all\\" ON product_compatibility_value\n  TO authenticated USING (is_admin()) WITH CHECK (is_admin())","-- ── product_relationship ──────────────────────────────────────────────────────\n-- Powers \\"you'll also need...\\" and \\"incompatible with\\" prompts in the kit builder.\n-- is_conditional = true means the relationship only applies in certain configurations\n-- (e.g. ALEXA 35 requires PL→LPL adapter only if using PL lenses, not LPL-native glass)\n\nCREATE TABLE product_relationship (\n  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  source_product_id   uuid NOT NULL REFERENCES product(id) ON DELETE CASCADE,\n  target_product_id   uuid NOT NULL REFERENCES product(id) ON DELETE CASCADE,\n  relationship_type   product_relationship_type NOT NULL,\n  is_conditional      boolean DEFAULT false,\n  condition_note      text,\n  notes               text,\n  created_at          timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (source_product_id, target_product_id, relationship_type)\n)","CREATE INDEX ON product_relationship (source_product_id)","CREATE INDEX ON product_relationship (target_product_id)","ALTER TABLE product_relationship ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"product_relationship_read\\" ON product_relationship FOR SELECT\n  TO anon, authenticated USING (true)","CREATE POLICY \\"product_relationship_admin_all\\" ON product_relationship\n  TO authenticated USING (is_admin()) WITH CHECK (is_admin())","-- ── kit_template ──────────────────────────────────────────────────────────────\n-- Pre-built package starting points, anchored to a hero product (camera body).\n-- is_public = true → visible to all authenticated users (curated by Altoscope team)\n-- is_public = false → private to the user who created it\n\nCREATE TABLE kit_template (\n  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name               text NOT NULL,\n  anchor_product_id  uuid REFERENCES product(id),\n  shoot_type         text CHECK (shoot_type IN ('narrative', 'commercial', 'documentary', 'music_video', 'episodic')),\n  description        text,\n  is_public          boolean DEFAULT false,\n  created_by         uuid REFERENCES users(id),\n  created_at         timestamptz NOT NULL DEFAULT now(),\n  updated_at         timestamptz NOT NULL DEFAULT now()\n)","CREATE INDEX ON kit_template (anchor_product_id)","CREATE TRIGGER kit_template_updated_at\n  BEFORE UPDATE ON kit_template\n  FOR EACH ROW EXECUTE FUNCTION set_updated_at()","ALTER TABLE kit_template ENABLE ROW LEVEL SECURITY","-- Public templates visible to all authenticated users; private visible to creator only\nCREATE POLICY \\"kit_template_select\\" ON kit_template FOR SELECT\n  TO authenticated\n  USING (is_public = true OR created_by = auth.uid() OR is_admin())","CREATE POLICY \\"kit_template_insert\\" ON kit_template FOR INSERT\n  TO authenticated WITH CHECK (created_by = auth.uid() OR is_admin())","CREATE POLICY \\"kit_template_update\\" ON kit_template FOR UPDATE\n  TO authenticated USING (created_by = auth.uid() OR is_admin())","CREATE POLICY \\"kit_template_delete\\" ON kit_template FOR DELETE\n  TO authenticated USING (created_by = auth.uid() OR is_admin())","-- ── kit_template_item ─────────────────────────────────────────────────────────\n\nCREATE TABLE kit_template_item (\n  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  kit_template_id  uuid NOT NULL REFERENCES kit_template(id) ON DELETE CASCADE,\n  product_id       uuid NOT NULL REFERENCES product(id),\n  quantity         integer NOT NULL DEFAULT 1,\n  is_required      boolean DEFAULT true,\n  sort_order       integer DEFAULT 0,\n  notes            text\n)","CREATE INDEX ON kit_template_item (kit_template_id)","ALTER TABLE kit_template_item ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"kit_template_item_select\\" ON kit_template_item FOR SELECT\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM kit_template kt\n      WHERE kt.id = kit_template_id\n        AND (kt.is_public = true OR kt.created_by = auth.uid() OR is_admin())\n    )\n  )","CREATE POLICY \\"kit_template_item_write\\" ON kit_template_item\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM kit_template kt\n      WHERE kt.id = kit_template_id\n        AND (kt.created_by = auth.uid() OR is_admin())\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM kit_template kt\n      WHERE kt.id = kit_template_id\n        AND (kt.created_by = auth.uid() OR is_admin())\n    )\n  )","-- ── packages: add source_kit_template_id ─────────────────────────────────────\n\nALTER TABLE packages\n  ADD COLUMN source_kit_template_id uuid REFERENCES kit_template(id)","-- ── rental_house ──────────────────────────────────────────────────────────────\n-- Distinct from brand (manufacturer). Some appear in both (Panavision, ARRI Rental).\n\nCREATE TABLE rental_house (\n  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name              text NOT NULL,\n  slug              text NOT NULL UNIQUE,\n  website_url       text,\n  logo_url          text,\n  type              rental_house_type NOT NULL DEFAULT 'full_service',\n  description       text,\n  brand_id          uuid REFERENCES brand(id),\n  is_active         boolean DEFAULT true,\n  scraping_enabled  boolean DEFAULT true,\n  created_at        timestamptz NOT NULL DEFAULT now(),\n  updated_at        timestamptz NOT NULL DEFAULT now()\n)","CREATE TRIGGER rental_house_updated_at\n  BEFORE UPDATE ON rental_house\n  FOR EACH ROW EXECUTE FUNCTION set_updated_at()","ALTER TABLE rental_house ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"rental_house_read\\" ON rental_house FOR SELECT\n  TO anon, authenticated USING (true)","CREATE POLICY \\"rental_house_admin_all\\" ON rental_house\n  TO authenticated USING (is_admin()) WITH CHECK (is_admin())","-- ── rental_house_location ─────────────────────────────────────────────────────\n-- Inventory and rates can vary by city (e.g. Keslow LA vs Keslow NY).\n\nCREATE TABLE rental_house_location (\n  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  rental_house_id   uuid NOT NULL REFERENCES rental_house(id) ON DELETE CASCADE,\n  city              text NOT NULL,\n  state_or_region   text,\n  country           text NOT NULL DEFAULT 'US',\n  address_line_1    text,\n  phone             text,\n  email             text,\n  is_primary        boolean DEFAULT false,\n  created_at        timestamptz NOT NULL DEFAULT now()\n)","CREATE INDEX ON rental_house_location (rental_house_id)","ALTER TABLE rental_house_location ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"rental_house_location_read\\" ON rental_house_location FOR SELECT\n  TO anon, authenticated USING (true)","CREATE POLICY \\"rental_house_location_admin_all\\" ON rental_house_location\n  TO authenticated USING (is_admin()) WITH CHECK (is_admin())","-- ── rental_house_inventory ────────────────────────────────────────────────────\n-- Reference rates scraped from rental house websites. Actual quoted rates\n-- live on package_item_quote. null location_id = available at all locations.\n\nCREATE TABLE rental_house_inventory (\n  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  rental_house_id            uuid NOT NULL REFERENCES rental_house(id) ON DELETE CASCADE,\n  product_id                 uuid NOT NULL REFERENCES product(id) ON DELETE CASCADE,\n  location_id                uuid REFERENCES rental_house_location(id),\n  day_rate                   numeric(10,2),\n  week_rate                  numeric(10,2),\n  rental_house_product_code  text,\n  rental_house_product_url   text,\n  quantity_on_hand           integer,\n  is_available               boolean DEFAULT true,\n  last_scraped_at            timestamptz,\n  created_at                 timestamptz NOT NULL DEFAULT now(),\n  updated_at                 timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (rental_house_id, product_id, location_id)\n)","CREATE INDEX ON rental_house_inventory (rental_house_id)","CREATE INDEX ON rental_house_inventory (product_id)","CREATE TRIGGER rental_house_inventory_updated_at\n  BEFORE UPDATE ON rental_house_inventory\n  FOR EACH ROW EXECUTE FUNCTION set_updated_at()","ALTER TABLE rental_house_inventory ENABLE ROW LEVEL SECURITY","-- Rate data is sensitive — only authenticated users can see pricing\nCREATE POLICY \\"rental_house_inventory_read\\" ON rental_house_inventory FOR SELECT\n  TO authenticated USING (true)","CREATE POLICY \\"rental_house_inventory_admin_all\\" ON rental_house_inventory\n  TO authenticated USING (is_admin()) WITH CHECK (is_admin())","-- ── package_item_quote ────────────────────────────────────────────────────────\n-- One quote per rental house per package item. Workflow:\n--   sent → quote_received (is_available + day_rate populated)\n--   → user selects best (is_selected = true)\n--   → day_rate_snapshot on package_items updated to match\n--   → approved → confirmed\n\nCREATE TABLE package_item_quote (\n  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  package_item_id      uuid NOT NULL REFERENCES package_items(id) ON DELETE CASCADE,\n  rental_house_id      uuid NOT NULL REFERENCES rental_house(id),\n  location_id          uuid REFERENCES rental_house_location(id),\n  day_rate             numeric(10,2),\n  week_rate            numeric(10,2),\n  is_available         boolean,        -- null = awaiting reply\n  is_selected          boolean DEFAULT false,\n  rental_house_notes   text,\n  quoted_at            timestamptz,\n  created_at           timestamptz NOT NULL DEFAULT now(),\n  updated_at           timestamptz NOT NULL DEFAULT now()\n)","CREATE INDEX ON package_item_quote (package_item_id)","CREATE INDEX ON package_item_quote (rental_house_id)","CREATE TRIGGER package_item_quote_updated_at\n  BEFORE UPDATE ON package_item_quote\n  FOR EACH ROW EXECUTE FUNCTION set_updated_at()","ALTER TABLE package_item_quote ENABLE ROW LEVEL SECURITY","-- Quotes visible to production members (via package → package_item chain)\nCREATE POLICY \\"package_item_quote_select\\" ON package_item_quote FOR SELECT\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM package_items pi\n      JOIN packages pk ON pk.id = pi.package_id\n      WHERE pi.id = package_item_id\n        AND (\n          get_production_role(pk.production_id) IS NOT NULL\n          OR is_company_admin_for_production(pk.production_id)\n          OR is_admin()\n        )\n    )\n  )","-- Coordinators (and admins) can create/update quotes\nCREATE POLICY \\"package_item_quote_write\\" ON package_item_quote\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM package_items pi\n      JOIN packages pk ON pk.id = pi.package_id\n      WHERE pi.id = package_item_id\n        AND (\n          get_production_role(pk.production_id) = 'coordinator'\n          OR is_company_admin_for_production(pk.production_id)\n          OR is_admin()\n        )\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM package_items pi\n      JOIN packages pk ON pk.id = pi.package_id\n      WHERE pi.id = package_item_id\n        AND (\n          get_production_role(pk.production_id) = 'coordinator'\n          OR is_company_admin_for_production(pk.production_id)\n          OR is_admin()\n        )\n    )\n  )","-- ── Seed: 7 core compatibility axes ──────────────────────────────────────────\n\nINSERT INTO compatibility_axis (name, slug, description, value_type, display_order) VALUES\n  ('Lens Mount',              'lens_mount',      'Mount standard on camera body or lens — gates all lens↔body pairings', 'enum', 1),\n  ('Sensor Format',           'sensor_format',   'Sensor size / image circle coverage required or provided',             'enum', 2),\n  ('Rod System',              'rod_system',      'Rod standard for baseplate, mattebox, and follow focus attachment',    'enum', 3),\n  ('Power Standard',          'power_standard',  'Battery mount or power connector type',                               'enum', 4),\n  ('Recording Media',         'recording_media', 'Proprietary or standard media card/SSD format',                       'enum', 5),\n  ('Signal Output',           'signal_output',   'Video output standard for monitors and recorders',                    'enum', 6),\n  ('Gear Pitch (FIZ)',        'gear_pitch',       'Follow focus motor gear pitch — must match lens iris/focus gears',    'enum', 7)"}	kit_builder_compatibility
20260408000003	{"-- ─────────────────────────────────────────────────────────────────────────────\n-- Section 6f: Full product category hierarchy for the 80/20 kit builder\n-- Adds granular lens subcategories and the full Accessories tree.\n-- All inserts are ON CONFLICT DO NOTHING — safe to re-run.\n-- ─────────────────────────────────────────────────────────────────────────────\n\nDO $$\nDECLARE\n  cameras_id       UUID;\n  lenses_id        UUID;\n  cinema_lens_id   UUID;\n  accessories_id   UUID;\n  monitors_id      UUID;\n  support_id       UUID;\n  power_id         UUID;\nBEGIN\n\n  -- ── Resolve existing parents ─────────────────────────────────────────────\n\n  SELECT id INTO cameras_id     FROM product_category WHERE slug = 'cameras';\n  SELECT id INTO lenses_id      FROM product_category WHERE slug = 'lenses';\n  SELECT id INTO cinema_lens_id FROM product_category WHERE slug = 'cinema-lenses';\n\n  IF cameras_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: cameras category not found. Run prior seeds first.';\n  END IF;\n  IF lenses_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: lenses category not found. Run 20251228014500 first.';\n  END IF;\n  IF cinema_lens_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: cinema-lenses category not found.';\n  END IF;\n\n  -- ── Lens subcategories (under cinema-lenses) ──────────────────────────────\n  -- Granular splits needed for spec definitions and compatibility axis seeding.\n\n  INSERT INTO product_category (name, slug, parent_category_id, display_order, icon_name) VALUES\n    ('Cinema Prime Sets (PL)',  'cinema-prime-sets-pl',   cinema_lens_id, 10, 'circle'),\n    ('Cinema Prime Sets (LPL)', 'cinema-prime-sets-lpl',  cinema_lens_id, 20, 'circle'),\n    ('Cinema Zoom Lenses',      'cinema-zoom-lenses',     cinema_lens_id, 30, 'zoom-in'),\n    ('Anamorphic Lenses',       'anamorphic-lenses',      cinema_lens_id, 40, 'maximize'),\n    ('Lens Adapters & Mounts',  'cinema-lens-adapters',   cinema_lens_id, 50, 'link')\n  ON CONFLICT (slug) DO NOTHING;\n\n  -- ── Accessories (new top-level) ───────────────────────────────────────────\n\n  INSERT INTO product_category (name, slug, display_order, icon_name)\n  VALUES ('Accessories', 'accessories', 30, 'package')\n  ON CONFLICT (slug) DO NOTHING;\n\n  SELECT id INTO accessories_id FROM product_category WHERE slug = 'accessories';\n\n  -- Monitors & Displays\n  INSERT INTO product_category (name, slug, parent_category_id, display_order, icon_name)\n  VALUES ('Monitors & Displays', 'monitors-displays', accessories_id, 10, 'monitor')\n  ON CONFLICT (slug) DO NOTHING;\n\n  SELECT id INTO monitors_id FROM product_category WHERE slug = 'monitors-displays';\n\n  INSERT INTO product_category (name, slug, parent_category_id, display_order) VALUES\n    ('On-Board Monitors',   'on-board-monitors',   monitors_id, 10),\n    ('Director''s Monitors','directors-monitors',  monitors_id, 20)\n  ON CONFLICT (slug) DO NOTHING;\n\n  -- Wireless Video\n  INSERT INTO product_category (name, slug, parent_category_id, display_order, icon_name)\n  VALUES ('Wireless Video', 'wireless-video', accessories_id, 20, 'wifi')\n  ON CONFLICT (slug) DO NOTHING;\n\n  -- Follow Focus & FIZ\n  INSERT INTO product_category (name, slug, parent_category_id, display_order, icon_name)\n  VALUES ('Follow Focus & FIZ', 'follow-focus-fiz', accessories_id, 30, 'settings')\n  ON CONFLICT (slug) DO NOTHING;\n\n  -- Matte Boxes\n  INSERT INTO product_category (name, slug, parent_category_id, display_order, icon_name)\n  VALUES ('Matte Boxes', 'matte-boxes', accessories_id, 40, 'square')\n  ON CONFLICT (slug) DO NOTHING;\n\n  -- Camera Support\n  INSERT INTO product_category (name, slug, parent_category_id, display_order, icon_name)\n  VALUES ('Camera Support', 'camera-support', accessories_id, 50, 'sliders')\n  ON CONFLICT (slug) DO NOTHING;\n\n  SELECT id INTO support_id FROM product_category WHERE slug = 'camera-support';\n\n  INSERT INTO product_category (name, slug, parent_category_id, display_order) VALUES\n    ('Fluid Heads',         'fluid-heads',       support_id, 10),\n    ('Tripods & Legs',      'tripods-legs',       support_id, 20),\n    ('Baseplates & Rails',  'baseplates-rails',   support_id, 30)\n  ON CONFLICT (slug) DO NOTHING;\n\n  -- Power & Batteries\n  INSERT INTO product_category (name, slug, parent_category_id, display_order, icon_name)\n  VALUES ('Power & Batteries', 'power-batteries', accessories_id, 60, 'battery')\n  ON CONFLICT (slug) DO NOTHING;\n\n  SELECT id INTO power_id FROM product_category WHERE slug = 'power-batteries';\n\n  INSERT INTO product_category (name, slug, parent_category_id, display_order) VALUES\n    ('Camera Batteries (Gold Mount)', 'batteries-gold-mount', power_id, 10),\n    ('Camera Batteries (V-Mount)',    'batteries-v-mount',    power_id, 20),\n    ('Battery Adapters & Plates',     'battery-adapters',     power_id, 30)\n  ON CONFLICT (slug) DO NOTHING;\n\n  -- Recording Media\n  INSERT INTO product_category (name, slug, parent_category_id, display_order, icon_name)\n  VALUES ('Recording Media', 'recording-media', accessories_id, 70, 'hard-drive')\n  ON CONFLICT (slug) DO NOTHING;\n\n  -- Camera Cages & Rigging\n  INSERT INTO product_category (name, slug, parent_category_id, display_order, icon_name)\n  VALUES ('Camera Cages & Rigging', 'camera-cages-rigging', accessories_id, 80, 'grid')\n  ON CONFLICT (slug) DO NOTHING;\n\nEND $$"}	seed_categories_80_20
20260408000004	{"-- ─────────────────────────────────────────────────────────────────────────────\n-- Sections 2 & 3: Seed all brands for the 80/20 cinema equipment reference.\n-- Covers camera, lens, accessory, and rental house manufacturers.\n-- ON CONFLICT DO NOTHING — safe to re-run.\n-- ─────────────────────────────────────────────────────────────────────────────\n\nINSERT INTO brand (name, slug, website_url, scraping_enabled) VALUES\n\n  -- ── Camera brands ──────────────────────────────────────────────────────────\n  -- ARRI and Sony already seeded — guarded by ON CONFLICT\n  ('ARRI',              'arri',       'https://www.arri.com',                  true),\n  ('Sony',              'sony',       'https://pro.sony/ue_US',                true),\n  ('Canon',             'canon',      'https://www.usa.canon.com',             true),\n  ('RED (Nikon)',        'red',        'https://www.red.com',                   true),\n  ('Blackmagic Design', 'blackmagic', 'https://www.blackmagicdesign.com',      true),\n\n  -- ── Cinema lens brands ─────────────────────────────────────────────────────\n  ('Cooke Optics',      'cooke',      'https://www.cookeoptics.com',           true),\n  ('Carl Zeiss AG',     'zeiss',      'https://www.zeiss.com/consumer-products/us/cinematography', true),\n  ('Angenieux',         'angenieux',  'https://www.angenieux.com',             true),\n  ('Sigma',             'sigma',      'https://www.sigmaphoto.com',            true),\n  ('Leica / Leitz Cine','leica-cine', 'https://www.leica-camera.com/en-US/leica-cine', true),\n\n  -- ── Monitor brands ─────────────────────────────────────────────────────────\n  ('SmallHD',           'smallhd',    'https://smallhd.com',                   true),\n  ('Atomos',            'atomos',     'https://www.atomos.com',                true),\n\n  -- ── Wireless video ─────────────────────────────────────────────────────────\n  ('Teradek',           'teradek',    'https://teradek.com',                   true),\n\n  -- ── Follow focus / FIZ ─────────────────────────────────────────────────────\n  ('Preston Cinema',    'preston',    'https://www.prestoncinema.com',         false),\n  ('Tilta',             'tilta',      'https://tilta.com',                     true),\n  ('cmotion',           'cmotion',    'https://www.cmotion.eu/en',             false),\n\n  -- ── Matte boxes & rigging ──────────────────────────────────────────────────\n  ('Bright Tangerine',  'bright-tangerine', 'https://brighttangerine.com',     true),\n  ('Wooden Camera',     'wooden-camera',    'https://woodencamera.com',        true),\n\n  -- ── Power & batteries ──────────────────────────────────────────────────────\n  ('Anton Bauer',       'anton-bauer','https://www.antonbauer.com',            false),\n  ('Core SWX',          'core-swx',   'https://www.coreswx.com',              false),\n  ('IDX',               'idx',        'https://www.idx.co.jp',                false),\n\n  -- ── Camera support ─────────────────────────────────────────────────────────\n  ('OConnor',           'oconnor',    'https://www.ocon.com',                  false),\n  ('Sachtler',          'sachtler',   'https://www.sachtler.com',              false)\n\nON CONFLICT DO NOTHING"}	seed_brands_80_20
20260408000005	{"-- ─────────────────────────────────────────────────────────────────────────────\n-- Section 6g: Cinema lens spec definitions + mapping rules\n-- Targets the cinema-lenses category (and subcategories share the same sections).\n-- Keys prefixed 'cine_lens_' where they would collide with photo lens keys.\n-- ON CONFLICT DO NOTHING — safe to re-run.\n-- ─────────────────────────────────────────────────────────────────────────────\n\nDO $$\nDECLARE\n  cat_id      UUID;\n  s_identity  UUID;\n  s_optical   UUID;\n  s_physical  UUID;\n  s_metadata  UUID;\nBEGIN\n\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'cinema-lenses';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: cinema-lenses category not found.';\n  END IF;\n\n  -- ── Spec sections ──────────────────────────────────────────────────────────\n\n  INSERT INTO spec_section (section_name, category_id, display_order) VALUES\n    ('Lens Identity',    cat_id, 10),\n    ('Optical',          cat_id, 20),\n    ('Physical',         cat_id, 30),\n    ('Metadata & Electronics', cat_id, 40)\n  ON CONFLICT (section_name, category_id) DO NOTHING;\n\n  SELECT id INTO s_identity FROM spec_section WHERE section_name = 'Lens Identity'           AND category_id = cat_id;\n  SELECT id INTO s_optical  FROM spec_section WHERE section_name = 'Optical'                 AND category_id = cat_id;\n  SELECT id INTO s_physical FROM spec_section WHERE section_name = 'Physical'                AND category_id = cat_id;\n  SELECT id INTO s_metadata FROM spec_section WHERE section_name = 'Metadata & Electronics' AND category_id = cat_id;\n\n  -- ── Spec definitions ───────────────────────────────────────────────────────\n\n  INSERT INTO spec_definition (section_id, display_name, normalized_key, data_type, unit, category_id, importance) VALUES\n\n    -- Identity (importance 9-10: drives compatibility checker)\n    (s_identity, 'Lens Mount',         'cine_lens_mount',       'text',    NULL,    cat_id, 10),\n    (s_identity, 'Image Circle',        'image_circle_mm',       'numeric', 'mm',    cat_id, 10),\n    (s_identity, 'Focal Length',        'cine_focal_length_mm',  'numeric', 'mm',    cat_id, 9),\n    (s_identity, 'T-Stop',             'cine_t_stop',           'numeric', 'T',     cat_id, 9),\n    (s_identity, 'Sensor Coverage',    'cine_sensor_coverage',  'text',    NULL,    cat_id, 9),\n    (s_identity, 'Lens Set',           'lens_set_id',           'text',    NULL,    cat_id, 8),\n\n    -- Optical\n    (s_optical,  'Close Focus Distance','cine_close_focus_m',   'numeric', 'm',     cat_id, 6),\n    (s_optical,  'Front Diameter',      'cine_front_diameter_mm','numeric','mm',    cat_id, 7),\n    (s_optical,  'Iris Gear Pitch',     'cine_gear_pitch',       'text',   'mod',   cat_id, 7),\n    (s_optical,  'Focus Gear Pitch',    'cine_focus_gear_pitch', 'text',   'mod',   cat_id, 6),\n    (s_optical,  'Zoom Ratio',          'cine_zoom_ratio',       'text',   NULL,    cat_id, 7),\n    (s_optical,  'Anamorphic Factor',   'cine_anamorphic_factor','text',   NULL,    cat_id, 8),\n\n    -- Physical\n    (s_physical, 'Weight',             'cine_lens_weight_kg',   'numeric', 'kg',    cat_id, 6),\n    (s_physical, 'Length',             'cine_lens_length_mm',   'numeric', 'mm',    cat_id, 5),\n\n    -- Metadata & electronics\n    (s_metadata, '/i Technology',      'has_i_technology',      'boolean', NULL,    cat_id, 6),\n    (s_metadata, 'eXtended Data (LDS)','has_lds_metadata',      'boolean', NULL,    cat_id, 6),\n    (s_metadata, 'Electronic Iris',    'has_electronic_iris',   'boolean', NULL,    cat_id, 5)\n\n  ON CONFLICT (normalized_key) DO NOTHING;\n\nEND $$","-- ─────────────────────────────────────────────────────────────────────────────\n-- Spec mapping rules for cinema lens labels\n-- ─────────────────────────────────────────────────────────────────────────────\n\nDO $$\nBEGIN\n  INSERT INTO spec_mapping (spec_definition_id, extraction_pattern, context_pattern, priority, notes)\n  SELECT sd.id, v.extraction_pattern, v.context_pattern, v.priority, v.notes\n  FROM (VALUES\n\n    ('cine_lens_mount',\n      '(lens\\\\\\\\s*mount|mount\\\\\\\\s*type|pl\\\\\\\\s*mount|lpl\\\\\\\\s*mount|ef\\\\\\\\s*mount|e.mount)',\n      '(mount|lens|compatibility)',\n      95, 'Cinema lens: mount type (PL, LPL, EF, E-Mount)'),\n\n    ('image_circle_mm',\n      '(image\\\\\\\\s*circle|covering\\\\\\\\s*power|image\\\\\\\\s*diameter|coverage\\\\\\\\s*circle)',\n      '(optical|image\\\\\\\\s*circle|coverage|sensor)',\n      90, 'Cinema lens: image circle diameter in mm'),\n\n    ('cine_focal_length_mm',\n      '(focal\\\\\\\\s*length\\\\\\\\b)',\n      '(lens|optical|specifications?)',\n      90, 'Cinema lens: focal length in mm'),\n\n    ('cine_t_stop',\n      '(t.?stop|t-?aperture|maximum\\\\\\\\s*aperture|speed)',\n      '(optical|aperture|speed|lens)',\n      90, 'Cinema lens: maximum T-stop'),\n\n    ('cine_sensor_coverage',\n      '(sensor\\\\\\\\s*(coverage|format|compatibility)|covering\\\\\\\\s*(super\\\\\\\\s*35|large\\\\\\\\s*format|full\\\\\\\\s*frame)|format\\\\\\\\s*(coverage|compatibility))',\n      '(optical|coverage|sensor|compatibility)',\n      85, 'Cinema lens: sensor format coverage (S35, LF, FF)'),\n\n    ('lens_set_id',\n      '(lens\\\\\\\\s*set|series\\\\\\\\s*name|product\\\\\\\\s*(family|series|line)|set\\\\\\\\s*(name|identifier))',\n      '(general|lens|series|family)',\n      70, 'Cinema lens: product family/set identifier (Cooke S4/i, Zeiss Supreme, etc.)'),\n\n    ('cine_close_focus_m',\n      '(close\\\\\\\\s*focus|minimum\\\\\\\\s*object\\\\\\\\s*distance|mod\\\\\\\\b|closest\\\\\\\\s*focus(ing)?)',\n      '(focusing|optical|specifications?)',\n      80, 'Cinema lens: minimum focus distance in metres'),\n\n    ('cine_front_diameter_mm',\n      '(front\\\\\\\\s*(diameter|element|clear\\\\\\\\s*aperture)|barrel\\\\\\\\s*diameter)',\n      '(physical|exterior|optical)',\n      80, 'Cinema lens: front barrel diameter in mm'),\n\n    ('cine_gear_pitch',\n      '(iris\\\\\\\\s*gear|gear\\\\\\\\s*pitch|aperture\\\\\\\\s*gear|0\\\\\\\\.4\\\\\\\\s*mod|0\\\\\\\\.8\\\\\\\\s*mod)',\n      '(optical|iris|gear|mechanical)',\n      85, 'Cinema lens: iris gear pitch (0.4 mod cinema standard)'),\n\n    ('cine_focus_gear_pitch',\n      '(focus\\\\\\\\s*gear|focus\\\\\\\\s*ring\\\\\\\\s*gear|0\\\\\\\\.4\\\\\\\\s*mod\\\\\\\\s*focus)',\n      '(focusing|gear|mechanical)',\n      80, 'Cinema lens: focus ring gear pitch'),\n\n    ('cine_zoom_ratio',\n      '(zoom\\\\\\\\s*ratio|\\\\\\\\d+(\\\\\\\\.\\\\\\\\d+)?\\\\\\\\s*[xX]\\\\\\\\s*zoom)',\n      '(optical|zoom)',\n      75, 'Cinema zoom: zoom ratio (e.g. 12:1)'),\n\n    ('cine_anamorphic_factor',\n      '(anamorphic\\\\\\\\s*(factor|ratio|squeeze)|squeeze\\\\\\\\s*(ratio|factor)|a\\\\\\\\s*[12]\\\\\\\\.0)',\n      '(optical|anamorphic)',\n      85, 'Anamorphic lens: squeeze factor (1.33x, 1.5x, 2x)'),\n\n    ('cine_lens_weight_kg',\n      '(\\\\\\\\bweight\\\\\\\\b)',\n      '(physical|specifications?)',\n      80, 'Cinema lens: weight in kg'),\n\n    ('cine_lens_length_mm',\n      '(\\\\\\\\blength\\\\\\\\b|overall\\\\\\\\s*length)',\n      '(physical|dimensions?|specifications?)',\n      75, 'Cinema lens: barrel length in mm'),\n\n    ('has_i_technology',\n      '(/i\\\\\\\\s*technology|cooke\\\\\\\\s*/i|i/i\\\\\\\\s*metadata|intelligent\\\\\\\\s*lens\\\\\\\\s*interface)',\n      '(metadata|electronics|lens|connectivity)',\n      85, 'Cinema lens: Cooke /i Technology metadata protocol'),\n\n    ('has_lds_metadata',\n      '(lds\\\\\\\\b|lens\\\\\\\\s*data\\\\\\\\s*system|extended\\\\\\\\s*data|zeiss\\\\\\\\s*extended|arri\\\\\\\\s*lds)',\n      '(metadata|electronics|lens|connectivity)',\n      80, 'Cinema lens: LDS / eXtended Data metadata'),\n\n    ('has_electronic_iris',\n      '(electronic\\\\\\\\s*iris|motorized\\\\\\\\s*aperture|e-?iris|iris\\\\\\\\s*motor)',\n      '(electronics|iris|aperture)',\n      75, 'Cinema lens: electronic iris control')\n\n  ) AS v(normalized_key, extraction_pattern, context_pattern, priority, notes)\n  JOIN spec_definition sd ON sd.normalized_key = v.normalized_key\n  WHERE NOT EXISTS (\n    SELECT 1 FROM spec_mapping sm\n    WHERE sm.spec_definition_id = sd.id\n      AND sm.extraction_pattern = v.extraction_pattern\n      AND sm.context_pattern IS NOT DISTINCT FROM v.context_pattern\n  );\nEND $$"}	seed_cinema_lens_specs
20260408000006	{"-- ─────────────────────────────────────────────────────────────────────────────\n-- Section 8: 80/20 demo seed set\n-- 3 camera bodies, 2 lens sets, 1 zoom, 6 accessories = 12 items\n-- Touches all 7 compatibility axes + seeds product_relationship + kit_template\n-- ─────────────────────────────────────────────────────────────────────────────\n\nDO $$\nDECLARE\n  -- Brands\n  b_arri     UUID; b_sony     UUID; b_red      UUID;\n  b_cooke    UUID; b_zeiss    UUID; b_ang      UUID;\n  b_smallhd  UUID; b_teradek  UUID; b_anton    UUID;\n\n  -- Categories\n  c_cinema_cam   UUID; c_pl_primes  UUID; c_lpl_primes UUID;\n  c_zoom         UUID; c_on_board   UUID; c_wireless   UUID;\n  c_fiz          UUID; c_matte      UUID; c_gold_batt  UUID;\n  c_cine_adapt   UUID;\n\n  -- Products\n  p_alexa35   UUID; p_venice2   UUID; p_raptor   UUID;\n  p_cooke_s4  UUID; p_zeiss_sp  UUID; p_ang_zoom UUID;\n  p_smallhd7  UUID; p_bolt4k    UUID; p_wcu4     UUID;\n  p_mb20      UUID; p_cine90    UUID; p_pllpl    UUID;\n\n  -- Axes\n  ax_mount    UUID; ax_sensor   UUID; ax_rod     UUID;\n  ax_power    UUID; ax_media    UUID; ax_signal  UUID;\n  ax_pitch    UUID;\n\n  -- Spec definitions (cameras)\n  sd_sensor_size  UUID; sd_dynamic_range UUID; sd_lens_mount UUID;\n  sd_rec_formats  UUID; sd_rec_media     UUID; sd_power_in   UUID;\n  sd_base_iso     UUID;\n\n  -- Spec definitions (lenses)\n  sd_cl_mount     UUID; sd_image_circle  UUID; sd_focal_len  UUID;\n  sd_t_stop       UUID; sd_sensor_cov    UUID; sd_gear_pitch UUID;\n  sd_i_tech       UUID; sd_lens_set_id   UUID; sd_zoom_ratio UUID;\n\n  -- Kit template\n  kt_alexa35 UUID;\n\nBEGIN\n\n  -- ── Resolve brand IDs ───────────────────────────────────────────────────────\n  SELECT id INTO b_arri    FROM brand WHERE slug = 'arri';\n  SELECT id INTO b_sony    FROM brand WHERE slug = 'sony';\n  SELECT id INTO b_red     FROM brand WHERE slug = 'red';\n  SELECT id INTO b_cooke   FROM brand WHERE slug = 'cooke';\n  SELECT id INTO b_zeiss   FROM brand WHERE slug = 'zeiss';\n  SELECT id INTO b_ang     FROM brand WHERE slug = 'angenieux';\n  SELECT id INTO b_smallhd FROM brand WHERE slug = 'smallhd';\n  SELECT id INTO b_teradek FROM brand WHERE slug = 'teradek';\n  SELECT id INTO b_anton   FROM brand WHERE slug = 'anton-bauer';\n\n  -- ── Resolve category IDs ────────────────────────────────────────────────────\n  SELECT id INTO c_cinema_cam  FROM product_category WHERE slug = 'cinema-cameras';\n  SELECT id INTO c_pl_primes   FROM product_category WHERE slug = 'cinema-prime-sets-pl';\n  SELECT id INTO c_lpl_primes  FROM product_category WHERE slug = 'cinema-prime-sets-lpl';\n  SELECT id INTO c_zoom        FROM product_category WHERE slug = 'cinema-zoom-lenses';\n  SELECT id INTO c_on_board    FROM product_category WHERE slug = 'on-board-monitors';\n  SELECT id INTO c_wireless    FROM product_category WHERE slug = 'wireless-video';\n  SELECT id INTO c_fiz         FROM product_category WHERE slug = 'follow-focus-fiz';\n  SELECT id INTO c_matte       FROM product_category WHERE slug = 'matte-boxes';\n  SELECT id INTO c_gold_batt   FROM product_category WHERE slug = 'batteries-gold-mount';\n  SELECT id INTO c_cine_adapt  FROM product_category WHERE slug = 'cinema-lens-adapters';\n\n  -- ── Resolve compatibility axis IDs ──────────────────────────────────────────\n  SELECT id INTO ax_mount   FROM compatibility_axis WHERE slug = 'lens_mount';\n  SELECT id INTO ax_sensor  FROM compatibility_axis WHERE slug = 'sensor_format';\n  SELECT id INTO ax_rod     FROM compatibility_axis WHERE slug = 'rod_system';\n  SELECT id INTO ax_power   FROM compatibility_axis WHERE slug = 'power_standard';\n  SELECT id INTO ax_media   FROM compatibility_axis WHERE slug = 'recording_media';\n  SELECT id INTO ax_signal  FROM compatibility_axis WHERE slug = 'signal_output';\n  SELECT id INTO ax_pitch   FROM compatibility_axis WHERE slug = 'gear_pitch';\n\n  -- ── Resolve spec definition IDs — cameras ───────────────────────────────────\n  SELECT id INTO sd_sensor_size   FROM spec_definition WHERE normalized_key = 'cinema_sensor_size';\n  SELECT id INTO sd_dynamic_range FROM spec_definition WHERE normalized_key = 'cinema_dynamic_range';\n  SELECT id INTO sd_lens_mount    FROM spec_definition WHERE normalized_key = 'cinema_lens_mount';\n  SELECT id INTO sd_rec_formats   FROM spec_definition WHERE normalized_key = 'cinema_recording_formats';\n  SELECT id INTO sd_rec_media     FROM spec_definition WHERE normalized_key = 'cinema_recording_media';\n  SELECT id INTO sd_power_in      FROM spec_definition WHERE normalized_key = 'cinema_power_input';\n  SELECT id INTO sd_base_iso      FROM spec_definition WHERE normalized_key = 'cinema_base_iso';\n\n  -- ── Resolve spec definition IDs — lenses ────────────────────────────────────\n  SELECT id INTO sd_cl_mount    FROM spec_definition WHERE normalized_key = 'cine_lens_mount';\n  SELECT id INTO sd_image_circle FROM spec_definition WHERE normalized_key = 'image_circle_mm';\n  SELECT id INTO sd_focal_len   FROM spec_definition WHERE normalized_key = 'cine_focal_length_mm';\n  SELECT id INTO sd_t_stop      FROM spec_definition WHERE normalized_key = 'cine_t_stop';\n  SELECT id INTO sd_sensor_cov  FROM spec_definition WHERE normalized_key = 'cine_sensor_coverage';\n  SELECT id INTO sd_gear_pitch  FROM spec_definition WHERE normalized_key = 'cine_gear_pitch';\n  SELECT id INTO sd_i_tech      FROM spec_definition WHERE normalized_key = 'has_i_technology';\n  SELECT id INTO sd_lens_set_id FROM spec_definition WHERE normalized_key = 'lens_set_id';\n  SELECT id INTO sd_zoom_ratio  FROM spec_definition WHERE normalized_key = 'cine_zoom_ratio';\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- 1. PRODUCTS\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  -- Camera bodies\n  INSERT INTO product (brand_id, category_id, model, full_name, slug, manufacturer_url, is_active) VALUES\n    (b_arri, c_cinema_cam, 'ALEXA 35',      'ARRI ALEXA 35',          'arri-alexa-35',       'https://www.arri.com/en/camera-systems/cameras/alexa-35',           true),\n    (b_sony, c_cinema_cam, 'VENICE 2',      'Sony VENICE 2',          'sony-venice-2',       'https://www.sony.com/en/articles/venice-2',                         true),\n    (b_red,  c_cinema_cam, 'V-RAPTOR 8K VV','RED V-RAPTOR 8K VV',     'red-v-raptor-8k-vv',  'https://www.red.com/v-raptor',                                      true)\n  ON CONFLICT (slug) DO NOTHING;\n\n  -- Lens sets\n  INSERT INTO product (brand_id, category_id, model, full_name, slug, manufacturer_url, is_active) VALUES\n    (b_cooke, c_pl_primes,  'S4/i Set',           'Cooke S4/i Prime Set (PL)',         'cooke-s4i-set',           'https://www.cookeoptics.com/lenses/s4i/',              true),\n    (b_zeiss, c_lpl_primes, 'Supreme Prime Set',  'Zeiss Supreme Prime Set (PL/LPL)',  'zeiss-supreme-prime-set', 'https://www.zeiss.com/consumer-products/us/cinematography/supreme-prime-lenses.html', true),\n    (b_ang,   c_zoom,       'Optimo 24-290mm',    'Angenieux Optimo 24-290mm T2.8',    'angenieux-optimo-24-290', 'https://www.angenieux.com/optimo-24-290',              true)\n  ON CONFLICT (slug) DO NOTHING;\n\n  -- Accessories\n  INSERT INTO product (brand_id, category_id, model, full_name, slug, manufacturer_url, is_active) VALUES\n    (b_smallhd,  c_on_board,   'Cine 7 (Bolt 6 RX)',  'SmallHD Cine 7 with Bolt 6 RX',        'smallhd-cine-7',         'https://smallhd.com/products/cine-7-bolt-6-rx',            true),\n    (b_teradek,  c_wireless,   'Bolt 4K LT 750',       'Teradek Bolt 4K LT 750 TX/RX',         'teradek-bolt-4k-lt-750', 'https://teradek.com/products/bolt-4k-lt-750',               true),\n    (b_arri,     c_fiz,        'WCU-4',                'ARRI WCU-4 Wireless Compact Unit',      'arri-wcu-4',             'https://www.arri.com/en/accessories/camera-control/wcu-4',  true),\n    (b_arri,     c_matte,      'MB-20 II',             'ARRI MB-20 II Matte Box',               'arri-mb-20-ii',          'https://www.arri.com/en/accessories/matte-boxes',           true),\n    (b_anton,    c_gold_batt,  'CINE 90',              'Anton Bauer CINE 90 Gold Mount Battery','anton-bauer-cine-90',    'https://www.antonbauer.com',                                true),\n    (b_arri,     c_cine_adapt, 'PL to LPL Adapter',   'ARRI PL to LPL Lens Adapter',           'arri-pl-lpl-adapter',    'https://www.arri.com/en/camera-systems/lenses/arri-pl-to-lpl-adapter', true)\n  ON CONFLICT (slug) DO NOTHING;\n\n  -- ── Capture product IDs ──────────────────────────────────────────────────────\n  SELECT id INTO p_alexa35  FROM product WHERE slug = 'arri-alexa-35';\n  SELECT id INTO p_venice2  FROM product WHERE slug = 'sony-venice-2';\n  SELECT id INTO p_raptor   FROM product WHERE slug = 'red-v-raptor-8k-vv';\n  SELECT id INTO p_cooke_s4 FROM product WHERE slug = 'cooke-s4i-set';\n  SELECT id INTO p_zeiss_sp FROM product WHERE slug = 'zeiss-supreme-prime-set';\n  SELECT id INTO p_ang_zoom FROM product WHERE slug = 'angenieux-optimo-24-290';\n  SELECT id INTO p_smallhd7 FROM product WHERE slug = 'smallhd-cine-7';\n  SELECT id INTO p_bolt4k   FROM product WHERE slug = 'teradek-bolt-4k-lt-750';\n  SELECT id INTO p_wcu4     FROM product WHERE slug = 'arri-wcu-4';\n  SELECT id INTO p_mb20     FROM product WHERE slug = 'arri-mb-20-ii';\n  SELECT id INTO p_cine90   FROM product WHERE slug = 'anton-bauer-cine-90';\n  SELECT id INTO p_pllpl    FROM product WHERE slug = 'arri-pl-lpl-adapter';\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- 2. PRODUCT SPECS (key specs for camera bodies and lens sets)\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  -- ARRI ALEXA 35\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value) VALUES\n    (p_alexa35, sd_sensor_size,   'Super 35 / 4.6K (4608 × 3164)'),\n    (p_alexa35, sd_dynamic_range, '17 stops'),\n    (p_alexa35, sd_lens_mount,    'LPL (PL via included adapter)'),\n    (p_alexa35, sd_rec_formats,   'ARRIRAW, Apple ProRes (4444 XQ, 4444, 422 HQ, 422, 422 LT, 422 Proxy)'),\n    (p_alexa35, sd_rec_media,     'CFexpress Type B (Mag System)'),\n    (p_alexa35, sd_power_in,      'Gold Mount (24V DC, Anton Bauer)'),\n    (p_alexa35, sd_base_iso,      '800 / 3200 (Dual Native)')\n  ON CONFLICT (product_id, spec_definition_id) DO NOTHING;\n\n  -- Sony VENICE 2\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value) VALUES\n    (p_venice2, sd_sensor_size,   'Full Frame / 8.6K (8640 × 5760)'),\n    (p_venice2, sd_dynamic_range, '16 stops'),\n    (p_venice2, sd_lens_mount,    'Native E-Mount lever lock (PL via CBK-3610XS)'),\n    (p_venice2, sd_rec_formats,   'X-OCN ST/LT/XT, Apple ProRes 4444/422 HQ'),\n    (p_venice2, sd_rec_media,     'SxS Pro+, AXS-R7 (via extension unit)'),\n    (p_venice2, sd_power_in,      'BP-GL95B / V-Mount / Gold Mount (via adapter)'),\n    (p_venice2, sd_base_iso,      '800 / 3200 (Dual Native)')\n  ON CONFLICT (product_id, spec_definition_id) DO NOTHING;\n\n  -- RED V-RAPTOR 8K VV\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value) VALUES\n    (p_raptor, sd_sensor_size,   'Vista Vision / 8K (8192 × 4320)'),\n    (p_raptor, sd_dynamic_range, '17+ stops (REDCODE RAW)'),\n    (p_raptor, sd_lens_mount,    'PL'),\n    (p_raptor, sd_rec_formats,   'REDCODE RAW, Apple ProRes, Avid DNxHR'),\n    (p_raptor, sd_rec_media,     'REDMAG 1TB SSD'),\n    (p_raptor, sd_power_in,      'V-Mount (DSMC Battery Grip)'),\n    (p_raptor, sd_base_iso,      '250 / 1600 (Dual Native)')\n  ON CONFLICT (product_id, spec_definition_id) DO NOTHING;\n\n  -- Cooke S4/i Set (PL)\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value, boolean_value) VALUES\n    (p_cooke_s4, sd_cl_mount,     'PL',          null),\n    (p_cooke_s4, sd_image_circle, '31.5',        null),\n    (p_cooke_s4, sd_t_stop,       'T2',          null),\n    (p_cooke_s4, sd_sensor_cov,   'Super 35',    null),\n    (p_cooke_s4, sd_gear_pitch,   '0.4 mod',     null),\n    (p_cooke_s4, sd_i_tech,       null,          true),\n    (p_cooke_s4, sd_lens_set_id,  'cooke-s4i',   null)\n  ON CONFLICT (product_id, spec_definition_id) DO NOTHING;\n\n  -- Zeiss Supreme Prime Set (PL / LPL)\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value, boolean_value) VALUES\n    (p_zeiss_sp, sd_cl_mount,     'PL / LPL',       null),\n    (p_zeiss_sp, sd_image_circle, '46.31',           null),\n    (p_zeiss_sp, sd_t_stop,       'T1.5',            null),\n    (p_zeiss_sp, sd_sensor_cov,   'Full Frame',      null),\n    (p_zeiss_sp, sd_gear_pitch,   '0.4 mod',         null),\n    (p_zeiss_sp, sd_i_tech,       null,              false),\n    (p_zeiss_sp, sd_lens_set_id,  'zeiss-supreme-prime', null)\n  ON CONFLICT (product_id, spec_definition_id) DO NOTHING;\n\n  -- Angenieux Optimo 24-290mm\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value) VALUES\n    (p_ang_zoom, sd_cl_mount,    'PL'),\n    (p_ang_zoom, sd_t_stop,      'T2.8'),\n    (p_ang_zoom, sd_sensor_cov,  'Super 35'),\n    (p_ang_zoom, sd_gear_pitch,  '0.4 mod'),\n    (p_ang_zoom, sd_zoom_ratio,  '12:1')\n  ON CONFLICT (product_id, spec_definition_id) DO NOTHING;\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- 3. PRODUCT COMPATIBILITY VALUES (all 7 axes)\n  --\n  -- is_input = true  → product ACCEPTS / requires this value\n  -- is_input = false → product PROVIDES / outputs this value\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO product_compatibility_value (product_id, axis_id, value, is_input, notes) VALUES\n\n    -- ── ARRI ALEXA 35 ──────────────────────────────────────────────────────────\n    (p_alexa35, ax_mount,  'LPL',           true,  'Native LPL mount'),\n    (p_alexa35, ax_mount,  'PL',            true,  'PL via included LPL-to-PL adapter'),\n    (p_alexa35, ax_sensor, 'S35',           false, 'Super 35 4.6K sensor'),\n    (p_alexa35, ax_rod,    '15mm_lws',      true,  '15mm LWS via baseplate'),\n    (p_alexa35, ax_rod,    '19mm_studio',   true,  '19mm studio via ARRI baseplate'),\n    (p_alexa35, ax_power,  'gold_mount',    true,  'Anton Bauer Gold Mount (24V DC)'),\n    (p_alexa35, ax_media,  'cfexpress_b',   true,  'CFexpress Type B in ALEXA 35 Mag'),\n    (p_alexa35, ax_signal, '3g_sdi',        false, 'MON OUT — 3G-SDI'),\n    (p_alexa35, ax_signal, '12g_sdi',       false, 'MON OUT — up to 12G-SDI'),\n\n    -- ── Sony VENICE 2 ──────────────────────────────────────────────────────────\n    (p_venice2, ax_mount,  'E-Mount',       true,  'Native E-Mount lever lock'),\n    (p_venice2, ax_mount,  'PL',            true,  'PL via CBK-3610XS or LA-FZB2 adapter'),\n    (p_venice2, ax_sensor, 'FF',            false, 'Full Frame 8.6K'),\n    (p_venice2, ax_rod,    '15mm_lws',      true,  NULL),\n    (p_venice2, ax_rod,    '19mm_studio',   true,  NULL),\n    (p_venice2, ax_power,  'v_mount',       true,  'V-Mount via BP-GL95B or adapter'),\n    (p_venice2, ax_power,  'gold_mount',    true,  'Gold Mount via adapter plate'),\n    (p_venice2, ax_media,  'sxs',           true,  'SxS Pro+ cards (built-in)'),\n    (p_venice2, ax_signal, '3g_sdi',        false, NULL),\n    (p_venice2, ax_signal, '12g_sdi',       false, '4× 3G-SDI = 12G equivalent'),\n\n    -- ── RED V-RAPTOR 8K VV ─────────────────────────────────────────────────────\n    (p_raptor, ax_mount,  'PL',            true,  'PL mount (native)'),\n    (p_raptor, ax_sensor, 'FF',            false, 'Vista Vision — wider than S35, close to FF'),\n    (p_raptor, ax_rod,    '15mm_lws',      true,  'Via baseplate'),\n    (p_raptor, ax_power,  'v_mount',       true,  'DSMC Battery Grip — V-Mount'),\n    (p_raptor, ax_media,  'redmag',        true,  'REDMAG 1TB SSD (proprietary)'),\n    (p_raptor, ax_signal, '12g_sdi',       false, '12G-SDI monitor output'),\n\n    -- ── Cooke S4/i Prime Set (PL) ──────────────────────────────────────────────\n    (p_cooke_s4, ax_mount,  'PL',           false, 'PL mount — provides PL'),\n    (p_cooke_s4, ax_sensor, 'S35',          false, '31.5mm image circle — covers Super 35'),\n    (p_cooke_s4, ax_pitch,  '0_4mod_cinema',false, 'Standard 0.4 mod cinema iris and focus gears'),\n\n    -- ── Zeiss Supreme Prime Set (PL / LPL) ────────────────────────────────────\n    (p_zeiss_sp, ax_mount,  'PL',           false, 'PL mount version'),\n    (p_zeiss_sp, ax_mount,  'LPL',          false, 'LPL mount version'),\n    (p_zeiss_sp, ax_sensor, 'FF',           false, '46.31mm image circle — covers Full Frame'),\n    (p_zeiss_sp, ax_pitch,  '0_4mod_cinema',false, '0.4 mod cinema gears'),\n\n    -- ── Angenieux Optimo 24-290mm ──────────────────────────────────────────────\n    (p_ang_zoom, ax_mount,  'PL',           false, 'PL mount'),\n    (p_ang_zoom, ax_sensor, 'S35',          false, 'Covers Super 35'),\n    (p_ang_zoom, ax_pitch,  '0_4mod_cinema',false, '0.4 mod cinema gears'),\n\n    -- ── SmallHD Cine 7 ─────────────────────────────────────────────────────────\n    (p_smallhd7, ax_power,  'gold_mount',   true,  'Gold Mount plate on back'),\n    (p_smallhd7, ax_power,  'v_mount',      true,  'V-Mount plate (with adapter)'),\n    (p_smallhd7, ax_signal, '3g_sdi',       true,  '3G-SDI input'),\n    (p_smallhd7, ax_signal, 'hdmi_2_0',     true,  'HDMI input'),\n\n    -- ── Teradek Bolt 4K LT 750 ─────────────────────────────────────────────────\n    (p_bolt4k, ax_power,  'gold_mount',    true,  'Gold Mount on TX and RX'),\n    (p_bolt4k, ax_power,  'v_mount',       true,  'V-Mount with adapter'),\n    (p_bolt4k, ax_power,  'd_tap',         true,  'D-Tap cable power'),\n    (p_bolt4k, ax_signal, '3g_sdi',        true,  'SDI input on TX / output on RX'),\n    (p_bolt4k, ax_signal, 'hdmi_2_0',      true,  'HDMI input on TX / output on RX'),\n\n    -- ── ARRI WCU-4 ─────────────────────────────────────────────────────────────\n    (p_wcu4, ax_pitch, '0_4mod_cinema',   true,  'Drives 0.4 mod cinema lens gears'),\n    (p_wcu4, ax_rod,   '15mm_lws',        true,  '15mm LWS rod mount for motor'),\n    (p_wcu4, ax_rod,   '19mm_studio',     true,  '19mm studio rod mount for motor'),\n\n    -- ── ARRI MB-20 II ──────────────────────────────────────────────────────────\n    (p_mb20, ax_rod, '15mm_lws',          true,  '15mm LWS rod mount'),\n    (p_mb20, ax_rod, '19mm_studio',       true,  '19mm studio rod mount'),\n\n    -- ── Anton Bauer CINE 90 ────────────────────────────────────────────────────\n    (p_cine90, ax_power, 'gold_mount',    false, 'Provides Gold Mount power'),\n\n    -- ── ARRI PL to LPL Adapter ────────────────────────────────────────────────\n    -- Camera side: presents LPL to the camera body (the camera accepts LPL)\n    -- Lens side: accepts PL lenses (the lens provides PL)\n    (p_pllpl, ax_mount, 'LPL',            false, 'Camera-side — presents LPL to LPL camera'),\n    (p_pllpl, ax_mount, 'PL',             true,  'Lens-side — accepts PL lenses')\n\n  ON CONFLICT (product_id, axis_id, value) DO NOTHING;\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- 4. PRODUCT RELATIONSHIPS\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO product_relationship (source_product_id, target_product_id, relationship_type, is_conditional, condition_note, notes) VALUES\n\n    -- ALEXA 35 kit essentials\n    (p_alexa35, p_pllpl,    'requires',   true,  'Only when using PL-mount lenses — LPL glass attaches natively',\n                                                   'ARRI includes one PL-to-LPL adapter in the ALEXA 35 box'),\n    (p_alexa35, p_cine90,   'recommends', false,  NULL,\n                                                   'Gold Mount is the standard power solution for ALEXA 35'),\n    (p_alexa35, p_mb20,     'recommends', false,  NULL,\n                                                   'MB-20 II is the matched matte box for ARRI bodies'),\n    (p_alexa35, p_wcu4,     'recommends', false,  NULL,\n                                                   'WCU-4 integrates natively with ALEXA camera bus (no cable required)'),\n    (p_alexa35, p_cooke_s4, 'recommends', false,  NULL,\n                                                   'Cooke S4/i is the most-rented PL prime set for ALEXA 35 S35 work'),\n    (p_alexa35, p_zeiss_sp, 'recommends', false,  NULL,\n                                                   'Zeiss Supreme Primes cover FF and S35 — ideal for open-gate on ALEXA 35'),\n\n    -- VENICE 2 kit\n    (p_venice2, p_zeiss_sp, 'recommends', false,  NULL,\n                                                   'Supreme Primes cover full frame — the natural FF lens choice for VENICE 2'),\n    (p_venice2, p_pllpl,    'requires',   true,  'Only when using PL lenses via CBK-3610XS adapter',\n                                                   'VENICE 2 native mount is E-Mount; PL requires Sony adapter unit'),\n\n    -- RED V-RAPTOR\n    (p_raptor,  p_cooke_s4, 'recommends', false,  NULL,\n                                                   'Cooke S4/i is the standard PL prime choice for RED bodies'),\n    (p_raptor,  p_wcu4,     'recommends', false,  NULL,\n                                                   'WCU-4 works on any PL-body build with 15mm rods'),\n\n    -- Wireless pairing — TX needs RX\n    (p_bolt4k,  p_smallhd7, 'recommends', false,  NULL,\n                                                   'SmallHD Cine 7 has integrated Bolt 6 RX — the natural director monitor pairing'),\n\n    -- Lens → FIZ compatibility\n    (p_cooke_s4, p_wcu4,   'recommends', false,  NULL,\n                                                   'Cooke S4/i 0.4 mod gears work directly with WCU-4 motors'),\n    (p_zeiss_sp, p_wcu4,   'recommends', false,  NULL,\n                                                   'Zeiss Supreme 0.4 mod gears work directly with WCU-4'),\n    (p_ang_zoom, p_wcu4,   'recommends', false,  NULL,\n                                                   'Optimo 24-290 requires FIZ — WCU-4 is the standard choice on ARRI builds')\n\n  ON CONFLICT (source_product_id, target_product_id, relationship_type) DO NOTHING;\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- 5. KIT TEMPLATE — \\"ALEXA 35 Standard Narrative Kit\\"\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO kit_template (name, anchor_product_id, shoot_type, description, is_public)\n  VALUES (\n    'ALEXA 35 — Standard Narrative Kit',\n    p_alexa35,\n    'narrative',\n    'Full S35 narrative package anchored on the ARRI ALEXA 35. Cooke S4/i primes, ARRI WCU-4 FIZ, MB-20 II matte box, Anton Bauer Gold Mount power, and SmallHD Cine 7 director monitor with Teradek wireless. Touches all 7 compatibility axes.',\n    true\n  )\n  ON CONFLICT DO NOTHING\n  RETURNING id INTO kt_alexa35;\n\n  -- Capture ID if it already existed (RETURNING only works on the INSERT path)\n  IF kt_alexa35 IS NULL THEN\n    SELECT id INTO kt_alexa35 FROM kit_template WHERE name = 'ALEXA 35 — Standard Narrative Kit';\n  END IF;\n\n  INSERT INTO kit_template_item (kit_template_id, product_id, quantity, is_required, sort_order, notes) VALUES\n    -- Camera body (anchor — listed first for UI display)\n    (kt_alexa35, p_alexa35,  1, true,  10, NULL),\n    -- Power — required to run anything\n    (kt_alexa35, p_cine90,   2, true,  20, '2× batteries recommended for a full shoot day'),\n    -- Lenses\n    (kt_alexa35, p_cooke_s4, 1, false, 30, 'S4/i full set — most-rented PL prime for S35'),\n    (kt_alexa35, p_ang_zoom, 1, false, 40, 'Optimo 24-290 as the production zoom'),\n    -- Adapter (conditional on using PL lenses)\n    (kt_alexa35, p_pllpl,    1, false, 50, 'Required if using PL lenses — ARRI includes one in box'),\n    -- Support & control\n    (kt_alexa35, p_mb20,     1, true,  60, NULL),\n    (kt_alexa35, p_wcu4,     1, false, 70, 'Recommended — integrates via ALEXA camera bus'),\n    -- Village\n    (kt_alexa35, p_smallhd7, 1, false, 80, 'Director / DIT monitor'),\n    (kt_alexa35, p_bolt4k,   1, false, 90, 'Wireless TX/RX for director monitor')\n  ON CONFLICT DO NOTHING;\n\nEND $$"}	seed_demo_80_20
20260409000000	{"-- Migration: RED V-RAPTOR 8K VV — accurate product specs and compatibility values.\n--\n-- Source: https://www.red.com/v-raptor (RED official spec sheet)\n-- Spec values are verbatim from the RED V-RAPTOR 8K VV product page.\n--\n-- The product row (slug = 'red-v-raptor-8k-vv') was seeded in\n-- 20260408000006_seed_demo_80_20.sql with placeholder spec_values.\n-- This migration upserts all specs with accurate data using\n-- ON CONFLICT ... DO UPDATE so it overwrites the placeholders.\n--\n-- Safe to re-run: product_spec uses DO UPDATE; compatibility values use DO NOTHING\n-- (they were already seeded correctly in the demo migration).\n\nDO $$\nDECLARE\n  p_id     UUID;\n\n  -- Compatibility axes\n  ax_mount  UUID;\n  ax_sensor UUID;\n  ax_rod    UUID;\n  ax_power  UUID;\n  ax_media  UUID;\n  ax_signal UUID;\n\n  -- Spec definitions\n  sd_sensor_size   UUID;\n  sd_dynamic_range UUID;\n  sd_lens_mount    UUID;\n  sd_rec_formats   UUID;\n  sd_rec_media     UUID;\n  sd_power_in      UUID;\n  sd_base_iso      UUID;\n  sd_max_fps       UUID;\n  sd_weight        UUID;\n  sd_sensor_type   UUID;\n  sd_max_res       UUID;\n  sd_sdi_out       UUID;\n  sd_hdmi          UUID;\n  sd_internal_nd   UUID;\n  sd_log_format    UUID;\n  sd_color_space   UUID;\n  sd_timecode      UUID;\n\nBEGIN\n\n  -- ── Resolve product ID ───────────────────────────────────────────────────────\n  SELECT id INTO p_id FROM product WHERE slug = 'red-v-raptor-8k-vv';\n  IF p_id IS NULL THEN\n    RAISE EXCEPTION 'Product red-v-raptor-8k-vv not found — run demo seed first.';\n  END IF;\n\n  -- ── Resolve compatibility axis IDs ──────────────────────────────────────────\n  SELECT id INTO ax_mount   FROM compatibility_axis WHERE slug = 'lens_mount';\n  SELECT id INTO ax_sensor  FROM compatibility_axis WHERE slug = 'sensor_format';\n  SELECT id INTO ax_rod     FROM compatibility_axis WHERE slug = 'rod_system';\n  SELECT id INTO ax_power   FROM compatibility_axis WHERE slug = 'power_standard';\n  SELECT id INTO ax_media   FROM compatibility_axis WHERE slug = 'recording_media';\n  SELECT id INTO ax_signal  FROM compatibility_axis WHERE slug = 'signal_output';\n\n  -- ── Resolve spec definition IDs ─────────────────────────────────────────────\n  SELECT id INTO sd_sensor_size   FROM spec_definition WHERE normalized_key = 'cinema_sensor_size';\n  SELECT id INTO sd_dynamic_range FROM spec_definition WHERE normalized_key = 'cinema_dynamic_range';\n  SELECT id INTO sd_lens_mount    FROM spec_definition WHERE normalized_key = 'cinema_lens_mount';\n  SELECT id INTO sd_rec_formats   FROM spec_definition WHERE normalized_key = 'cinema_recording_formats';\n  SELECT id INTO sd_rec_media     FROM spec_definition WHERE normalized_key = 'cinema_recording_media';\n  SELECT id INTO sd_power_in      FROM spec_definition WHERE normalized_key = 'cinema_power_input';\n  SELECT id INTO sd_base_iso      FROM spec_definition WHERE normalized_key = 'cinema_base_iso';\n  SELECT id INTO sd_max_fps       FROM spec_definition WHERE normalized_key = 'cinema_max_fps';\n  SELECT id INTO sd_weight        FROM spec_definition WHERE normalized_key = 'cinema_weight';\n  SELECT id INTO sd_sensor_type   FROM spec_definition WHERE normalized_key = 'cinema_sensor_type';\n  SELECT id INTO sd_max_res       FROM spec_definition WHERE normalized_key = 'cinema_max_resolution';\n  SELECT id INTO sd_sdi_out       FROM spec_definition WHERE normalized_key = 'cinema_sdi_outputs';\n  SELECT id INTO sd_hdmi          FROM spec_definition WHERE normalized_key = 'cinema_hdmi';\n  SELECT id INTO sd_internal_nd   FROM spec_definition WHERE normalized_key = 'cinema_internal_nd';\n  SELECT id INTO sd_log_format    FROM spec_definition WHERE normalized_key = 'cinema_log_format';\n  SELECT id INTO sd_color_space   FROM spec_definition WHERE normalized_key = 'cinema_color_space';\n  SELECT id INTO sd_timecode      FROM spec_definition WHERE normalized_key = 'cinema_timecode_io';\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- PRODUCT SPECS\n  -- Verbatim values from the RED V-RAPTOR 8K VV spec sheet.\n  -- Uses DO UPDATE to overwrite the placeholder values from the demo seed.\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value) VALUES\n\n    -- Image Sensor\n    (p_id, sd_sensor_type,   'RED MONSTRO 8K VV CMOS'),\n    (p_id, sd_sensor_size,   'Vista Vision (46.31mm × 23.99mm)'),\n    (p_id, sd_dynamic_range, '17+ stops'),\n    (p_id, sd_base_iso,      '250 / 1600 (Dual Native ISO)'),\n    (p_id, sd_max_fps,       '120'),   -- 8K VV up to 120fps (cropped modes higher)\n\n    -- Recording\n    (p_id, sd_max_res,       '8192 × 4320 (8K VV)'),\n    (p_id, sd_rec_formats,   'REDCODE RAW (R3D), Apple ProRes (4444 XQ, 4444, 422 HQ, 422, 422 LT, 422 Proxy), Avid DNxHR/DNxHD'),\n    (p_id, sd_rec_media,     'REDMAG 1TB SSD (REDMAG Slot)'),\n    (p_id, sd_internal_nd,   'None (no internal ND)'),\n\n    -- Optics & Mount\n    (p_id, sd_lens_mount,    'PL'),\n\n    -- Color Science\n    (p_id, sd_log_format,    'REDlogFilm, Log3G10'),\n    (p_id, sd_color_space,   'REDWideGamutRGB'),\n\n    -- Connectivity\n    (p_id, sd_sdi_out,       '1× 12G-SDI (BNC, monitor output)'),\n    (p_id, sd_hdmi,          'None'),\n    (p_id, sd_timecode,      'LTC in/out (LEMO 5-pin)'),\n\n    -- Physical\n    (p_id, sd_power_in,      '26.4V DC — V-Mount battery via DSMC Battery Grip; 24V DC via DSMC Power Adaptor'),\n    (p_id, sd_weight,        '2313')   -- grams, body only (no lens, no battery)\n\n  ON CONFLICT (product_id, spec_definition_id)\n  DO UPDATE SET spec_value = EXCLUDED.spec_value;\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- COMPATIBILITY VALUES\n  -- The demo seed already inserted the core rows with DO NOTHING.\n  -- Re-insert here with DO NOTHING to be idempotent; add the HDMI-absent\n  -- signal note and any rows the demo seed omitted.\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO product_compatibility_value (product_id, axis_id, value, is_input, notes) VALUES\n\n    -- Lens mount — camera ACCEPTS PL lenses\n    (p_id, ax_mount,  'PL',          true,  'Native PL mount'),\n\n    -- Sensor format — camera PROVIDES Vista Vision output\n    -- VV is wider than Super 35, comparable to Full Frame; maps to FF for compatibility\n    (p_id, ax_sensor, 'FF',          false, 'Vista Vision sensor (46.31 × 23.99mm) — wider than S35, maps to FF for lens coverage'),\n\n    -- Rod system — camera ACCEPTS 15mm LWS via baseplate\n    (p_id, ax_rod,    '15mm_lws',    true,  'Via DSMC2 Production Module or third-party baseplate'),\n\n    -- Power — camera ACCEPTS V-Mount (DSMC Battery Grip)\n    (p_id, ax_power,  'v_mount',     true,  'DSMC Battery Grip — V-Mount (26.4V DC)'),\n\n    -- Recording media — camera ACCEPTS REDMAG SSDs\n    (p_id, ax_media,  'redmag',      true,  'REDMAG 1TB SSD (REDMAG Slot, proprietary)'),\n\n    -- Signal output — camera PROVIDES 12G-SDI\n    (p_id, ax_signal, '12g_sdi',     false, '1× 12G-SDI BNC monitor output')\n\n  ON CONFLICT (product_id, axis_id, value) DO NOTHING;\n\nEND $$"}	scrape_red_v_raptor
20260409000001	{"-- Migration: Blackmagic URSA Mini Pro 12K — accurate product specs and compatibility values.\n--\n-- Source: Blackmagic Design official spec sheet (https://www.blackmagicdesign.com/products/blackmagicursaminipro)\n-- Spec values reflect the URSA Mini Pro 12K as shipped; EF and PL mount variants\n-- share the same sensor/recording specs — mount differences are captured in\n-- product_compatibility_value (both accepted) and in the lens_mount spec_value.\n--\n-- This migration:\n--   1. Inserts the product row (slug = 'blackmagic-ursa-mini-pro-12k')\n--   2. Upserts all product_spec rows with accurate values\n--   3. Inserts product_compatibility_value rows for all relevant axes\n--\n-- Safe to re-run: product INSERT uses ON CONFLICT DO NOTHING;\n-- product_spec uses ON CONFLICT ... DO UPDATE; compatibility values use DO NOTHING.\n\nDO $$\nDECLARE\n  b_id     UUID;\n  cat_id   UUID;\n  p_id     UUID;\n\n  -- Compatibility axes\n  ax_mount  UUID;\n  ax_sensor UUID;\n  ax_rod    UUID;\n  ax_power  UUID;\n  ax_media  UUID;\n  ax_signal UUID;\n\n  -- Spec definitions\n  sd_sensor_size   UUID;\n  sd_sensor_type   UUID;\n  sd_dynamic_range UUID;\n  sd_lens_mount    UUID;\n  sd_rec_formats   UUID;\n  sd_rec_media     UUID;\n  sd_power_in      UUID;\n  sd_base_iso      UUID;\n  sd_max_fps       UUID;\n  sd_weight        UUID;\n  sd_max_res       UUID;\n  sd_sdi_out       UUID;\n  sd_hdmi          UUID;\n  sd_internal_nd   UUID;\n  sd_log_format    UUID;\n  sd_color_space   UUID;\n  sd_timecode      UUID;\n  sd_audio_input   UUID;\n  sd_audio_fmt     UUID;\n  sd_audio_ch      UUID;\n  sd_dimensions    UUID;\n\nBEGIN\n\n  -- ── Resolve brand ID ────────────────────────────────────────────────────────\n  SELECT id INTO b_id FROM brand WHERE slug = 'blackmagic' OR name = 'Blackmagic Design' LIMIT 1;\n  IF b_id IS NULL THEN\n    RAISE EXCEPTION 'Brand Blackmagic Design not found in brand table.';\n  END IF;\n\n  -- ── Resolve category ID ─────────────────────────────────────────────────────\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'cinema-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'Category cinema-cameras not found — run cinema category seed first (20260211000000).';\n  END IF;\n\n  -- ── Upsert product row ──────────────────────────────────────────────────────\n  INSERT INTO product (brand_id, category_id, model, full_name, slug, manufacturer_url, is_active)\n  VALUES (\n    b_id,\n    cat_id,\n    'URSA Mini Pro 12K',\n    'Blackmagic URSA Mini Pro 12K',\n    'blackmagic-ursa-mini-pro-12k',\n    'https://www.blackmagicdesign.com/products/blackmagicursaminipro',\n    true\n  )\n  ON CONFLICT (slug) DO NOTHING;\n\n  SELECT id INTO p_id FROM product WHERE slug = 'blackmagic-ursa-mini-pro-12k';\n  IF p_id IS NULL THEN\n    RAISE EXCEPTION 'Product insert failed for blackmagic-ursa-mini-pro-12k.';\n  END IF;\n\n  -- ── Resolve compatibility axis IDs ──────────────────────────────────────────\n  SELECT id INTO ax_mount   FROM compatibility_axis WHERE slug = 'lens_mount';\n  SELECT id INTO ax_sensor  FROM compatibility_axis WHERE slug = 'sensor_format';\n  SELECT id INTO ax_rod     FROM compatibility_axis WHERE slug = 'rod_system';\n  SELECT id INTO ax_power   FROM compatibility_axis WHERE slug = 'power_standard';\n  SELECT id INTO ax_media   FROM compatibility_axis WHERE slug = 'recording_media';\n  SELECT id INTO ax_signal  FROM compatibility_axis WHERE slug = 'signal_output';\n\n  -- ── Resolve spec definition IDs ─────────────────────────────────────────────\n  SELECT id INTO sd_sensor_size   FROM spec_definition WHERE normalized_key = 'cinema_sensor_size';\n  SELECT id INTO sd_sensor_type   FROM spec_definition WHERE normalized_key = 'cinema_sensor_type';\n  SELECT id INTO sd_dynamic_range FROM spec_definition WHERE normalized_key = 'cinema_dynamic_range';\n  SELECT id INTO sd_lens_mount    FROM spec_definition WHERE normalized_key = 'cinema_lens_mount';\n  SELECT id INTO sd_rec_formats   FROM spec_definition WHERE normalized_key = 'cinema_recording_formats';\n  SELECT id INTO sd_rec_media     FROM spec_definition WHERE normalized_key = 'cinema_recording_media';\n  SELECT id INTO sd_power_in      FROM spec_definition WHERE normalized_key = 'cinema_power_input';\n  SELECT id INTO sd_base_iso      FROM spec_definition WHERE normalized_key = 'cinema_base_iso';\n  SELECT id INTO sd_max_fps       FROM spec_definition WHERE normalized_key = 'cinema_max_fps';\n  SELECT id INTO sd_weight        FROM spec_definition WHERE normalized_key = 'cinema_weight';\n  SELECT id INTO sd_max_res       FROM spec_definition WHERE normalized_key = 'cinema_max_resolution';\n  SELECT id INTO sd_sdi_out       FROM spec_definition WHERE normalized_key = 'cinema_sdi_outputs';\n  SELECT id INTO sd_hdmi          FROM spec_definition WHERE normalized_key = 'cinema_hdmi';\n  SELECT id INTO sd_internal_nd   FROM spec_definition WHERE normalized_key = 'cinema_internal_nd';\n  SELECT id INTO sd_log_format    FROM spec_definition WHERE normalized_key = 'cinema_log_format';\n  SELECT id INTO sd_color_space   FROM spec_definition WHERE normalized_key = 'cinema_color_space';\n  SELECT id INTO sd_timecode      FROM spec_definition WHERE normalized_key = 'cinema_timecode_io';\n  SELECT id INTO sd_audio_input   FROM spec_definition WHERE normalized_key = 'cinema_audio_input';\n  SELECT id INTO sd_audio_fmt     FROM spec_definition WHERE normalized_key = 'cinema_audio_format';\n  SELECT id INTO sd_audio_ch      FROM spec_definition WHERE normalized_key = 'cinema_audio_channels';\n  SELECT id INTO sd_dimensions    FROM spec_definition WHERE normalized_key = 'cinema_dimensions';\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- PRODUCT SPECS\n  -- Verbatim / closely paraphrased from the Blackmagic URSA Mini Pro 12K\n  -- official spec sheet. Values reflect the base EF/PL interchangeable-mount\n  -- body. Where the spec differs by mount or media config, the more common\n  -- production value is listed with a parenthetical qualifier.\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value) VALUES\n\n    -- Image Sensor\n    -- Super 35+ sensor; Blackmagic calls it \\"Super 35\\" in their docs.\n    -- Physical dimensions: 27.03 × 14.25 mm (diagonal ≈ 30.6 mm).\n    (p_id, sd_sensor_type,   'Blackmagic Design custom 12K CMOS'),\n    (p_id, sd_sensor_size,   'Super 35+ (27.03mm × 14.25mm)'),\n    (p_id, sd_dynamic_range, '13 stops'),\n    (p_id, sd_base_iso,      '400 (ISO 200–3200 range; no dual native ISO)'),\n    -- Maximum fps at full 12K; higher fps available at reduced resolution.\n    -- 12K 17:9 up to 60fps; 8K up to 75fps; lower resolutions higher still.\n    (p_id, sd_max_fps,       '60'),   -- 12K (full resolution)\n\n    -- Recording\n    (p_id, sd_max_res,       '12288 × 6480 (12K)'),\n    -- BRAW = Blackmagic RAW; ProRes = Apple ProRes variants\n    (p_id, sd_rec_formats,\n      'Blackmagic RAW (BRAW 3:1, 5:1, 8:1, 12:1 — constant bitrate; 3:1, 5:1, 8:1, 12:1 — constant quality), '\n      'Apple ProRes (4444 XQ, 4444, 422 HQ, 422, 422 LT, 422 Proxy)'),\n    -- CFast 2.0 is the primary high-speed media slot; USB-C SSD supported simultaneously.\n    -- The URSA Mini Pro 12K has 1× CFast 2.0 + 1× SD card + 1× USB-C expansion.\n    (p_id, sd_rec_media,\n      'CFast 2.0 card (slot 1), SD/UHS-II card (slot 2), USB-C SSD (expansion port)'),\n    -- No internal ND; optional ND filter stage available via URSA Mini Shoulder Kit or third-party.\n    (p_id, sd_internal_nd,   'None (no built-in internal ND filter)'),\n\n    -- Optics & Mount\n    -- The URSA Mini Pro 12K ships with a PL mount installed and includes an EF mount adapter.\n    -- Both PL and EF are first-class supported mounts — listed here as primary.\n    (p_id, sd_lens_mount,    'PL (included), EF (included adapter), B4 (optional adapter), F (optional adapter)'),\n\n    -- Color Science\n    (p_id, sd_log_format,    'Blackmagic Design Film (Generation 5)'),\n    (p_id, sd_color_space,   'Blackmagic Wide Gamut'),\n\n    -- Connectivity\n    -- 1× 12G-SDI output (BNC) for monitoring; no second SDI output.\n    (p_id, sd_sdi_out,       '1× 12G-SDI output (BNC)'),\n    -- Mini HDMI Type A output for monitoring.\n    (p_id, sd_hdmi,          '1× Mini HDMI Type A output'),\n    -- SMPTE LTC timecode via 3.5mm jack (I/O, bidirectional).\n    (p_id, sd_timecode,      'SMPTE LTC in/out (3.5mm jack)'),\n\n    -- Audio\n    -- 2× mini XLR inputs (analog), phantom power selectable per channel.\n    (p_id, sd_audio_input,   '2× mini XLR (3-pin) — mic/line switchable, 48V phantom power'),\n    (p_id, sd_audio_fmt,     'Uncompressed 24-bit 48kHz PCM'),\n    (p_id, sd_audio_ch,      '4'),  -- 4 channels (2 analog + 2 embedded from SDI/HDMI input)\n\n    -- Physical\n    -- Body weight without lens, battery, or media: ~2650 g (manufacturer spec ~2.6 kg).\n    (p_id, sd_weight,        '2650'),  -- grams, body only\n    -- H × W × D (approximate from official drawings): 148.0 × 212.4 × 175.8 mm\n    (p_id, sd_dimensions,    '148.0 × 212.4 × 175.8 mm (H × W × D, body only)'),\n    -- Power: LP-E6 battery (body native, 2× slot), OR external 12V–20V DC via Anton Bauer\n    -- Gold Mount plate (sold separately). The URSA Mini Pro 12K ships with an LP-E6\n    -- battery compartment; Gold Mount is the industry standard accessory plate.\n    (p_id, sd_power_in,\n      '12–20V DC via 4-pin XLR, or 2× Canon LP-E6 internal batteries, or Anton Bauer Gold Mount plate (optional)')\n\n  ON CONFLICT (product_id, spec_definition_id)\n  DO UPDATE SET spec_value = EXCLUDED.spec_value;\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- COMPATIBILITY VALUES\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO product_compatibility_value (product_id, axis_id, value, is_input, notes) VALUES\n\n    -- ── Lens mount — camera ACCEPTS PL and EF lenses ───────────────────────────\n    -- PL is installed at the factory and is the primary cinema mount.\n    (p_id, ax_mount,  'PL',           true,  'Native PL mount (installed at factory; swappable)'),\n    -- EF adapter is included in the box; no optical elements — native electronic control.\n    (p_id, ax_mount,  'EF',           true,  'Interchangeable EF mount adapter (included in box)'),\n\n    -- ── Sensor format — camera PROVIDES Super 35 image area ────────────────────\n    -- 27.03 × 14.25 mm is within the Super 35 envelope; maps to S35.\n    (p_id, ax_sensor, 'S35',          false, 'Super 35+ sensor (27.03 × 14.25mm) — covers S35 lens image circles'),\n\n    -- ── Rod system — camera ACCEPTS 15mm LWS via third-party baseplate ─────────\n    (p_id, ax_rod,    '15mm_lws',     true,  'Via URSA Mini Shoulder Kit or any 15mm LWS baseplate'),\n\n    -- ── Power — camera ACCEPTS LP-E6 (internal) AND Gold Mount (external plate) ─\n    -- LP-E6 is the built-in battery solution (2× internal).\n    (p_id, ax_power,  'lp_e6',        true,  '2× Canon LP-E6 internal battery slots (native)'),\n    -- Gold Mount plate attaches to the rear of the camera body via the standard\n    -- Blackmagic camera power adapter plates (sold separately by Anton Bauer et al.).\n    (p_id, ax_power,  'gold_mount',   true,  'Anton Bauer Gold Mount plate (optional, rear-mount accessory)'),\n    -- V-Mount plate is also supported via compatible adapter plates.\n    (p_id, ax_power,  'v_mount',      true,  'V-Mount plate (optional, via compatible adapter plate)'),\n    -- 12V–20V DC via 4-pin XLR (on-body connector) accepts Anton Bauer D-Tap / 12V brick.\n    (p_id, ax_power,  'd_tap',        true,  '12–20V DC via 4-pin XLR (D-Tap compatible power adapters)'),\n\n    -- ── Recording media — camera ACCEPTS CFast 2.0, SD, and USB-C SSD ─────────\n    (p_id, ax_media,  'cfast_2',      true,  'CFast 2.0 (slot 1) — primary high-speed recording media'),\n    (p_id, ax_media,  'usb_c_ssd',    true,  'USB-C SSD (expansion port) — simultaneous record / backup'),\n\n    -- ── Signal output — camera PROVIDES 12G-SDI and HDMI ──────────────────────\n    (p_id, ax_signal, '12g_sdi',      false, '1× 12G-SDI BNC monitor output'),\n    (p_id, ax_signal, 'hdmi_2_0',     false, '1× Mini HDMI Type A output (up to 4K 60p monitoring)')\n\n  ON CONFLICT (product_id, axis_id, value) DO NOTHING;\n\nEND $$"}	scrape_blackmagic_ursa
20260409000002	{"-- Add 'member_of' to product_relationship_type.\n-- Must be its own migration so the value is committed before the lens-set\n-- migrations (20260409000003–000005) attempt to use it.\n\nALTER TYPE product_relationship_type ADD VALUE IF NOT EXISTS 'member_of'"}	add_member_of_enum
20260409000003	{"-- Migration: Cooke S4/i Prime Set — complete per-focal-length spec data.\n--\n-- Source: Cooke Optics official S4/i lens specification sheets.\n-- Spec values are accurate to the production S4/i set (current generation).\n--\n-- The set-level product row (slug = 'cooke-s4i-set') and its summary specs\n-- were seeded in 20260408000006_seed_demo_80_20.sql.\n--\n-- This migration:\n--   1. Upserts the set-level product specs with accurate values (DO UPDATE).\n--   2. Inserts individual per-focal-length product rows (16 lenses, 12mm–300mm).\n--   3. Seeds full product_spec rows for every individual lens.\n--   4. Seeds product_compatibility_value rows for every individual lens.\n--   5. Seeds product_relationship rows linking each individual lens to the set.\n--\n-- Safe to re-run: all inserts use ON CONFLICT DO NOTHING / DO UPDATE.\n\nDO $$\nDECLARE\n  -- Brand / category\n  b_cooke   UUID;\n  c_pl_primes UUID;\n\n  -- Set-level product\n  p_set     UUID;\n\n  -- Individual lens product IDs (16 focal lengths)\n  p_12mm    UUID;  p_14mm    UUID;  p_16mm    UUID;  p_18mm    UUID;\n  p_21mm    UUID;  p_25mm    UUID;  p_27mm    UUID;  p_32mm    UUID;\n  p_35mm    UUID;  p_40mm    UUID;  p_50mm    UUID;  p_65mm    UUID;\n  p_75mm    UUID;  p_100mm   UUID;  p_135mm   UUID;  p_300mm   UUID;\n\n  -- Compatibility axes\n  ax_mount  UUID;\n  ax_sensor UUID;\n  ax_pitch  UUID;\n\n  -- Spec definitions — set level\n  sd_cl_mount    UUID;\n  sd_img_circle  UUID;\n  sd_focal_len   UUID;\n  sd_t_stop      UUID;\n  sd_sensor_cov  UUID;\n  sd_gear_pitch  UUID;\n  sd_i_tech      UUID;\n  sd_lens_set_id UUID;\n  sd_close_focus UUID;\n  sd_front_diam  UUID;\n  sd_weight      UUID;\n  sd_length      UUID;\n\nBEGIN\n\n  -- ── Resolve brand and category ───────────────────────────────────────────────\n  SELECT id INTO b_cooke     FROM brand            WHERE slug = 'cooke';\n  SELECT id INTO c_pl_primes FROM product_category WHERE slug = 'cinema-prime-sets-pl';\n\n  IF b_cooke     IS NULL THEN RAISE EXCEPTION 'Brand cooke not found.'; END IF;\n  IF c_pl_primes IS NULL THEN RAISE EXCEPTION 'Category cinema-prime-sets-pl not found.'; END IF;\n\n  -- ── Resolve compatibility axis IDs ──────────────────────────────────────────\n  SELECT id INTO ax_mount  FROM compatibility_axis WHERE slug = 'lens_mount';\n  SELECT id INTO ax_sensor FROM compatibility_axis WHERE slug = 'sensor_format';\n  SELECT id INTO ax_pitch  FROM compatibility_axis WHERE slug = 'gear_pitch';\n\n  -- ── Resolve spec definition IDs ─────────────────────────────────────────────\n  SELECT id INTO sd_cl_mount    FROM spec_definition WHERE normalized_key = 'cine_lens_mount';\n  SELECT id INTO sd_img_circle  FROM spec_definition WHERE normalized_key = 'image_circle_mm';\n  SELECT id INTO sd_focal_len   FROM spec_definition WHERE normalized_key = 'cine_focal_length_mm';\n  SELECT id INTO sd_t_stop      FROM spec_definition WHERE normalized_key = 'cine_t_stop';\n  SELECT id INTO sd_sensor_cov  FROM spec_definition WHERE normalized_key = 'cine_sensor_coverage';\n  SELECT id INTO sd_gear_pitch  FROM spec_definition WHERE normalized_key = 'cine_gear_pitch';\n  SELECT id INTO sd_i_tech      FROM spec_definition WHERE normalized_key = 'has_i_technology';\n  SELECT id INTO sd_lens_set_id FROM spec_definition WHERE normalized_key = 'lens_set_id';\n  SELECT id INTO sd_close_focus FROM spec_definition WHERE normalized_key = 'cine_close_focus_m';\n  SELECT id INTO sd_front_diam  FROM spec_definition WHERE normalized_key = 'cine_front_diameter_mm';\n  SELECT id INTO sd_weight      FROM spec_definition WHERE normalized_key = 'cine_lens_weight_kg';\n  SELECT id INTO sd_length      FROM spec_definition WHERE normalized_key = 'cine_lens_length_mm';\n\n  -- ── Resolve set-level product ────────────────────────────────────────────────\n  SELECT id INTO p_set FROM product WHERE slug = 'cooke-s4i-set';\n  IF p_set IS NULL THEN\n    RAISE EXCEPTION 'Product cooke-s4i-set not found — run demo seed first.';\n  END IF;\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- 1. UPSERT SET-LEVEL PRODUCT SPECS (accurate values, overwrite placeholders)\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value, boolean_value) VALUES\n    (p_set, sd_cl_mount,    'PL',          null),\n    (p_set, sd_img_circle,  '31.5',        null),  -- mm; covers Super 35\n    (p_set, sd_t_stop,      'T2',          null),  -- max aperture across set\n    (p_set, sd_sensor_cov,  'Super 35',    null),\n    (p_set, sd_gear_pitch,  '0.4 mod',     null),\n    (p_set, sd_i_tech,      null,          true),  -- /i Technology on all S4/i lenses\n    (p_set, sd_lens_set_id, 'cooke-s4i',   null)\n  ON CONFLICT (product_id, spec_definition_id)\n  DO UPDATE SET\n    spec_value    = EXCLUDED.spec_value,\n    boolean_value = EXCLUDED.boolean_value;\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- 2. INSERT INDIVIDUAL LENS PRODUCTS (16 focal lengths)\n  --\n  -- Naming convention: \\"Cooke S4/i {fl}mm T2\\" — the T-stop designation used\n  -- by Cooke in their official lens rental datasheets.\n  -- Slugs: cooke-s4i-{fl}mm\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO product (brand_id, category_id, model, full_name, slug, manufacturer_url, is_active) VALUES\n    (b_cooke, c_pl_primes, 'S4/i 12mm T2',\n      'Cooke S4/i 12mm T2 Prime Lens',\n      'cooke-s4i-12mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 14mm T2',\n      'Cooke S4/i 14mm T2 Prime Lens',\n      'cooke-s4i-14mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 16mm T2',\n      'Cooke S4/i 16mm T2 Prime Lens',\n      'cooke-s4i-16mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 18mm T2',\n      'Cooke S4/i 18mm T2 Prime Lens',\n      'cooke-s4i-18mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 21mm T2',\n      'Cooke S4/i 21mm T2 Prime Lens',\n      'cooke-s4i-21mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 25mm T2',\n      'Cooke S4/i 25mm T2 Prime Lens',\n      'cooke-s4i-25mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 27mm T2',\n      'Cooke S4/i 27mm T2 Prime Lens',\n      'cooke-s4i-27mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 32mm T2',\n      'Cooke S4/i 32mm T2 Prime Lens',\n      'cooke-s4i-32mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 35mm T2',\n      'Cooke S4/i 35mm T2 Prime Lens',\n      'cooke-s4i-35mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 40mm T2',\n      'Cooke S4/i 40mm T2 Prime Lens',\n      'cooke-s4i-40mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 50mm T2',\n      'Cooke S4/i 50mm T2 Prime Lens',\n      'cooke-s4i-50mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 65mm T2',\n      'Cooke S4/i 65mm T2 Prime Lens',\n      'cooke-s4i-65mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 75mm T2',\n      'Cooke S4/i 75mm T2 Prime Lens',\n      'cooke-s4i-75mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 100mm T2',\n      'Cooke S4/i 100mm T2 Prime Lens',\n      'cooke-s4i-100mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 135mm T2',\n      'Cooke S4/i 135mm T2 Prime Lens',\n      'cooke-s4i-135mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true),\n\n    (b_cooke, c_pl_primes, 'S4/i 300mm T2.8',\n      'Cooke S4/i 300mm T2.8 Prime Lens',\n      'cooke-s4i-300mm',\n      'https://www.cookeoptics.com/lenses/s4i/',  true)\n\n  ON CONFLICT (slug) DO NOTHING;\n\n  -- ── Capture individual lens IDs ──────────────────────────────────────────────\n  SELECT id INTO p_12mm  FROM product WHERE slug = 'cooke-s4i-12mm';\n  SELECT id INTO p_14mm  FROM product WHERE slug = 'cooke-s4i-14mm';\n  SELECT id INTO p_16mm  FROM product WHERE slug = 'cooke-s4i-16mm';\n  SELECT id INTO p_18mm  FROM product WHERE slug = 'cooke-s4i-18mm';\n  SELECT id INTO p_21mm  FROM product WHERE slug = 'cooke-s4i-21mm';\n  SELECT id INTO p_25mm  FROM product WHERE slug = 'cooke-s4i-25mm';\n  SELECT id INTO p_27mm  FROM product WHERE slug = 'cooke-s4i-27mm';\n  SELECT id INTO p_32mm  FROM product WHERE slug = 'cooke-s4i-32mm';\n  SELECT id INTO p_35mm  FROM product WHERE slug = 'cooke-s4i-35mm';\n  SELECT id INTO p_40mm  FROM product WHERE slug = 'cooke-s4i-40mm';\n  SELECT id INTO p_50mm  FROM product WHERE slug = 'cooke-s4i-50mm';\n  SELECT id INTO p_65mm  FROM product WHERE slug = 'cooke-s4i-65mm';\n  SELECT id INTO p_75mm  FROM product WHERE slug = 'cooke-s4i-75mm';\n  SELECT id INTO p_100mm FROM product WHERE slug = 'cooke-s4i-100mm';\n  SELECT id INTO p_135mm FROM product WHERE slug = 'cooke-s4i-135mm';\n  SELECT id INTO p_300mm FROM product WHERE slug = 'cooke-s4i-300mm';\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- 3. PRODUCT SPECS — per focal length\n  --\n  -- Close focus distances sourced from Cooke S4/i datasheets (imperial converted\n  -- to metres, rounded to 2 d.p.):\n  --   12mm  0.20m (8\\")     14mm  0.22m (8.7\\")   16mm  0.25m (10\\")\n  --   18mm  0.28m (11\\")    21mm  0.30m (12\\")     25mm  0.33m (13\\")\n  --   27mm  0.36m (14\\")    32mm  0.40m (16\\")     35mm  0.43m (17\\")\n  --   40mm  0.46m (18\\")    50mm  0.46m (18\\")     65mm  0.61m (24\\")\n  --   75mm  0.61m (24\\")   100mm  0.76m (30\\")    135mm  0.91m (36\\")\n  --  300mm  1.83m (6')\n  --\n  -- Front diameters:\n  --   12–21mm: 95mm front; 25–40mm: 110mm front; 50–135mm: 110mm front;\n  --   300mm: 110mm front (same front barrel diameter across most of set).\n  --\n  -- Weights (kg, body-only, approximate from Cooke rental datasheets):\n  --   12mm  1.25   14mm  1.25   16mm  1.25   18mm  1.25\n  --   21mm  1.36   25mm  1.36   27mm  1.36   32mm  1.36\n  --   35mm  1.36   40mm  1.47   50mm  1.47   65mm  1.59\n  --   75mm  1.59  100mm  1.70  135mm  1.81  300mm  3.49\n  --\n  -- Lengths (mm, flange to front):\n  --   12mm  130   14mm  130   16mm  130   18mm  130\n  --   21mm  140   25mm  140   27mm  140   32mm  140\n  --   35mm  141   40mm  148   50mm  148   65mm  165\n  --   75mm  165  100mm  178  135mm  191  300mm  257\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  -- ── 12mm T2 ─────────────────────────────────────────────────────────────────\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value, boolean_value) VALUES\n    (p_12mm, sd_cl_mount,    'PL',         null),\n    (p_12mm, sd_img_circle,  '31.5',       null),\n    (p_12mm, sd_focal_len,   '12',         null),\n    (p_12mm, sd_t_stop,      'T2',         null),\n    (p_12mm, sd_sensor_cov,  'Super 35',   null),\n    (p_12mm, sd_gear_pitch,  '0.4 mod',    null),\n    (p_12mm, sd_i_tech,      null,         true),\n    (p_12mm, sd_lens_set_id, 'cooke-s4i',  null),\n    (p_12mm, sd_close_focus, '0.20',       null),\n    (p_12mm, sd_front_diam,  '95',         null),\n    (p_12mm, sd_weight,      '1.25',       null),\n    (p_12mm, sd_length,      '130',        null)\n  ON CONFLICT (product_id, spec_definition_id) DO NOTHING;\n\n  -- ── 14mm T2 ─────────────────────────────────────────────────────────────────\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value, boolean_value) VALUES\n    (p_14mm, sd_cl_mount,    'PL',         