00mm T2 ────────────────────────────────────────────────────────────────\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value, boolean_value) VALUES\n    (p_100mm, sd_cl_mount,    'PL',         null),\n    (p_100mm, sd_img_circle,  '31.5',       null),\n    (p_100mm, sd_focal_len,   '100',        null),\n    (p_100mm, sd_t_stop,      'T2',         null),\n    (p_100mm, sd_sensor_cov,  'Super 35',   null),\n    (p_100mm, sd_gear_pitch,  '0.4 mod',    null),\n    (p_100mm, sd_i_tech,      null,         true),\n    (p_100mm, sd_lens_set_id, 'cooke-s4i',  null),\n    (p_100mm, sd_close_focus, '0.76',       null),\n    (p_100mm, sd_front_diam,  '110',        null),\n    (p_100mm, sd_weight,      '1.70',       null),\n    (p_100mm, sd_length,      '178',        null)\n  ON CONFLICT (product_id, spec_definition_id) DO NOTHING;\n\n  -- ── 135mm T2 ────────────────────────────────────────────────────────────────\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value, boolean_value) VALUES\n    (p_135mm, sd_cl_mount,    'PL',         null),\n    (p_135mm, sd_img_circle,  '31.5',       null),\n    (p_135mm, sd_focal_len,   '135',        null),\n    (p_135mm, sd_t_stop,      'T2',         null),\n    (p_135mm, sd_sensor_cov,  'Super 35',   null),\n    (p_135mm, sd_gear_pitch,  '0.4 mod',    null),\n    (p_135mm, sd_i_tech,      null,         true),\n    (p_135mm, sd_lens_set_id, 'cooke-s4i',  null),\n    (p_135mm, sd_close_focus, '0.91',       null),\n    (p_135mm, sd_front_diam,  '110',        null),\n    (p_135mm, sd_weight,      '1.81',       null),\n    (p_135mm, sd_length,      '191',        null)\n  ON CONFLICT (product_id, spec_definition_id) DO NOTHING;\n\n  -- ── 300mm T2.8 ──────────────────────────────────────────────────────────────\n  -- The 300mm is the sole exception in the S4/i set: T2.8 max aperture\n  -- (not T2), reflecting the physical constraints of a 300mm telephoto design.\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value, boolean_value) VALUES\n    (p_300mm, sd_cl_mount,    'PL',         null),\n    (p_300mm, sd_img_circle,  '31.5',       null),\n    (p_300mm, sd_focal_len,   '300',        null),\n    (p_300mm, sd_t_stop,      'T2.8',       null),   -- only lens in set not T2\n    (p_300mm, sd_sensor_cov,  'Super 35',   null),\n    (p_300mm, sd_gear_pitch,  '0.4 mod',    null),\n    (p_300mm, sd_i_tech,      null,         true),\n    (p_300mm, sd_lens_set_id, 'cooke-s4i',  null),\n    (p_300mm, sd_close_focus, '1.83',       null),   -- 6 feet\n    (p_300mm, sd_front_diam,  '110',        null),\n    (p_300mm, sd_weight,      '3.49',       null),\n    (p_300mm, sd_length,      '257',        null)\n  ON CONFLICT (product_id, spec_definition_id) DO NOTHING;\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- 4. COMPATIBILITY VALUES — per individual lens\n  --\n  -- Each S4/i lens:\n  --   ax_mount  → provides 'PL'          (is_input = false: the lens has a PL mount)\n  --   ax_sensor → provides 'S35'         (is_input = false: 31.5mm circle covers S35)\n  --   ax_pitch  → provides '0_4mod_cinema'(is_input = false: 0.4 mod iris + focus gears)\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO product_compatibility_value (product_id, axis_id, value, is_input, notes) VALUES\n    -- 12mm\n    (p_12mm, ax_mount,  'PL',             false, 'PL mount'),\n    (p_12mm, ax_sensor, 'S35',            false, '31.5mm image circle — covers Super 35'),\n    (p_12mm, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema iris and focus gears'),\n    -- 14mm\n    (p_14mm, ax_mount,  'PL',             false, 'PL mount'),\n    (p_14mm, ax_sensor, 'S35',            false, '31.5mm image circle — covers Super 35'),\n    (p_14mm, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema iris and focus gears'),\n    -- 16mm\n    (p_16mm, ax_mount,  'PL',             false, 'PL mount'),\n    (p_16mm, ax_sensor, 'S35',            false, '31.5mm image circle — covers Super 35'),\n    (p_16mm, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema iris and focus gears'),\n    -- 18mm\n    (p_18mm, ax_mount,  'PL',             false, 'PL mount'),\n    (p_18mm, ax_sensor, 'S35',            false, '31.5mm image circle — covers Super 35'),\n    (p_18mm, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema iris and focus gears'),\n    -- 21mm\n    (p_21mm, ax_mount,  'PL',             false, 'PL mount'),\n    (p_21mm, ax_sensor, 'S35',            false, '31.5mm image circle — covers Super 35'),\n    (p_21mm, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema iris and focus gears'),\n    -- 25mm\n    (p_25mm, ax_mount,  'PL',             false, 'PL mount'),\n    (p_25mm, ax_sensor, 'S35',            false, '31.5mm image circle — covers Super 35'),\n    (p_25mm, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema iris and focus gears'),\n    -- 27mm\n    (p_27mm, ax_mount,  'PL',             false, 'PL mount'),\n    (p_27mm, ax_sensor, 'S35',            false, '31.5mm image circle — covers Super 35'),\n    (p_27mm, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema iris and focus gears'),\n    -- 32mm\n    (p_32mm, ax_mount,  'PL',             false, 'PL mount'),\n    (p_32mm, ax_sensor, 'S35',            false, '31.5mm image circle — covers Super 35'),\n    (p_32mm, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema iris and focus gears'),\n    -- 35mm\n    (p_35mm, ax_mount,  'PL',             false, 'PL mount'),\n    (p_35mm, ax_sensor, 'S35',            false, '31.5mm image circle — covers Super 35'),\n    (p_35mm, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema iris and focus gears'),\n    -- 40mm\n    (p_40mm, ax_mount,  'PL',             false, 'PL mount'),\n    (p_40mm, ax_sensor, 'S35',            false, '31.5mm image circle — covers Super 35'),\n    (p_40mm, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema iris and focus gears'),\n    -- 50mm\n    (p_50mm, ax_mount,  'PL',             false, 'PL mount'),\n    (p_50mm, ax_sensor, 'S35',            false, '31.5mm image circle — covers Super 35'),\n    (p_50mm, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema iris and focus gears'),\n    -- 65mm\n    (p_65mm, ax_mount,  'PL',             false, 'PL mount'),\n    (p_65mm, ax_sensor, 'S35',            false, '31.5mm image circle — covers Super 35'),\n    (p_65mm, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema iris and focus gears'),\n    -- 75mm\n    (p_75mm, ax_mount,  'PL',             false, 'PL mount'),\n    (p_75mm, ax_sensor, 'S35',            false, '31.5mm image circle — covers Super 35'),\n    (p_75mm, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema iris and focus gears'),\n    -- 100mm\n    (p_100mm, ax_mount,  'PL',            false, 'PL mount'),\n    (p_100mm, ax_sensor, 'S35',           false, '31.5mm image circle — covers Super 35'),\n    (p_100mm, ax_pitch,  '0_4mod_cinema', false, '0.4 mod cinema iris and focus gears'),\n    -- 135mm\n    (p_135mm, ax_mount,  'PL',            false, 'PL mount'),\n    (p_135mm, ax_sensor, 'S35',           false, '31.5mm image circle — covers Super 35'),\n    (p_135mm, ax_pitch,  '0_4mod_cinema', false, '0.4 mod cinema iris and focus gears'),\n    -- 300mm\n    (p_300mm, ax_mount,  'PL',            false, 'PL mount'),\n    (p_300mm, ax_sensor, 'S35',           false, '31.5mm image circle — covers Super 35'),\n    (p_300mm, ax_pitch,  '0_4mod_cinema', false, '0.4 mod cinema iris and focus gears')\n\n  ON CONFLICT (product_id, axis_id, value) DO NOTHING;\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- 5. PRODUCT RELATIONSHIPS — individual lens → set\n  --\n  -- Each individual lens is a 'member_of' the set product.\n  -- The set product 'contains' each individual lens.\n  -- Using 'member_of' relationship type to avoid breaking the set's existing\n  -- recommends/requires relationships established in the demo seed.\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO product_relationship (source_product_id, target_product_id, relationship_type, is_conditional, condition_note, notes) VALUES\n    (p_12mm,  p_set, 'member_of', false, NULL, 'Cooke S4/i 12mm is part of the S4/i prime set'),\n    (p_14mm,  p_set, 'member_of', false, NULL, 'Cooke S4/i 14mm is part of the S4/i prime set'),\n    (p_16mm,  p_set, 'member_of', false, NULL, 'Cooke S4/i 16mm is part of the S4/i prime set'),\n    (p_18mm,  p_set, 'member_of', false, NULL, 'Cooke S4/i 18mm is part of the S4/i prime set'),\n    (p_21mm,  p_set, 'member_of', false, NULL, 'Cooke S4/i 21mm is part of the S4/i prime set'),\n    (p_25mm,  p_set, 'member_of', false, NULL, 'Cooke S4/i 25mm is part of the S4/i prime set'),\n    (p_27mm,  p_set, 'member_of', false, NULL, 'Cooke S4/i 27mm is part of the S4/i prime set'),\n    (p_32mm,  p_set, 'member_of', false, NULL, 'Cooke S4/i 32mm is part of the S4/i prime set'),\n    (p_35mm,  p_set, 'member_of', false, NULL, 'Cooke S4/i 35mm is part of the S4/i prime set'),\n    (p_40mm,  p_set, 'member_of', false, NULL, 'Cooke S4/i 40mm is part of the S4/i prime set'),\n    (p_50mm,  p_set, 'member_of', false, NULL, 'Cooke S4/i 50mm is part of the S4/i prime set'),\n    (p_65mm,  p_set, 'member_of', false, NULL, 'Cooke S4/i 65mm is part of the S4/i prime set'),\n    (p_75mm,  p_set, 'member_of', false, NULL, 'Cooke S4/i 75mm is part of the S4/i prime set'),\n    (p_100mm, p_set, 'member_of', false, NULL, 'Cooke S4/i 100mm is part of the S4/i prime set'),\n    (p_135mm, p_set, 'member_of', false, NULL, 'Cooke S4/i 135mm is part of the S4/i prime set'),\n    (p_300mm, p_set, 'member_of', false, NULL, 'Cooke S4/i 300mm T2.8 is part of the S4/i prime set')\n\n  ON CONFLICT (source_product_id, target_product_id, relationship_type) DO NOTHING;\n\nEND $$"}	scrape_cooke_s4i
20260409000004	{"-- ─────────────────────────────────────────────────────────────────────────────\n-- Zeiss Supreme Prime Set — scraped spec seed\n-- Source: https://www.zeiss.com/consumer-products/us/cinematography/supreme-prime-lenses.html\n-- Key specs confirmed from Zeiss published data (April 2026)\n--\n-- Focal lengths available: 15, 18, 21, 25, 29, 35, 40, 50, 65, 85, 100, 135, 150, 200mm\n-- Image circle:  46.31 mm (covers Full Frame / Large Format)\n-- T-stop:        T1.5 (all focal lengths)\n-- Mount:         PL and LPL (ordered separately per focal length)\n-- Front diam.:   95 mm (consistent across all focal lengths)\n-- Iris gear:     0.4 mod (cinema standard)\n-- Focus gear:    0.4 mod (cinema standard)\n-- eXtended Data: YES — Zeiss eXtended Data protocol (LDS-based metadata over /i contact)\n-- /i Technology: NO  — Zeiss proprietary, not Cooke /i\n-- Weight (50mm): ~1.6 kg (varies slightly; 1.4–1.9 kg across the set)\n-- Close focus:   varies by focal length; 50mm = 0.38 m minimum object distance\n--\n-- The product row (slug = 'zeiss-supreme-prime-set') is already seeded in\n-- 20260408000006_seed_demo_80_20.sql. This migration UPSERTs the full spec set\n-- and compatibility values, extending that demo row with scraped detail.\n-- ─────────────────────────────────────────────────────────────────────────────\n\nDO $$\nDECLARE\n  p_id UUID;\n\n  -- Compatibility axes\n  ax_mount  UUID;\n  ax_sensor UUID;\n  ax_pitch  UUID;\n\n  -- Spec definitions\n  sd_cl_mount      UUID;\n  sd_image_circle  UUID;\n  sd_focal_len     UUID;\n  sd_t_stop        UUID;\n  sd_sensor_cov    UUID;\n  sd_gear_pitch    UUID;\n  sd_focus_gear    UUID;\n  sd_i_tech        UUID;\n  sd_lds           UUID;\n  sd_lens_set_id   UUID;\n  sd_close_focus   UUID;\n  sd_front_diam    UUID;\n  sd_weight        UUID;\n\nBEGIN\n\n  -- ── Resolve product ─────────────────────────────────────────────────────────\n  SELECT id INTO p_id FROM product WHERE slug = 'zeiss-supreme-prime-set';\n  IF p_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: product zeiss-supreme-prime-set not found. '\n                    'Run 20260408000006_seed_demo_80_20.sql first.';\n  END IF;\n\n  -- ── Resolve compatibility axes ──────────────────────────────────────────────\n  SELECT id INTO ax_mount  FROM compatibility_axis WHERE slug = 'lens_mount';\n  SELECT id INTO ax_sensor FROM compatibility_axis WHERE slug = 'sensor_format';\n  SELECT id INTO ax_pitch  FROM compatibility_axis WHERE slug = 'gear_pitch';\n\n  -- ── Resolve spec definitions ────────────────────────────────────────────────\n  SELECT id INTO sd_cl_mount     FROM spec_definition WHERE normalized_key = 'cine_lens_mount';\n  SELECT id INTO sd_image_circle FROM spec_definition WHERE normalized_key = 'image_circle_mm';\n  SELECT id INTO sd_focal_len    FROM spec_definition WHERE normalized_key = 'cine_focal_length_mm';\n  SELECT id INTO sd_t_stop       FROM spec_definition WHERE normalized_key = 'cine_t_stop';\n  SELECT id INTO sd_sensor_cov   FROM spec_definition WHERE normalized_key = 'cine_sensor_coverage';\n  SELECT id INTO sd_gear_pitch   FROM spec_definition WHERE normalized_key = 'cine_gear_pitch';\n  SELECT id INTO sd_focus_gear   FROM spec_definition WHERE normalized_key = 'cine_focus_gear_pitch';\n  SELECT id INTO sd_i_tech       FROM spec_definition WHERE normalized_key = 'has_i_technology';\n  SELECT id INTO sd_lds          FROM spec_definition WHERE normalized_key = 'has_lds_metadata';\n  SELECT id INTO sd_lens_set_id  FROM spec_definition WHERE normalized_key = 'lens_set_id';\n  SELECT id INTO sd_close_focus  FROM spec_definition WHERE normalized_key = 'cine_close_focus_m';\n  SELECT id INTO sd_front_diam   FROM spec_definition WHERE normalized_key = 'cine_front_diameter_mm';\n  SELECT id INTO sd_weight       FROM spec_definition WHERE normalized_key = 'cine_lens_weight_kg';\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- PRODUCT SPECS\n  -- Scraped / confirmed from Zeiss Supreme Prime product page and datasheet.\n  --\n  -- image_circle_mm  = 46.31  — published by Zeiss; covers Full Frame 43.1mm\n  --                             diagonal with headroom (LPL spec)\n  -- cine_t_stop      = 1.5    — uniform T1.5 across all focal lengths\n  -- cine_close_focus_m = 0.38 — 50mm representative value (MOD 0.38m);\n  --                             shorter focal lengths are closer (15mm = 0.3m)\n  -- cine_front_diameter_mm = 95 — all Supreme Primes share a 95mm front\n  -- cine_lens_weight_kg = 1.6  — 50mm T1.5; full set ranges 1.4–1.9 kg\n  -- has_lds_metadata  = true   — Zeiss eXtended Data (metadata contacts over\n  --                              the /i pin on PL; LDS on LPL mount)\n  -- has_i_technology  = false  — NOT Cooke /i; Zeiss uses their own protocol\n  -- cine_focal_length_mm = '15, 18, 21, 25, 29, 35, 40, 50, 65, 85, 100, 135,\n  --                          150, 200' — full set as of 2024 lineup\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value, boolean_value) VALUES\n    (p_id, sd_cl_mount,     'PL / LPL',                                                         null),\n    (p_id, sd_image_circle, '46.31',                                                             null),\n    (p_id, sd_t_stop,       '1.5',                                                               null),\n    (p_id, sd_sensor_cov,   'Full Frame',                                                        null),\n    (p_id, sd_gear_pitch,   '0.4 mod',                                                           null),\n    (p_id, sd_focus_gear,   '0.4 mod',                                                           null),\n    (p_id, sd_lens_set_id,  'zeiss-supreme-prime',                                               null),\n    (p_id, sd_focal_len,    '15, 18, 21, 25, 29, 35, 40, 50, 65, 85, 100, 135, 150, 200',       null),\n    (p_id, sd_close_focus,  '0.38',                                                              null),\n    (p_id, sd_front_diam,   '95',                                                                null),\n    (p_id, sd_weight,       '1.6',                                                               null),\n    (p_id, sd_i_tech,       null,                                                                false),\n    (p_id, sd_lds,          null,                                                                true)\n  ON CONFLICT (product_id, spec_definition_id)\n  DO UPDATE SET\n    spec_value    = EXCLUDED.spec_value,\n    boolean_value = EXCLUDED.boolean_value;\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- COMPATIBILITY VALUES\n  --\n  -- Supreme Primes are available in both PL and LPL barrel versions (ordered\n  -- separately per focal length). They cover Full Frame (46.31mm image circle)\n  -- and therefore also cover Super 35 (31.5mm diagonal). All use standard\n  -- 0.4 mod cinema iris and focus gears.\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO product_compatibility_value (product_id, axis_id, value, is_input, notes) VALUES\n    (p_id, ax_mount,  'PL',             false, 'PL mount version available (ordered per focal length)'),\n    (p_id, ax_mount,  'LPL',            false, 'LPL mount version available (ordered per focal length)'),\n    (p_id, ax_sensor, 'FF',             false, '46.31mm image circle — covers Full Frame / Large Format'),\n    (p_id, ax_sensor, 'S35',            false, '46.31mm image circle also covers Super 35 (31.5mm diagonal)'),\n    (p_id, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema iris and focus gears (standard)')\n  ON CONFLICT (product_id, axis_id, value) DO NOTHING;\n\nEND $$"}	scrape_zeiss_supreme
20260409000005	{"-- ─────────────────────────────────────────────────────────────────────────────\n-- Migration: Angenieux Optimo 24-290mm T2.8 — accurate product specs and\n-- compatibility values.\n--\n-- Source: https://www.angenieux.com/optimo-24-290\n-- Spec values sourced from the Angenieux Optimo 24-290mm T2.8 official\n-- product page and published spec sheet.\n--\n-- Key specs:\n--   Mount:          PL\n--   T-stop:         T2.8\n--   Focal range:    24–290mm\n--   Zoom ratio:     12:1\n--   Sensor coverage:Super 35\n--   Image circle:   31.1mm\n--   Close focus:    1.5m (approx. 4 ft 11 in)\n--   Front diameter: 136mm\n--   Weight:         5.4 kg (body, no accessories)\n--   Length:         373mm (at 24mm focal length)\n--   Iris gear:      0.4 mod (standard cinema)\n--   Focus gear:     0.4 mod (standard cinema)\n--   /i Technology:  No (analogue lens, no embedded metadata electronics)\n--   LDS metadata:   No\n--\n-- The product row (slug = 'angenieux-optimo-24-290') was seeded in\n-- 20260408000006_seed_demo_80_20.sql with placeholder spec values.\n-- This migration upserts all specs with accurate data using\n-- ON CONFLICT ... DO UPDATE so it overwrites the placeholders.\n--\n-- Safe to re-run: product_spec uses DO UPDATE; compatibility values use\n-- DO NOTHING (they were already seeded correctly in the demo migration).\n-- ─────────────────────────────────────────────────────────────────────────────\n\nDO $$\nDECLARE\n  p_id UUID;\n\n  -- Compatibility axes\n  ax_mount  UUID;\n  ax_sensor UUID;\n  ax_pitch  UUID;\n\n  -- Spec definitions\n  sd_cl_mount      UUID;\n  sd_image_circle  UUID;\n  sd_focal_len     UUID;\n  sd_t_stop        UUID;\n  sd_sensor_cov    UUID;\n  sd_gear_pitch    UUID;\n  sd_focus_gear    UUID;\n  sd_zoom_ratio    UUID;\n  sd_close_focus   UUID;\n  sd_front_diam    UUID;\n  sd_weight        UUID;\n  sd_length        UUID;\n  sd_i_tech        UUID;\n  sd_lds           UUID;\n\nBEGIN\n\n  -- ── Resolve product ID ───────────────────────────────────────────────────────\n  SELECT id INTO p_id FROM product WHERE slug = 'angenieux-optimo-24-290';\n  IF p_id IS NULL THEN\n    RAISE EXCEPTION 'Product angenieux-optimo-24-290 not found — run demo seed first.';\n  END IF;\n\n  -- ── Resolve compatibility axis IDs ──────────────────────────────────────────\n  SELECT id INTO ax_mount  FROM compatibility_axis WHERE slug = 'lens_mount';\n  SELECT id INTO ax_sensor FROM compatibility_axis WHERE slug = 'sensor_format';\n  SELECT id INTO ax_pitch  FROM compatibility_axis WHERE slug = 'gear_pitch';\n\n  -- ── Resolve spec definition IDs ─────────────────────────────────────────────\n  SELECT id INTO sd_cl_mount     FROM spec_definition WHERE normalized_key = 'cine_lens_mount';\n  SELECT id INTO sd_image_circle FROM spec_definition WHERE normalized_key = 'image_circle_mm';\n  SELECT id INTO sd_focal_len    FROM spec_definition WHERE normalized_key = 'cine_focal_length_mm';\n  SELECT id INTO sd_t_stop       FROM spec_definition WHERE normalized_key = 'cine_t_stop';\n  SELECT id INTO sd_sensor_cov   FROM spec_definition WHERE normalized_key = 'cine_sensor_coverage';\n  SELECT id INTO sd_gear_pitch   FROM spec_definition WHERE normalized_key = 'cine_gear_pitch';\n  SELECT id INTO sd_focus_gear   FROM spec_definition WHERE normalized_key = 'cine_focus_gear_pitch';\n  SELECT id INTO sd_zoom_ratio   FROM spec_definition WHERE normalized_key = 'cine_zoom_ratio';\n  SELECT id INTO sd_close_focus  FROM spec_definition WHERE normalized_key = 'cine_close_focus_m';\n  SELECT id INTO sd_front_diam   FROM spec_definition WHERE normalized_key = 'cine_front_diameter_mm';\n  SELECT id INTO sd_weight       FROM spec_definition WHERE normalized_key = 'cine_lens_weight_kg';\n  SELECT id INTO sd_length       FROM spec_definition WHERE normalized_key = 'cine_lens_length_mm';\n  SELECT id INTO sd_i_tech       FROM spec_definition WHERE normalized_key = 'has_i_technology';\n  SELECT id INTO sd_lds          FROM spec_definition WHERE normalized_key = 'has_lds_metadata';\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- PRODUCT SPECS\n  -- Values from the Angenieux Optimo 24-290mm T2.8 official spec sheet.\n  -- Uses DO UPDATE to overwrite the placeholder values from the demo seed.\n  -- numeric_value carries the machine-readable number; spec_value is the\n  -- human-readable label shown in the UI.\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO product_spec (product_id, spec_definition_id, spec_value, numeric_value, boolean_value) VALUES\n\n    -- Identity\n    (p_id, sd_cl_mount,     'PL',          NULL,    NULL),\n    (p_id, sd_t_stop,       'T2.8',        2.8,     NULL),\n    (p_id, sd_sensor_cov,   'Super 35',    NULL,    NULL),\n    (p_id, sd_zoom_ratio,   '12:1',        NULL,    NULL),\n    (p_id, sd_focal_len,    '24–290mm',    NULL,    NULL),\n\n    -- Optical\n    -- Image circle: 31.1mm — sufficient to cover Super 35 (31.1mm diagonal)\n    (p_id, sd_image_circle, '31.1mm',      31.1,    NULL),\n\n    -- Close focus: 1.5m from front of lens (approx. 4 ft 11 in)\n    (p_id, sd_close_focus,  '1.5m',        1.5,     NULL),\n\n    -- Front diameter: 136mm (Ø136mm barrel — standard for this lens family)\n    (p_id, sd_front_diam,   '136mm',       136.0,   NULL),\n\n    -- Iris gear: standard 0.4 mod cinema pitch\n    (p_id, sd_gear_pitch,   '0.4 mod',     NULL,    NULL),\n\n    -- Focus gear: standard 0.4 mod cinema pitch\n    (p_id, sd_focus_gear,   '0.4 mod',     NULL,    NULL),\n\n    -- Physical\n    -- Weight: 5.4 kg (body only, no lens support bracket)\n    (p_id, sd_weight,       '5.4 kg',      5.4,     NULL),\n\n    -- Length: 373mm at 24mm focal length (extended to ~401mm at 290mm end)\n    (p_id, sd_length,       '373mm',       373.0,   NULL),\n\n    -- Metadata & electronics\n    -- No /i Technology — this is a fully mechanical lens; no embedded chip\n    (p_id, sd_i_tech,       NULL,          NULL,    false),\n\n    -- No LDS / eXtended Data metadata output\n    (p_id, sd_lds,          NULL,          NULL,    false)\n\n  ON CONFLICT (product_id, spec_definition_id)\n  DO UPDATE SET\n    spec_value    = EXCLUDED.spec_value,\n    numeric_value = EXCLUDED.numeric_value,\n    boolean_value = EXCLUDED.boolean_value;\n\n  -- ─────────────────────────────────────────────────────────────────────────────\n  -- COMPATIBILITY VALUES\n  -- The demo seed already inserted the core rows with DO NOTHING.\n  -- Re-insert here with DO NOTHING to be idempotent.\n  -- is_input = false → the lens PROVIDES / presents this value to the system.\n  -- ─────────────────────────────────────────────────────────────────────────────\n\n  INSERT INTO product_compatibility_value (product_id, axis_id, value, is_input, notes) VALUES\n\n    -- Lens mount — the lens PRESENTS PL to the camera body\n    (p_id, ax_mount,  'PL',             false, 'PL mount — mates with any PL camera body'),\n\n    -- Sensor format — the lens COVERS Super 35 (31.1mm image circle)\n    (p_id, ax_sensor, 'S35',            false, '31.1mm image circle — covers Super 35'),\n\n    -- Gear pitch — the lens PROVIDES 0.4 mod cinema gears on iris and focus rings\n    (p_id, ax_pitch,  '0_4mod_cinema',  false, '0.4 mod cinema standard iris and focus gears')\n\n  ON CONFLICT (product_id, axis_id, value) DO NOTHING;\n\nEND $$"}	scrape_angenieux_optimo
20260409000006	{"-- Migration: Ohio rental houses — sourced from ohio_rental_houses.csv in repo root.\n--\n-- Inserts 13 rental houses (14 CSV rows — Liminal Space deduped into 1 house\n-- with 2 locations). Street addresses stored in description; contact emails\n-- are not in the schema so are omitted.\n--\n-- Type assignments:\n--   full_service  — primary cinema/broadcast rental inventory\n--   specialty     — camera stores, photo-focused, studio-first businesses\n--\n-- Safe to re-run: all inserts use ON CONFLICT DO NOTHING.\n\nDO $$\nDECLARE\n  rh_ohio_cinemotion     UUID;\n  rh_cleveland_camera    UUID;\n  rh_dodd                UUID;\n  rh_liminal             UUID;\n  rh_osv                 UUID;\n  rh_mpex                UUID;\n  rh_cencam              UUID;\n  rh_kinopicz            UUID;\n  rh_ohd                 UUID;\n  rh_allprohd            UUID;\n  rh_procam              UUID;\n  rh_akron               UUID;\n  rh_campus              UUID;\nBEGIN\n\n  -- ── Insert rental houses ──────────────────────────────────────────────────\n\n  INSERT INTO rental_house (name, slug, website_url, type, description, is_active) VALUES\n    ('Ohio CineMotion',\n     'ohio-cinemotion',\n     'https://www.ohiocinemotion.com',\n     'full_service',\n     '1 American Road, Suite 700-A, Cleveland, OH — Contact: william@ohiocinemotion.com',\n     true),\n\n    ('Cleveland Camera Rental',\n     'cleveland-camera-rental',\n     'https://www.clevelandcamerarental.com',\n     'full_service',\n     '1419 E 40th St, Cleveland, OH — Contact: support@clevelandcamerarental.com',\n     true),\n\n    ('Dodd Camera Professional',\n     'dodd-camera',\n     'https://doddpro.com',\n     'specialty',\n     '2077 East 30th St, Cleveland, OH — Contact: estore@doddcamera.com',\n     true),\n\n    ('Liminal Space Rentals',\n     'liminal-space-rentals',\n     'https://liminalspaceproductions.com',\n     'full_service',\n     'Multi-location rental operation (Cleveland & Columbus). Contact: rent@liminalspaceproductions.com',\n     true),\n\n    ('OSV Studios',\n     'osv-studios',\n     'https://www.osvstudios.com',\n     'specialty',\n     '29605 Lorain Rd, North Olmsted, OH — Contact: csmith@osvstudios.com',\n     true),\n\n    ('Midwest Photo Rentals (MPEX)',\n     'midwest-photo-rentals',\n     'https://www.mpexrentals.com',\n     'specialty',\n     '2887 Silver Drive, Columbus, OH — Contact: rentals@mpex.com',\n     true),\n\n    ('CENCAM',\n     'cencam',\n     'https://cencam.com',\n     'full_service',\n     '1166 Cleveland Ave, Columbus, OH',\n     true),\n\n    ('Kinopicz American',\n     'kinopicz-american',\n     'https://kinopicz.com',\n     'full_service',\n     '1217 Goodale Blvd, Columbus, OH — Contact: hello@kinopicz.com',\n     true),\n\n    ('OHD Studios',\n     'ohd-studios',\n     'https://www.ohdstudios.com',\n     'specialty',\n     '350 W Johnstown Rd, Columbus, OH — Contact: info@ohdstudios.com',\n     true),\n\n    ('AllProHD',\n     'allprohd',\n     'https://allprohd.com',\n     'full_service',\n     '2900 Park Avenue West, Ontario, OH',\n     true),\n\n    ('PROCAM Rentals Cincinnati',\n     'procam-cincinnati',\n     'https://procam.com/pages/rentals-cincinnati',\n     'full_service',\n     '1014 Ohio Pike, Cincinnati, OH — Contact: cincinnati@procam.com',\n     true),\n\n    ('Akron Studio Rentals',\n     'akron-studio-rentals',\n     'https://akronstudiorentals.com',\n     'specialty',\n     'Akron, OH',\n     true),\n\n    ('Campus Camera & Imaging',\n     'campus-camera',\n     'https://www.campuscamera.net',\n     'specialty',\n     '1645 E. Main Street, Kent, OH — Contact: CampusCameraLab@hotmail.com',\n     true)\n\n  ON CONFLICT (slug) DO NOTHING;\n\n  -- ── Capture IDs for location rows ─────────────────────────────────────────\n\n  SELECT id INTO rh_ohio_cinemotion  FROM rental_house WHERE slug = 'ohio-cinemotion';\n  SELECT id INTO rh_cleveland_camera FROM rental_house WHERE slug = 'cleveland-camera-rental';\n  SELECT id INTO rh_dodd             FROM rental_house WHERE slug = 'dodd-camera';\n  SELECT id INTO rh_liminal          FROM rental_house WHERE slug = 'liminal-space-rentals';\n  SELECT id INTO rh_osv              FROM rental_house WHERE slug = 'osv-studios';\n  SELECT id INTO rh_mpex             FROM rental_house WHERE slug = 'midwest-photo-rentals';\n  SELECT id INTO rh_cencam           FROM rental_house WHERE slug = 'cencam';\n  SELECT id INTO rh_kinopicz         FROM rental_house WHERE slug = 'kinopicz-american';\n  SELECT id INTO rh_ohd              FROM rental_house WHERE slug = 'ohd-studios';\n  SELECT id INTO rh_allprohd         FROM rental_house WHERE slug = 'allprohd';\n  SELECT id INTO rh_procam           FROM rental_house WHERE slug = 'procam-cincinnati';\n  SELECT id INTO rh_akron            FROM rental_house WHERE slug = 'akron-studio-rentals';\n  SELECT id INTO rh_campus           FROM rental_house WHERE slug = 'campus-camera';\n\n  -- ── Insert locations ───────────────────────────────────────────────────────\n\n  INSERT INTO rental_house_location (rental_house_id, city, state_or_region, country) VALUES\n    (rh_ohio_cinemotion,  'Cleveland',     'OH', 'US'),\n    (rh_cleveland_camera, 'Cleveland',     'OH', 'US'),\n    (rh_dodd,             'Cleveland',     'OH', 'US'),\n    -- Liminal Space: two locations, same company\n    (rh_liminal,          'Cleveland',     'OH', 'US'),\n    (rh_liminal,          'Columbus',      'OH', 'US'),\n    (rh_osv,              'North Olmsted', 'OH', 'US'),\n    (rh_mpex,             'Columbus',      'OH', 'US'),\n    (rh_cencam,           'Columbus',      'OH', 'US'),\n    (rh_kinopicz,         'Columbus',      'OH', 'US'),\n    (rh_ohd,              'Columbus',      'OH', 'US'),\n    (rh_allprohd,         'Ontario',       'OH', 'US'),\n    (rh_procam,           'Cincinnati',    'OH', 'US'),\n    (rh_akron,            'Akron',         'OH', 'US'),\n    (rh_campus,           'Kent',          'OH', 'US')\n\n  ON CONFLICT DO NOTHING;\n\nEND $$"}	seed_ohio_rental_houses
20260409000007	{"-- Add contact_email and phone to rental_house (company-level contact info).\n-- Also add location-level overrides on rental_house_location for chains\n-- where individual offices have different contact details.\n--\n-- Backfills emails from the Ohio rental house seed (20260409000006).\n\nALTER TABLE rental_house\n  ADD COLUMN IF NOT EXISTS contact_email text,\n  ADD COLUMN IF NOT EXISTS phone         text","ALTER TABLE rental_house_location\n  ADD COLUMN IF NOT EXISTS contact_email text,\n  ADD COLUMN IF NOT EXISTS phone         text","-- ── Backfill Ohio rental house emails ────────────────────────────────────────\n\nUPDATE rental_house SET contact_email = 'william@ohiocinemotion.com'      WHERE slug = 'ohio-cinemotion'","UPDATE rental_house SET contact_email = 'support@clevelandcamerarental.com' WHERE slug = 'cleveland-camera-rental'","UPDATE rental_house SET contact_email = 'estore@doddcamera.com'            WHERE slug = 'dodd-camera'","UPDATE rental_house SET contact_email = 'rent@liminalspaceproductions.com' WHERE slug = 'liminal-space-rentals'","UPDATE rental_house SET contact_email = 'csmith@osvstudios.com'            WHERE slug = 'osv-studios'","UPDATE rental_house SET contact_email = 'rentals@mpex.com'                 WHERE slug = 'midwest-photo-rentals'","UPDATE rental_house SET contact_email = 'hello@kinopicz.com'               WHERE slug = 'kinopicz-american'","UPDATE rental_house SET contact_email = 'info@ohdstudios.com'              WHERE slug = 'ohd-studios'","UPDATE rental_house SET contact_email = 'cincinnati@procam.com'            WHERE slug = 'procam-cincinnati'","UPDATE rental_house SET contact_email = 'CampusCameraLab@hotmail.com'      WHERE slug = 'campus-camera'"}	rental_house_contact_fields
20260211000001	{"-- Demo seed: RED and Blackmagic cinema cameras\n-- Specs sourced directly from manufacturer spec sheets (April 2026).\n-- Safe to re-run: all inserts use ON CONFLICT guards.\n-- Requires: 20260211000000_seed_cinema_camera_category.sql (cinema-cameras category + spec defs)\n\nDO $$\nDECLARE\n  cat_id      UUID;\n  red_id      UUID;\n  bmd_id      UUID;\n\n  p_id        UUID;\n\n  -- spec definition IDs\n  sd_sensor_type        UUID;\n  sd_sensor_size        UUID;\n  sd_sensor_dims        UUID;\n  sd_dynamic_range      UUID;\n  sd_base_iso           UUID;\n  sd_dual_iso           UUID;\n  sd_max_fps            UUID;\n  sd_anamorphic         UUID;\n  sd_squeeze_factors    UUID;\n  sd_rec_formats        UUID;\n  sd_rec_media          UUID;\n  sd_internal_rec       UUID;\n  sd_max_res            UUID;\n  sd_internal_nd        UUID;\n  sd_lens_mount         UUID;\n  sd_flange             UUID;\n  sd_lens_meta          UUID;\n  sd_log_format         UUID;\n  sd_color_space        UUID;\n  sd_lut_support        UUID;\n  sd_timecode           UUID;\n  sd_genlock            UUID;\n  sd_sdi                UUID;\n  sd_wifi               UUID;\n  sd_ethernet           UUID;\n  sd_weight             UUID;\n  sd_dimensions         UUID;\n  sd_power_input        UUID;\n  sd_power_draw         UUID;\n  sd_body_type          UUID;\nBEGIN\n\n  -- ----------------------------------------------------------------\n  -- Prerequisites\n  -- ----------------------------------------------------------------\n  SELECT id INTO cat_id FROM product_category WHERE slug = 'cinema-cameras';\n  IF cat_id IS NULL THEN\n    RAISE EXCEPTION 'Seed failed: cinema-cameras category not found. Run 20260211000000 first.';\n  END IF;\n\n  -- Load all spec definition IDs by normalized_key\n  SELECT id INTO sd_sensor_type     FROM spec_definition WHERE normalized_key = 'cinema_sensor_type';\n  SELECT id INTO sd_sensor_size     FROM spec_definition WHERE normalized_key = 'cinema_sensor_size';\n  SELECT id INTO sd_sensor_dims     FROM spec_definition WHERE normalized_key = 'cinema_sensor_dimensions';\n  SELECT id INTO sd_dynamic_range   FROM spec_definition WHERE normalized_key = 'cinema_dynamic_range';\n  SELECT id INTO sd_base_iso        FROM spec_definition WHERE normalized_key = 'cinema_base_iso';\n  SELECT id INTO sd_dual_iso        FROM spec_definition WHERE normalized_key = 'dual_base_iso';\n  SELECT id INTO sd_max_fps         FROM spec_definition WHERE normalized_key = 'cinema_max_fps';\n  SELECT id INTO sd_anamorphic      FROM spec_definition WHERE normalized_key = 'anamorphic_desqueeze_supported';\n  SELECT id INTO sd_squeeze_factors FROM spec_definition WHERE normalized_key = 'anamorphic_squeeze_factors';\n  SELECT id INTO sd_rec_formats     FROM spec_definition WHERE normalized_key = 'cinema_recording_formats';\n  SELECT id INTO sd_rec_media       FROM spec_definition WHERE normalized_key = 'cinema_recording_media';\n  SELECT id INTO sd_internal_rec    FROM spec_definition WHERE normalized_key = 'cinema_internal_recording';\n  SELECT id INTO sd_max_res         FROM spec_definition WHERE normalized_key = 'cinema_max_resolution';\n  SELECT id INTO sd_internal_nd     FROM spec_definition WHERE normalized_key = 'cinema_internal_nd';\n  SELECT id INTO sd_lens_mount      FROM spec_definition WHERE normalized_key = 'cinema_lens_mount';\n  SELECT id INTO sd_flange          FROM spec_definition WHERE normalized_key = 'cinema_flange_focal_distance';\n  SELECT id INTO sd_lens_meta       FROM spec_definition WHERE normalized_key = 'cinema_lens_metadata';\n  SELECT id INTO sd_log_format      FROM spec_definition WHERE normalized_key = 'cinema_log_format';\n  SELECT id INTO sd_color_space     FROM spec_definition WHERE normalized_key = 'cinema_color_space';\n  SELECT id INTO sd_lut_support     FROM spec_definition WHERE normalized_key = 'cinema_lut_support';\n  SELECT id INTO sd_timecode        FROM spec_definition WHERE normalized_key = 'cinema_timecode_io';\n  SELECT id INTO sd_genlock         FROM spec_definition WHERE normalized_key = 'cinema_genlock';\n  SELECT id INTO sd_sdi             FROM spec_definition WHERE normalized_key = 'cinema_sdi_outputs';\n  SELECT id INTO sd_wifi            FROM spec_definition WHERE normalized_key = 'cinema_wifi';\n  SELECT id INTO sd_ethernet        FROM spec_definition WHERE normalized_key = 'cinema_ethernet';\n  SELECT id INTO sd_weight          FROM spec_definition WHERE normalized_key = 'cinema_weight';\n  SELECT id INTO sd_dimensions      FROM spec_definition WHERE normalized_key = 'cinema_dimensions';\n  SELECT id INTO sd_power_input     FROM spec_definition WHERE normalized_key = 'cinema_power_input';\n  SELECT id INTO sd_power_draw      FROM spec_definition WHERE normalized_key = 'cinema_power_draw';\n  SELECT id INTO sd_body_type       FROM spec_definition WHERE normalized_key = 'cinema_body_type';\n\n  -- ----------------------------------------------------------------\n  -- Brands — look up existing rows first; insert only if truly absent.\n  -- The brands table has unique constraints on both slug AND name,\n  -- so we resolve by name to avoid any slug mismatch with existing data.\n  -- ----------------------------------------------------------------\n  INSERT INTO brand (name, slug, website_url, scraping_enabled)\n  VALUES ('RED', 'red', 'https://www.red.com', TRUE)\n  ON CONFLICT (slug) DO NOTHING;\n  -- Fallback: some seeds stored the brand with a different slug\n  SELECT id INTO red_id FROM brand WHERE slug = 'red';\n  IF red_id IS NULL THEN\n    SELECT id INTO red_id FROM brand WHERE LOWER(name) = 'red';\n  END IF;\n\n  -- Blackmagic already seeded as slug='blackmagic-design'\n  INSERT INTO brand (name, slug, website_url, scraping_enabled)\n  VALUES ('Blackmagic Design', 'blackmagic-design', 'https://www.blackmagicdesign.com', TRUE)\n  ON CONFLICT (slug) DO NOTHING;\n  SELECT id INTO bmd_id FROM brand WHERE slug = 'blackmagic-design';\n  IF bmd_id IS NULL THEN\n    